};

export default App;

import React, { useState, useEffect, useMemo, ChangeEvent } from 'react';
import { Player, DbPlayer, Match, DbMatch } from './types';
import { getSupabase, saveSupabaseKey, SUPABASE_URL } from './supabaseClient';

const DEFAULT_FEE = 40;

const App: React.FC = () => {
  // --- STATE ---
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [currentTab, setCurrentTab] = useState<'financial' | 'matches' | 'stats'>('matches'); 

  // Data State
  const [players, setPlayers] = useState<Player[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);

  // Financial Specific State
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  // Connection State
  const [apiKeyModalOpen, setApiKeyModalOpen] = useState(false);
  const [apiKeyInput, setApiKeyInput] = useState('');
  const [isConnected, setIsConnected] = useState(false);

  // Inline Editing State
  const [editingDateId, setEditingDateId] = useState<string | null>(null);
  const [editingNameId, setEditingNameId] = useState<string | null>(null);
  const [editingJerseyId, setEditingJerseyId] = useState<string | null>(null);
  const [tempName, setTempName] = useState<string>('');

  // Modals State
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // Matches View Mode
  const [matchViewMode, setMatchViewMode] = useState<'upcoming' | 'history'>('upcoming');

  // MATCH RESULT MODAL STATE
  const [isMatchResultModalOpen, setIsMatchResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);
  const [manualHomeScore, setManualHomeScore] = useState(0);
  const [manualAwayScore, setManualAwayScore] = useState(0);
  const [matchPlayerStats, setMatchPlayerStats] = useState<Record<string, {goals: number}>>({});

  // Forms State
  const [newPlayerName, setNewPlayerName] = useState('');
  const [newPlayerNumber, setNewPlayerNumber] = useState('');
  const [newPlayerPhoto, setNewPlayerPhoto] = useState<string | null>(null);
  const [newPlayerPosition, setNewPlayerPosition] = useState('MEI');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [newMatchOpponent, setNewMatchOpponent] = useState('');
  const [newMatchLocation, setNewMatchLocation] = useState('');
  const [newMatchDate, setNewMatchDate] = useState(new Date().toISOString().split('T')[0]);
  const [newMatchTime, setNewMatchTime] = useState('');
  const [newMatchLocationImg, setNewMatchLocationImg] = useState<string | null>(null);

  // Edit Stats State
  const [editingStatsId, setEditingStatsId] = useState<string | null>(null);
  const [tempStats, setTempStats] = useState({ goals: 0, matchesPlayed: 0, overall: 0, position: '' });

  // --- INITIALIZATION ---

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  // Load Data
  useEffect(() => {
    const supabase = getSupabase();
    if (!supabase) {
      setApiKeyModalOpen(true);
      setLoading(false);
      return;
    }
    setIsConnected(true);
    fetchData();

    const channelPlayers = supabase.channel('realtime-players')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'players' }, () => fetchData())
      .subscribe();

    const channelMatches = supabase.channel('realtime-matches')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, () => fetchData())
      .subscribe();

    return () => {
      supabase.removeChannel(channelPlayers);
      supabase.removeChannel(channelMatches);
    };
  }, []);

  const fetchData = async () => {
    const supabase = getSupabase();
    if (!supabase) return;

    try {
      const { data: dataPlayers } = await supabase.from('players').select('*').order('name', { ascending: true });
      if (dataPlayers) {
        setPlayers(dataPlayers.map((p: any) => ({
          id: p.id.toString(),
          name: p.name,
          photoUrl: p.photo_url || 'https://via.placeholder.com/150',
          isPaid: false, 
          paymentDate: undefined,
          value: p.value,
          jerseyNumber: p.jersey_number,
          status: (p.status === 'injured' ? 'injured' : 'active') as 'active' | 'injured',
          paymentHistory: parsePaymentHistory(p.payment_date),
          position: p.position || 'MEI',
          goals: p.goals || 0,
          matchesPlayed: p.matches_played || 0,
          overall: p.overall || 75
        })));
      }

      const { data: dataMatches } = await supabase.from('matches').select('*').order('date', { ascending: true });
      if (dataMatches) {
        setMatches(dataMatches.map((m: DbMatch) => ({
          id: m.id.toString(),
          opponent: m.opponent,
          locationImg: m.location_img,
          location: m.location || '',
          date: m.date,
          time: m.time,
          homeScore: m.home_score,
          awayScore: m.away_score,
          result: m.result as any,
          isFinished: m.is_finished
        })));
      }
    } catch (error) {
      console.error("Erro ao buscar dados:", error);
    } finally {
      setLoading(false);
    }
  };

  // --- HELPERS ---

  const getMonthKey = (date: Date) => {
    const m = (date.getMonth() + 1).toString().padStart(2, '0');
    const y = date.getFullYear();
    return `${m}-${y}`;
  };

  const parsePaymentHistory = (dateStr: string | null): Record<string, string> => {
    if (!dateStr) return {};
    try {
        const parsed = JSON.parse(dateStr);
        if (typeof parsed === 'object' && parsed !== null) return parsed;
        return {};
    } catch (e) {
        return dateStr ? { [getMonthKey(new Date())]: dateStr } : {};
    }
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  const formattedDate = useMemo(() => {
    const options: Intl.DateTimeFormatOptions = { month: 'long', year: 'numeric' };
    const str = selectedDate.toLocaleDateString('pt-BR', options);
    return str.charAt(0).toUpperCase() + str.slice(1);
  }, [selectedDate]);

  const changeMonth = (increment: number) => {
    const newDate = new Date(selectedDate);
    newDate.setMonth(newDate.getMonth() + increment);
    setSelectedDate(newDate);
  };

  const getNextSundays = () => {
      const dates = [];
      let d = new Date();
      d.setDate(d.getDate() + (7 - d.getDay()) % 7);
      for(let i=0; i<6; i++) {
          dates.push(new Date(d));
          d.setDate(d.getDate() + 7);
      }
      return dates;
  };

  // --- STATS CALCULATION ---

  const currentMonthKey = getMonthKey(selectedDate);

  const playersView = useMemo(() => {
    return players.map(player => ({
        ...player,
        isPaid: !!player.paymentHistory[currentMonthKey],
        paymentDate: player.paymentHistory[currentMonthKey]
    }));
  }, [players, currentMonthKey]);

  const financialStats = useMemo(() => {
    const active = playersView.filter(p => p.status === 'active' || p.isPaid);
    const collected = playersView.reduce((acc, p) => acc + (p.isPaid ? p.value : 0), 0);
    const potential = active.reduce((acc, p) => acc + p.value, 0);
    const count = active.length;
    const paid = playersView.filter(p => p.isPaid).length;
    return { collected, potential, paid, count, progress: count > 0 ? (paid / count) * 100 : 0 };
  }, [playersView]);

  const topPayers = useMemo(() => playersView.filter(p => p.isPaid && p.status === 'active').slice(0, 3), [playersView]);

  const matchStats = useMemo(() => {
    const finished = matches.filter(m => m.isFinished);
    const wins = finished.filter(m => m.result === 'win').length;
    const draws = finished.filter(m => m.result === 'draw').length;
    const losses = finished.filter(m => m.result === 'loss').length;
    const total = finished.length;
    const goalsFor = finished.reduce((acc, m) => acc + m.homeScore, 0);
    const goalsAgainst = finished.reduce((acc, m) => acc + m.awayScore, 0);
    const goalDiff = goalsFor - goalsAgainst;

    return { 
        wins, draws, losses, total, 
        winRate: total > 0 ? Math.round((wins / total) * 100) : 0,
        goalsFor, goalsAgainst, goalDiff
    };
  }, [matches]);

  const topScorers = useMemo(() => [...players].sort((a, b) => b.goals - a.goals).slice(0, 5), [players]);

  const topAppearances = useMemo(() => [...players].sort((a, b) => b.matchesPlayed - a.matchesPlayed).slice(0, 3), [players]);

  // --- ACTIONS ---

  const handleSaveKey = (e: React.FormEvent) => {
    e.preventDefault();
    if (apiKeyInput.trim()) {
      saveSupabaseKey(apiKeyInput.trim());
      setApiKeyModalOpen(false);
    }
  };

  const togglePayment = async (id: string) => {
    const supabase = getSupabase();
    if (!supabase) return;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const newHistory = { ...player.paymentHistory };
    const isPaid = !!newHistory[currentMonthKey];

    if (isPaid) delete newHistory[currentMonthKey];
    else newHistory[currentMonthKey] = new Date().toLocaleDateString('pt-BR');

    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    await supabase.from('players').update({ payment_date: JSON.stringify(newHistory), is_paid: !isPaid }).eq('id', id);
  };

  const updatePaymentDate = async (id: string, dateValue: string) => {
    if (!dateValue) return;
    const [year, month, day] = dateValue.split('-');
    const formatted = `${day}/${month}/${year}`;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const newHistory = { ...player.paymentHistory, [currentMonthKey]: formatted };
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    setEditingDateId(null);
    const supabase = getSupabase();
    if (supabase) await supabase.from('players').update({ payment_date: JSON.stringify(newHistory) }).eq('id', id);
  };

  const handlePhotoUpload = (e: ChangeEvent<HTMLInputElement>, setter: (val: string) => void) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => setter(reader.result as string);
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const updatePlayerPhoto = async (id: string, e: ChangeEvent<HTMLInputElement>) => {
    handlePhotoUpload(e, async (base64) => {
        const supabase = getSupabase();
        if(supabase) await supabase.from('players').update({ photo_url: base64 }).eq('id', id);
        fetchData();
    });
  };

  const deletePlayer = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Remover jogador?")) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').delete().eq('id', id);
      setPlayers(prev => prev.filter(p => p.id !== id));
    }
  };

  const togglePlayerStatus = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const player = players.find(p => p.id === id);
    if(!player) return;
    const newStatus = player.status === 'active' ? 'injured' : 'active';
    const supabase = getSupabase();
    if(supabase) await supabase.from('players').update({ status: newStatus }).eq('id', id);
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
  };

  const startEditingName = (player: Player) => {
    setTempName(player.name);
    setEditingNameId(player.id);
  };

  const savePlayerName = async (id: string) => {
    if (tempName.trim()) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').update({ name: tempName.trim() }).eq('id', id);
      setPlayers(prev => prev.map(p => p.id === id ? { ...p, name: tempName.trim() } : p));
    }
    setEditingNameId(null);
  };

  const saveJerseyNumber = async (id: string, newNumber: string) => {
    const num = parseInt(newNumber);
    if (!isNaN(num)) {
         const supabase = getSupabase();
         if(supabase) await supabase.from('players').update({ jersey_number: num }).eq('id', id);
         setPlayers(prev => prev.map(p => p.id === id ? { ...p, jerseyNumber: num } : p));
    }
    setEditingJerseyId(null);
  };

  const handleAddPlayer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlayerName.trim() || !newPlayerPhoto || isSubmitting) return;

    setIsSubmitting(true);
    const supabase = getSupabase();
    if (supabase) {
        const fullPayload = {
            name: newPlayerName,
            photo_url: newPlayerPhoto,
            is_paid: false,
            value: DEFAULT_FEE,
            jersey_number: parseInt(newPlayerNumber) || 0,
            status: 'active',
            payment_date: JSON.stringify({}),
            position: newPlayerPosition,
            goals: 0,
            matches_played: 0,
            overall: 70
        };

        const { error } = await supabase.from('players').insert([fullPayload]);

        if (error) {
            console.warn("Insert completo falhou. Tentando fallback básico.", error.message);
            const basicPayload = {
                name: newPlayerName,
                photo_url: newPlayerPhoto,
                is_paid: false,
                value: DEFAULT_FEE,
                jersey_number: parseInt(newPlayerNumber) || 0,
                status: 'active',
                payment_date: JSON.stringify({})
            };
            const { error: basicError } = await supabase.from('players').insert([basicPayload]);
            if (basicError) {
                alert(`Erro ao salvar jogador: ${basicError.message}`);
                setIsSubmitting(false);
                return;
            }
        }
        await fetchData();
    }

    setNewPlayerName('');
    setNewPlayerNumber('');
    setNewPlayerPhoto(null);
    setIsAddModalOpen(false);
    setIsSubmitting(false);
  };

  const openPlayerProfile = (player: Player) => {
      setTempStats({
          goals: player.goals,
          matchesPlayed: player.matchesPlayed,
          overall: player.overall,
          position: player.position
      });
      setEditingStatsId(player.id);
  };

  const savePlayerStats = async () => {
      if(!editingStatsId) return;
      const supabase = getSupabase();
      if(supabase) {
          const { error } = await supabase.from('players').update({
              goals: tempStats.goals,
              matches_played: tempStats.matchesPlayed,
              overall: tempStats.overall,
              position: tempStats.position
          }).eq('id', editingStatsId);

          if (error) {
             alert("Erro ao atualizar estatísticas. Verifique se as colunas existem.\n" + error.message);
          } else {
             setPlayers(prev => prev.map(p => p.id === editingStatsId ? { ...p, ...tempStats } : p));
          }
      }
      setEditingStatsId(null);
  };

  const handleAddMatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if(isSubmitting) return;
    setIsSubmitting(true);

    const supabase = getSupabase();
    if(supabase) {
        if (matches.some(m => m.date === newMatchDate)) {
            if(!window.confirm("Já existe um jogo nesta data. Deseja marcar outro?")) {
                setIsSubmitting(false);
                return;
            }
        }

        const { error } = await supabase.from('matches').insert([{
            opponent: newMatchOpponent,
            location: newMatchLocation,
            date: newMatchDate,
            time: newMatchTime,
            location_img: newMatchLocationImg,
            result: 'pending',
            is_finished: false
        }]);

        if (error) {
            alert(`Erro ao criar partida: ${error.message}`);
            setIsSubmitting(false);
            return;
        }
        await fetchData();
    }
    setNewMatchOpponent('');
    setNewMatchLocation('');
    setNewMatchDate(new Date().toISOString().split('T')[0]);
    setNewMatchTime('');
    setNewMatchLocationImg(null);
    setIsAddModalOpen(false);
    setIsSubmitting(false);
  };

  const deleteMatch = async (id: string, e: React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();

      const confirmDelete = window.confirm("Tem certeza que deseja excluir esta partida?");
      if (!confirmDelete) return;

      const previousMatches = [...matches];
      setMatches(prev => prev.filter(m => m.id !== id));

      const supabase = getSupabase();
      if(!supabase) {
          setMatches(previousMatches); 
          return;
      }

      try {
          const { error } = await supabase.from('matches').delete().eq('id', parseInt(id));
          if (error) {
              alert("Erro ao excluir partida no banco de dados: " + error.message);
              setMatches(previousMatches); 
          }
      } catch (err: any) {
          alert("Ocorreu um erro ao tentar excluir: " + err.message);
          setMatches(previousMatches); 
      }
  };

  const openMatchResultModal = (match: Match) => {
      setSelectedMatch(match);
      setManualHomeScore(match.isFinished ? match.homeScore : 0);
      setManualAwayScore(match.isFinished ? match.awayScore : 0);

      const initialStats: Record<string, {goals: number}> = {};
      players.filter(p => p.status === 'active').forEach(p => {
          initialStats[p.id] = { goals: 0 };
      });
      setMatchPlayerStats(initialStats);

      setIsMatchResultModalOpen(true);
  };

  const updateMatchStat = (playerId: string, type: 'goals', delta: number) => {
      setMatchPlayerStats(prev => ({
          ...prev,
          [playerId]: {
              ...prev[playerId],
              [type]: Math.max(0, (prev[playerId]?.[type] || 0) + delta)
          }
      }));
  };

  const confirmMatchResult = async () => {
      if (!selectedMatch) return;
      const supabase = getSupabase();
      if (!supabase) return;

      setIsSubmitting(true);

      let result = 'draw';
      if (manualHomeScore > manualAwayScore) result = 'win';
      if (manualHomeScore < manualAwayScore) result = 'loss';

      const { error: matchError } = await supabase.from('matches').update({
          home_score: manualHomeScore,
          away_score: manualAwayScore,
          result: result,
          is_finished: true
      }).eq('id', parseInt(selectedMatch.id));

      if (matchError) {
          alert("Erro ao salvar placar: " + matchError.message);
          setIsSubmitting(false);
          return;
      }

      if (!selectedMatch.isFinished) {
          const updates = [];
          for (const playerId in matchPlayerStats) {
                const stats = matchPlayerStats[playerId];
                const player = players.find(p => p.id === playerId);

                if (player) {
                    updates.push(
                        supabase.from('players').update({
                            goals: (player.goals || 0) + stats.goals,
                            matches_played: (player.matchesPlayed || 0) + 1 
                        }).eq('id', playerId)
                    );
                }
          }
          if(updates.length > 0) {
            await Promise.all(updates);
          }
      }

      await fetchData(); 
      setIsMatchResultModalOpen(false);
      setIsSubmitting(false);
  };

  // --- RENDERERS ---

  const renderFinancial = () => (
    <div className="space-y-8 md:space-y-10 animation-fade-in pb-20">
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 md:gap-8">
          <div className="xl:col-span-1 bg-surface-light dark:bg-surface-dark rounded-2xl p-6 md:p-8 border border-gray-200 dark:border-gray-800 shadow-sm relative overflow-hidden group flex flex-col justify-between min-h-[200px] md:min-h-[220px]">
             <div className="absolute top-0 right-0 w-64 h-64 bg-primary/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
             <div className="relative z-10">
               <h2 className="text-muted-light dark:text-muted-dark font-medium mb-1 text-sm md:text-base">Total em Caixa ({formattedDate})</h2>
               <div className="flex items-baseline gap-2 mb-6">
                 <span className="text-4xl md:text-5xl font-bold tracking-tighter text-gray-900 dark:text-white">R$ {financialStats.collected}</span>
                 <span className="text-sm md:text-lg text-muted-light dark:text-muted-dark font-medium">/ {financialStats.potential}</span>
               </div>
             </div>
             <div className="relative z-10 mt-auto">
               <div className="flex justify-between text-sm font-semibold mb-3">
                 <span className="text-primary">{financialStats.paid} Pagos</span>
                 <span className="text-muted-light dark:text-muted-dark">{financialStats.count - financialStats.paid} Pendentes</span>
               </div>
               <div className="w-full bg-gray-200 dark:bg-gray-800 rounded-full h-3 md:h-4 overflow-hidden">
                 <div className="bg-primary h-3 md:h-4 rounded-full transition-all duration-700 ease-out" style={{ width: `${financialStats.progress}%` }}></div>
               </div>
             </div>
          </div>

          <div className="xl:col-span-2 bg-surface-light dark:bg-surface-dark rounded-2xl p-6 md:p-8 border border-gray-200 dark:border-gray-800 shadow-sm relative overflow-hidden">
              <div className="flex items-center gap-2 mb-6"><span className="material-icons-outlined text-yellow-500">emoji_events</span><h3 className="font-bold text-lg">Pagadores Rápidos</h3></div>
              <div className="flex items-end justify-around h-36 md:h-40 pb-2">
                 {[1, 0, 2].map((idx) => {
                     const p = topPayers[idx];
                     const rank = idx + 1;
                     const isFirst = rank === 1;
                     return p ? (
                        <div key={p.id} className={`flex flex-col items-center gap-2 ${isFirst ? 'mb-4' : ''}`}>
                             <div className="relative">
                                 {isFirst && <span className="absolute -top-5 md:-top-6 left-1/2 -translate-x-1/2 material-icons-outlined text-yellow-400 animate-bounce">crown</span>}
                                 <img src={p.photoUrl} className={`${isFirst ? 'w-20 h-20 md:w-24 md:h-24 border-yellow-400' : 'w-14 h-14 md:w-16 md:h-16 border-gray-400'} rounded-full border-4 object-cover`} />
                                 <div className={`absolute -bottom-3 left-1/2 -translate-x-1/2 w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${isFirst ? 'bg-yellow-400 text-black' : 'bg-gray-400 text-white'}`}>{rank}</div>
                             </div>
                             <div className="text-center mt-2"><p className="font-bold text-xs md:text-sm truncate max-w-[80px] md:max-w-[100px]">{p.name}</p></div>
                        </div>
                     ) : <div key={idx} className="w-14 h-14 md:w-16 md:h-16 rounded-full bg-gray-800/10 flex items-center justify-center text-xs opacity-30">{rank}º</div>
                 })}
              </div>
          </div>
        </div>

        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <h3 className="text-xl font-bold flex items-center gap-2">Elenco <span className="text-xs bg-gray-200 dark:bg-gray-800 px-2 py-1 rounded">{playersView.length}</span></h3>
                <div className="flex w-full md:w-auto justify-between md:justify-end items-center gap-2">
                    <div className="flex items-center gap-2 bg-surface-light dark:bg-surface-dark px-2 py-1 rounded-full border border-gray-200 dark:border-gray-700">
                        <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><span className="material-icons-outlined">chevron_left</span></button>
                        <span className="font-bold text-sm px-2">{formattedDate}</span>
                        <button onClick={() => changeMonth(1)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><span className="material-icons-outlined">chevron_right</span></button>
                    </div>
                    <button onClick={() => setIsAddModalOpen(true)} className="hidden md:flex items-center justify-center gap-2 bg-primary hover:opacity-90 text-surface-light dark:text-surface-dark font-bold px-4 py-2 rounded-xl transition-all shadow-lg shadow-primary/20 text-sm">
                        <span className="material-icons-outlined text-lg">add</span> Novo Jogador
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4 md:gap-6">
                 {playersView.map(p => (
                     <div key={p.id} className={`relative bg-surface-light dark:bg-surface-dark rounded-2xl p-4 md:p-6 flex flex-col items-center border ${p.status === 'injured' ? 'border-orange-200 dark:border-orange-900/30 opacity-90' : p.isPaid ? 'border-primary/50 shadow-lg shadow-primary/10' : 'border-gray-200 dark:border-gray-800'} transition-all group`}>

                         {/* Action Buttons: Injury & Delete (Top Right) */}
                         <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                            <button 
                                onClick={(e) => togglePlayerStatus(p.id, e)}
                                className={`p-1 rounded text-[10px] ${p.status === 'injured' ? 'bg-orange-100 text-orange-600 hover:bg-orange-200' : 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-400 hover:text-orange-500'}`}
                                title={p.status === 'injured' ? "Retornar ao elenco" : "Reportar lesão"}
                            >
                                <span className="material-icons-outlined text-sm">medical_services</span>
                            </button>
                            <button onClick={(e) => deletePlayer(p.id, e)} className="p-1 hover:bg-red-100 dark:hover:bg-red-900/50 rounded text-red-500"><span className="material-icons-outlined text-sm">delete</span></button>
                         </div>

                         {/* Photo */}
                         <div className="relative mb-3 group/img">
                             <img src={p.photoUrl} className={`w-16 h-16 md:w-20 md:h-20 rounded-full object-cover border-2 ${p.status === 'injured' ? 'border-gray-300 grayscale opacity-80' : p.isPaid ? 'border-primary border-4' : 'border-transparent border-4'}`} />
                             <label className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover/img:opacity-100 rounded-full cursor-pointer transition-opacity">
                                 <span className="material-icons-outlined text-white">camera_alt</span>
                                 <input type="file" className="hidden" onChange={(e) => updatePlayerPhoto(p.id, e)} />
                             </label>
                             <div className="absolute top-0 left-0 bg-surface-dark text-white text-xs font-bold w-5 h-5 md:w-6 md:h-6 rounded-full flex items-center justify-center border border-white">{p.jerseyNumber}</div>
                         </div>

                         {/* Name */}
                         {editingNameId === p.id ? (
                             <input autoFocus className="w-full text-center bg-transparent border-b border-primary font-bold mb-1" value={tempName} onChange={e => setTempName(e.target.value)} onBlur={() => savePlayerName(p.id)} onKeyDown={e => e.key === 'Enter' && savePlayerName(p.id)} />
                         ) : (
                             <h4 onClick={() => startEditingName(p)} className="font-bold truncate w-full text-center cursor-pointer hover:text-primary transition-colors text-base md:text-lg">{p.name}</h4>
                         )}

                         {/* Status Badge */}
                         <div className="mt-2 mb-3 flex items-center justify-center gap-2">
                            {p.status === 'injured' ? (
                                <span className="flex items-center gap-1 text-[10px] font-bold text-orange-500 bg-orange-500/10 px-2 py-1 rounded-full uppercase">
                                    <span className="material-icons-outlined text-[12px]">healing</span>
                                    Afastado
                                </span>
                            ) : p.isPaid ? (
                                <span className="flex items-center gap-1 text-[10px] font-bold text-green-600 bg-green-100 dark:bg-green-900/30 px-2 py-1 rounded-full uppercase">
                                    <span className="material-icons-outlined text-[12px]">check_circle</span>
                                    Pagou
                                </span>
                            ) : (
                                <span className="flex items-center gap-1 text-[10px] font-bold text-red-500 bg-red-100 dark:bg-red-900/30 px-2 py-1 rounded-full uppercase">
                                    <span className="material-icons-outlined text-[12px]">cancel</span>
                                    Não Pagou
                                </span>
                            )}
                         </div>

                         {/* Footer Actions */}
                         <div className="mt-auto w-full flex items-center justify-between border-t border-gray-100 dark:border-gray-700/50 pt-3">
                             <span className={`font-bold text-xs md:text-sm ${p.status === 'injured' ? 'text-gray-400 line-through' : 'text-muted-light'}`}>R$ {p.value}</span>
                             <label className={`cursor-pointer ${p.status === 'injured' ? 'opacity-50 pointer-events-none' : ''}`}>
                                 <input type="checkbox" className="sr-only peer" checked={p.isPaid} onChange={() => togglePayment(p.id)} disabled={p.status === 'injured'} />
                                 <div className="w-8 h-5 md:w-10 md:h-6 bg-gray-300 dark:bg-gray-700 rounded-full peer-checked:bg-primary transition-colors relative">
                                     <div className={`absolute top-1 left-1 bg-white w-3 h-3 md:w-4 md:h-4 rounded-full transition-transform ${p.isPaid ? 'translate-x-3 md:translate-x-4' : ''}`}></div>
                                 </div>
                             </label>
                         </div>
                     </div>
                 ))}
                 <button onClick={() => setIsAddModalOpen(true)} className="flex flex-col items-center justify-center bg-surface-light dark:bg-surface-dark border border-gray-100 dark:border-gray-800 rounded-2xl p-6 hover:shadow-lg transition-all text-muted-light group min-h-[160px]">
                     <span className="material-icons-outlined text-3xl md:text-4xl mb-2 group-hover:scale-110 transition-transform group-hover:text-primary">add_circle_outline</span>
                     <span className="font-bold text-sm group-hover:text-primary">Adicionar</span>
                 </button>
            </div>
        </div>
    </div>
  );

  const renderMatches = () => {
    const nextSundays = getNextSundays();
    const upcomingMatches = matches.filter(m => !m.isFinished).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    const finishedMatches = matches.filter(m => m.isFinished).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const displayMatches = matchViewMode === 'upcoming' ? upcomingMatches : finishedMatches;

    return (
    <div className="space-y-8 animation-fade-in pb-20">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
             <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800 flex items-center justify-between relative overflow-hidden">
                  <div className="z-10">
                      <h3 className="text-muted-light font-bold text-sm uppercase">Aproveitamento</h3>
                      <p className="text-4xl font-bold mt-2">{matchStats.winRate}%</p>
                  </div>
                  <div className="relative w-24 h-24 p-1">
                      <svg className="w-full h-full transform -rotate-90" viewBox="0 0 100 100">
                          <circle cx="50" cy="50" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-200 dark:text-gray-800" />
                          <circle cx="50" cy="50" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={251} strokeDashoffset={251 - (251 * matchStats.winRate) / 100} className="text-green-500 transition-all duration-1000" />
                      </svg>
                  </div>
             </div>

             <div className="lg:col-span-2 grid grid-cols-3 gap-2 md:gap-4">
                 <div className="bg-green-500/10 border border-green-500/20 rounded-2xl p-2 md:p-4 flex flex-col items-center justify-center">
                     <span className="text-2xl md:text-3xl font-bold text-green-500">{matchStats.wins}</span>
                     <span className="text-[10px] md:text-xs font-bold uppercase text-green-700 dark:text-green-400">Vitórias</span>
                 </div>
                 <div className="bg-gray-200/50 dark:bg-gray-700/30 border border-gray-300 dark:border-gray-700 rounded-2xl p-2 md:p-4 flex flex-col items-center justify-center">
                     <span className="text-2xl md:text-3xl font-bold text-gray-500 dark:text-gray-300">{matchStats.draws}</span>
                     <span className="text-[10px] md:text-xs font-bold uppercase text-gray-600 dark:text-gray-400">Empates</span>
                 </div>
                 <div className="bg-red-500/10 border border-red-500/20 rounded-2xl p-2 md:p-4 flex flex-col items-center justify-center">
                     <span className="text-2xl md:text-3xl font-bold text-red-500">{matchStats.losses}</span>
                     <span className="text-[10px] md:text-xs font-bold uppercase text-red-700 dark:text-red-400">Derrotas</span>
                 </div>
             </div>

             <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800 flex flex-col justify-center">
                  <h3 className="text-muted-light font-bold text-xs uppercase mb-3">Resumo da Temporada</h3>
                  <div className="flex justify-between items-end border-b border-gray-100 dark:border-gray-700 pb-2 mb-2">
                      <span className="text-xs font-bold">Jogos</span>
                      <span className="font-bold text-gray-900 dark:text-white text-lg">{matchStats.total}</span>
                  </div>
                  <div className="flex justify-between items-end border-b border-gray-100 dark:border-gray-700 pb-2 mb-2">
                      <span className="text-xs font-bold">Gols Pró</span>
                      <span className="font-bold text-green-500 text-lg">{matchStats.goalsFor}</span>
                  </div>
                  <div className="flex justify-between items-end border-b border-gray-100 dark:border-gray-700 pb-2 mb-2">
                      <span className="text-xs font-bold">Gols Contra</span>
                      <span className="font-bold text-red-500 text-lg">{matchStats.goalsAgainst}</span>
                  </div>
                  <div className="flex justify-between items-end">
                      <span className="text-xs font-bold">Saldo</span>
                      <span className={`font-bold text-lg ${matchStats.goalDiff >= 0 ? 'text-primary' : 'text-red-500'}`}>{matchStats.goalDiff > 0 ? '+' : ''}{matchStats.goalDiff}</span>
                  </div>
             </div>
        </div>

        <div className="space-y-4">
            <h3 className="text-lg font-bold flex items-center gap-2"><span className="material-icons-outlined text-primary">event_available</span> Domingos de Jogo</h3>
            <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide">
                {nextSundays.map((d, i) => {
                    const dateStr = d.toISOString().split('T')[0];
                    const isBooked = matches.some(m => m.date === dateStr);
                    return (
                        <div key={i} className={`flex-shrink-0 w-20 h-24 rounded-2xl flex flex-col items-center justify-center border-2 transition-all ${isBooked ? 'bg-primary border-primary text-white shadow-lg shadow-primary/30' : 'bg-surface-light dark:bg-surface-dark border-gray-200 dark:border-gray-800 text-muted-light'}`}>
                             <span className="text-xs font-bold uppercase opacity-80">{d.toLocaleDateString('pt-BR', {month: 'short'}).replace('.','')}</span>
                             <span className="text-3xl font-bold my-1">{d.getDate()}</span>
                             <span className="text-[10px] font-bold uppercase">{isBooked ? 'JOGO' : 'LIVRE'}</span>
                        </div>
                    );
                })}
            </div>
        </div>

        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-4">
                <div className="flex items-center gap-4">
                    <h3 className="text-lg font-bold">Agenda de Jogos</h3>
                    <div className="flex bg-gray-200 dark:bg-surface-dark p-1 rounded-lg">
                        <button onClick={() => setMatchViewMode('upcoming')} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${matchViewMode === 'upcoming' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Próximos</button>
                        <button onClick={() => setMatchViewMode('history')} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${matchViewMode === 'history' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Histórico</button>
                    </div>
                </div>

                <button onClick={() => setIsAddModalOpen(true)} className="hidden md:flex bg-primary hover:opacity-90 text-white px-4 py-2 rounded-xl font-bold text-sm shadow-lg shadow-primary/20 items-center gap-2">
                    <span className="material-icons-outlined text-lg">add</span> Nova Partida
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {displayMatches.map(m => (
                    <div 
                        key={m.id} 
                        className={`relative rounded-2xl overflow-hidden flex flex-col shadow-sm animation-fade-in group transition-all duration-300
                            ${matchViewMode === 'upcoming' 
                                ? 'bg-gradient-to-br from-primary to-orange-500 dark:from-primary dark:to-orange-500 text-white shadow-lg' 
                                : 'bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-800 grayscale opacity-80 hover:grayscale-0 hover:opacity-100'
                            }`}
                    >
                        <div className="absolute top-3 right-3 z-50">
                            <button onClick={(e) => deleteMatch(m.id, e)} className={`p-2 rounded-full transition-colors cursor-pointer ${matchViewMode === 'upcoming' ? 'text-white/80 hover:bg-white/20 hover:text-white' : 'text-gray-400 hover:text-red-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}>
                                <span className="material-icons-outlined text-lg">delete_outline</span>
                            </button>
                        </div>

                        {/* Status Badge */}
                        <div className="absolute top-4 left-4 z-40">
                             {m.isFinished ? (
                                 <span className={`text-[10px] font-bold uppercase px-2 py-1 rounded backdrop-blur-md shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/20 text-white' : (m.result === 'win' ? 'bg-green-100 text-green-600' : m.result === 'loss' ? 'bg-red-100 text-red-600' : 'bg-gray-100 text-gray-600')}`}>
                                     {m.result === 'win' ? 'Vitória' : m.result === 'loss' ? 'Derrota' : 'Empate'}
                                 </span>
                             ) : (
                                 <span className="text-[10px] font-bold uppercase px-2 py-1 rounded bg-white/20 text-white backdrop-blur-md shadow-sm animate-pulse">Em Breve</span>
                             )}
                        </div>

                        <div className="p-6 pt-14 flex items-center justify-between">
                             <div className="flex flex-col items-center gap-2 w-1/3">
                                 <img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10 md:w-14 md:h-14 object-contain drop-shadow-md" />
                                 <span className={`font-bold text-xs md:text-sm hidden sm:block ${matchViewMode === 'upcoming' ? 'text-white' : ''}`}>Pesadão</span>
                             </div>

                             <div className="flex flex-col items-center justify-center w-1/3">
                                 <div className={`px-2 md:px-4 py-1 md:py-2 rounded-lg font-mono text-3xl md:text-4xl font-bold tracking-widest mb-2 ${matchViewMode === 'upcoming' ? 'text-white' : 'text-gray-900 dark:text-white'}`}>
                                     {m.isFinished ? `${m.homeScore}-{m.awayScore}` : 'VS'}
                                 </div>

                                 <div className={`flex flex-col items-center gap-1 text-[10px] md:text-xs font-bold uppercase ${matchViewMode === 'upcoming' ? 'text-white/90' : 'text-muted-light'}`}>
                                     <div className="flex items-center gap-1 bg-black/10 dark:bg-white/5 px-2 py-0.5 rounded-full">
                                        <span className="material-icons-outlined text-[12px]">calendar_today</span>
                                        <span>{new Date(m.date + 'T00:00:00').toLocaleDateString('pt-BR')}</span>
                                     </div>
                                     <div className="flex items-center gap-1">
                                        <span>{m.time.slice(0,5)}</span>
                                        {m.location && (
                                            <>
                                                <span>•</span>
                                                <span className="flex items-center gap-0.5"><span className="material-icons-outlined text-[10px]">place</span>{m.location}</span>
                                            </>
                                        )}
                                     </div>
                                 </div>
                             </div>

                             <div className="flex flex-col items-center gap-2 w-1/3">
                                 <div className={`w-10 h-10 md:w-14 md:h-14 rounded-full flex items-center justify-center overflow-hidden shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/90' : 'bg-gray-100 dark:bg-gray-700'}`}>
                                     {m.locationImg ? <img src={m.locationImg} className="w-full h-full object-cover" /> : <span className="material-icons-outlined text-gray-400">sports_soccer</span>}
                                 </div>
                                 <span className={`font-bold text-xs md:text-sm truncate max-w-full text-center ${matchViewMode === 'upcoming' ? 'text-white' : ''}`}>{m.opponent}</span>
                             </div>
                        </div>

                        <div className={`p-3 border-t flex justify-center ${matchViewMode === 'upcoming' ? 'border-white/10 bg-white/5' : 'border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-surface-dark/50'}`}>
                             <button onClick={() => openMatchResultModal(m)} className={`w-full py-3 rounded-lg text-xs font-bold uppercase text-center flex items-center justify-center gap-2 transition-all shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/20 text-white hover:bg-white hover:text-primary' : 'bg-white dark:bg-surface-dark border border-gray-200 dark:border-gray-700 hover:bg-primary hover:text-white hover:border-primary'}`}>
                                 <span className="material-icons-outlined text-[14px]">{m.isFinished ? "edit" : "sports_score"}</span>
                                 {m.isFinished ? "Editar Placar / Súmula" : "Informar Placar / Súmula"}
                             </button>
                        </div>
                    </div>
                ))}

                {displayMatches.length === 0 && (
                    <div className="col-span-full text-center py-10 bg-surface-light dark:bg-surface-dark rounded-2xl border border-dashed border-gray-200 dark:border-gray-800 flex flex-col items-center">
                        <span className="material-icons-outlined text-4xl text-muted-light mb-2">event_busy</span>
                        <p className="text-muted-light font-bold">Nenhum jogo encontrado nesta seção.</p>
                        {matchViewMode === 'upcoming' && (
                            <button onClick={() => setIsAddModalOpen(true)} className="mt-4 text-primary font-bold text-sm hover:underline">
                                Agendar agora
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
    </div>
  );
  };

  const renderStats = () => {
    // Find last finished match to display in cards
    const lastMatch = matches.filter(m => m.isFinished).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

    const renderRankingItem = (p: Player, i: number, value: number, type: 'goals' | 'matches') => {
        let rankColors = "border-gray-100 dark:border-gray-800 bg-surface-light dark:bg-surface-dark";
        let textRank = "text-muted-light";
        let icon = null;

        if (i === 0) {
            rankColors = "border-yellow-500/50 bg-gradient-to-r from-yellow-500/10 to-transparent";
            textRank = "text-yellow-500";
            icon = "emoji_events";
        } else if (i === 1) {
            rankColors = "border-gray-400/50 bg-gradient-to-r from-gray-400/10 to-transparent";
            textRank = "text-gray-400";
        } else if (i === 2) {
            rankColors = "border-orange-700/50 bg-gradient-to-r from-orange-700/10 to-transparent";
            textRank = "text-orange-700";
        }

        return (
            <div key={p.id} className={`flex items-center justify-between p-4 md:p-3 rounded-xl border ${rankColors} transition-all`}>
                <div className="flex items-center gap-4">
                    <div className={`flex flex-col items-center justify-center w-8 ${textRank}`}>
                        {i === 0 && icon ? <span className="material-icons-outlined text-xl mb-1">{icon}</span> : <span className="font-black text-xl md:text-lg">{i + 1}</span>}
                    </div>
                    <img src={p.photoUrl} className="w-14 h-14 md:w-10 md:h-10 rounded-full object-cover border-2 border-white/10 shadow-sm" />
                    <div>
                        <span className="font-bold text-base md:text-sm block">{p.name}</span>
                        <span className="text-xs text-muted-light font-bold bg-black/5 dark:bg-white/5 px-2 py-0.5 rounded-full">{p.position}</span>
                    </div>
                </div>
                <div className="flex flex-col items-end">
                    <span className={`text-2xl md:text-xl font-black ${textRank}`}>{value}</span>
                    <span className="text-[10px] uppercase font-bold text-muted-light">{type === 'goals' ? 'Gols' : 'Jogos'}</span>
                </div>
            </div>
        );
    };

    return (
    <div className="space-y-8 animation-fade-in pb-20">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800">
                <h3 className="font-bold mb-4 flex items-center gap-2 text-primary text-lg"><span className="material-icons-outlined">sports_soccer</span> Artilheiros</h3>
                <div className="space-y-3">
                    {topScorers.map((p, i) => renderRankingItem(p, i, p.goals, 'goals'))}
                    {topScorers.length === 0 && <p className="text-muted-light text-sm">Sem dados</p>}
                </div>
            </div>

            <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800">
                <h3 className="font-bold mb-4 flex items-center gap-2 text-primary text-lg"><span className="material-icons-outlined">history</span> Participações</h3>
                <div className="space-y-3">
                    {topAppearances.map((p, i) => renderRankingItem(p, i, p.matchesPlayed, 'matches'))}
                    {topAppearances.length === 0 && <p className="text-muted-light text-sm">Sem dados</p>}
                </div>
            </div>
        </div>

        <h3 className="text-xl font-bold mt-8">Jogadores</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
             {players.map(p => (
                 <div 
                    key={p.id} 
                    onClick={() => openPlayerProfile(p)} 
                    className="cursor-pointer group relative bg-surface-light dark:bg-surface-dark rounded-[2rem] border border-gray-200 dark:border-gray-800 p-5 transition-all duration-300 hover:shadow-2xl hover:-translate-y-1 hover:border-primary/40 overflow-hidden"
                 >
                      {/* Hover Decoration Background */}
                      <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-full blur-3xl -mr-16 -mt-16 transition-opacity opacity-0 group-hover:opacity-100 pointer-events-none"></div>

                      {/* Header: Number & Position */}
                      <div className="flex justify-between items-start mb-2 relative z-10">
                          <span className="font-display font-black text-3xl text-gray-100 dark:text-gray-800 group-hover:text-primary/10 transition-colors">
                              {p.jerseyNumber}
                          </span>
                          <span className="px-3 py-1 rounded-full bg-gray-100 dark:bg-gray-800/80 text-[10px] font-bold uppercase tracking-wider text-muted-light group-hover:bg-primary group-hover:text-white transition-colors shadow-sm backdrop-blur-sm">
                              {p.position}
                          </span>
                      </div>

                      {/* Center: Image & Name */}
                      <div className="flex flex-col items-center mb-6 relative z-10">
                          <div className="relative mb-3">
                              {/* Glow effect */}
                              <div className="absolute inset-0 bg-primary/20 rounded-full blur-md opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                              <img 
                                src={p.photoUrl} 
                                className="relative w-28 h-28 rounded-full object-cover border-4 border-surface-light dark:border-surface-dark shadow-lg group-hover:border-primary/50 transition-colors" 
                              />
                              {/* Status indicator */}
                              <div className={`absolute bottom-1 right-1 w-5 h-5 rounded-full border-4 border-surface-light dark:border-surface-dark ${p.status === 'active' ? 'bg-green-500' : 'bg-red-500'} shadow-sm`}></div>
                          </div>
                          <h4 className="font-bold text-xl text-center truncate w-full px-2 text-gray-900 dark:text-gray-100">{p.name}</h4>
                      </div>

                      {/* Footer: Last Match Info */}
                      <div className="relative z-10 mt-auto">
                          <div className="bg-gray-50 dark:bg-black/20 rounded-2xl p-3 border border-gray-100 dark:border-gray-800/50 group-hover:bg-white dark:group-hover:bg-gray-800/50 transition-colors">
                              <p className="text-[9px] uppercase font-bold text-muted-light mb-2 text-center tracking-wider">Último Jogo</p>
                              {lastMatch ? (
                                  <div className="flex items-center justify-between">
                                      <div className="flex items-center gap-2 overflow-hidden">
                                          <div className={`w-2 h-8 rounded-full flex-shrink-0 ${lastMatch.result === 'win' ? 'bg-green-500' : lastMatch.result === 'loss' ? 'bg-red-500' : 'bg-gray-400'}`}></div>
                                          <div className="flex flex-col min-w-0">
                                              <span className="text-xs font-bold truncate">{lastMatch.opponent}</span>
                                              <span className={`text-[9px] font-bold uppercase ${lastMatch.result === 'win' ? 'text-green-600' : lastMatch.result === 'loss' ? 'text-red-500' : 'text-gray-500'}`}>
                                                  {lastMatch.result === 'win' ? 'Vitória' : lastMatch.result === 'loss' ? 'Derrota' : 'Empate'}
                                              </span>
                                          </div>
                                      </div>
                                      <span className="font-mono text-xs font-black bg-white dark:bg-black/40 px-2 py-1 rounded-lg border border-gray-100 dark:border-gray-700 shadow-sm">
                                          {lastMatch.homeScore}-{lastMatch.awayScore}
                                      </span>
                                  </div>
                              ) : (
                                  <div className="text-center text-xs text-muted-light italic py-1">Sem histórico recente</div>
                              )}
                          </div>
                      </div>
                 </div>
             ))}
        </div>
    </div>
    );
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark text-gray-900 dark:text-gray-100 font-display p-4 md:p-8 transition-colors duration-300 pb-24 md:pb-8">

        {/* Navigation Header */}
        <div className="max-w-7xl mx-auto flex flex-row items-center justify-between mb-4 md:mb-8 gap-4 sticky top-0 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur z-40 py-2 md:py-4">
             <div className="flex items-center gap-3">
                 <img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10 md:w-12 md:h-12 object-contain" />
                 <div>
                     <h1 className="text-lg md:text-xl font-bold tracking-tight">Pesadão F.C<span className="text-primary">.</span></h1>
                     <div className={`text-[10px] font-bold uppercase tracking-wider flex items-center gap-1 ${isConnected ? 'text-green-500' : 'text-red-500'}`}>
                         <span className={`w-1.5 h-1.5 rounded-full ${isConnected ? 'bg-green-500' : 'bg-red-500'}`}></span>
                         {isConnected ? 'Online' : 'Offline'}
                     </div>
                 </div>
             </div>

             {/* Desktop Navigation */}
             <nav className="hidden md:flex bg-gray-200 dark:bg-surface-dark p-1.5 rounded-full">
                 <button onClick={() => setCurrentTab('financial')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${currentTab === 'financial' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Financeiro</button>
                 <button onClick={() => setCurrentTab('matches')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${currentTab === 'matches' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Jogos</button>
                 <button onClick={() => setCurrentTab('stats')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${currentTab === 'stats' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Jogadores</button>
             </nav>

             <button onClick={toggleTheme} className="w-10 h-10 rounded-full bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-700 flex items-center justify-center hover:text-primary transition-colors">
                 <span className="material-icons-outlined">{theme === 'dark' ? 'light_mode' : 'dark_mode'}</span>
             </button>
        </div>

        <main className="max-w-7xl mx-auto">
             {currentTab === 'financial' && renderFinancial()}
             {currentTab === 'matches' && renderMatches()}
             {currentTab === 'stats' && renderStats()}
        </main>

        {/* Mobile Bottom Navigation */}
        <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-surface-light/90 dark:bg-surface-dark/90 backdrop-blur-xl border-t border-gray-200 dark:border-gray-800 p-2 z-50 flex justify-around items-center safe-area-bottom pb-4 shadow-[0_-5px_20px_rgba(0,0,0,0.1)]">
             <button onClick={() => setCurrentTab('financial')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg transition-colors ${currentTab === 'financial' ? 'text-primary' : 'text-muted-light hover:text-gray-900 dark:hover:text-gray-300'}`}>
                 <span className="material-icons-outlined mb-1">attach_money</span>
                 <span className="text-[10px] font-bold uppercase">Financeiro</span>
             </button>
             <button onClick={() => setCurrentTab('matches')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg transition-colors ${currentTab === 'matches' ? 'text-primary' : 'text-muted-light hover:text-gray-900 dark:hover:text-gray-300'}`}>
                 <span className="material-icons-outlined mb-1">sports_soccer</span>
                 <span className="text-[10px] font-bold uppercase">Jogos</span>
             </button>
             <button onClick={() => setCurrentTab('stats')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg transition-colors ${currentTab === 'stats' ? 'text-primary' : 'text-muted-light hover:text-gray-900 dark:hover:text-gray-300'}`}>
                 <span className="material-icons-outlined mb-1">groups</span>
                 <span className="text-[10px] font-bold uppercase">Jogadores</span>
             </button>
        </nav>

        {/* Dynamic Add Modal */}
        {isAddModalOpen && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
                <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 w-full max-w-md shadow-2xl border border-gray-200 dark:border-gray-700 overflow-y-auto max-h-[90vh]">
                    <div className="flex justify-between items-center mb-6 border-b border-gray-100 dark:border-gray-800 pb-4">
                        <h3 className="font-bold text-xl">{currentTab === 'matches' ? 'Nova Partida' : 'Novo Jogador'}</h3>
                        <button onClick={() => setIsAddModalOpen(false)}><span className="material-icons-outlined">close</span></button>
                    </div>

                    {currentTab === 'matches' ? (
                        <form onSubmit={handleAddMatch} className="space-y-4">
                            <div>
                                <label className="text-xs font-bold uppercase text-muted-light dark:text-muted-dark ml-1">Adversário</label>
                                <input type="text" placeholder="Ex: Real Madrid" value={newMatchOpponent} onChange={e => setNewMatchOpponent(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary focus:border-primary" />
                            </div>

                            <div>
                                <label className="text-xs font-bold uppercase text-muted-light dark:text-muted-dark ml-1">Local</label>
                                <input type="text" placeholder="Ex: Arena XP" value={newMatchLocation} onChange={e => setNewMatchLocation(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary focus:border-primary" />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold uppercase text-muted-light dark:text-muted-dark ml-1">Data</label>
                                    <input type="date" value={newMatchDate} onChange={e => setNewMatchDate(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary focus:border-primary" />
                                </div>
                                <div>
                                    <label className="text-xs font-bold uppercase text-muted-light dark:text-muted-dark ml-1">Horário</label>
                                    <input type="time" value={newMatchTime} onChange={e => setNewMatchTime(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary focus:border-primary" />
                                </div>
                            </div>

                            <button type="submit" disabled={!newMatchOpponent || !newMatchDate} className="w-full mt-4 bg-primary text-white font-bold py-3 rounded-xl hover:opacity-90 shadow-lg shadow-primary/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed">
                                Agendar Jogo
                            </button>
                        </form>
                    ) : (
                        <form onSubmit={handleAddPlayer} className="space-y-4">
                            <div className="flex justify-center mb-6">
                                <div className="relative group w-32 h-32">
                                    <div className="w-full h-full rounded-full bg-gray-100 dark:bg-gray-800 border-2 border-dashed border-gray-300 dark:border-gray-600 flex items-center justify-center overflow-hidden hover:border-primary transition-colors">
                                        {newPlayerPhoto ? (
                                            <img src={newPlayerPhoto} className="w-full h-full object-cover" />
                                        ) : (
                                            <span className="material-icons-outlined text-muted-dark text-4xl">add_a_photo</span>
                                        )}
                                    </div>
                                    <label className="absolute inset-0 cursor-pointer rounded-full">
                                        <input type="file" accept="image/*" onChange={(e) => handlePhotoUpload(e, setNewPlayerPhoto)} className="hidden" />
                                    </label>
                                </div>
                            </div>

                            <div>
                                <label className="text-xs font-bold uppercase text-muted-light dark:text-muted-dark ml-1">Nome Completo</label>
                                <input type="text" value={newPlayerName} onChange={e => setNewPlayerName(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary focus:border-primary" />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold uppercase text-muted-light dark:text-muted-dark ml-1">Camisa</label>
                                    <input type="number" value={newPlayerNumber} onChange={e => setNewPlayerNumber(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary focus:border-primary" />
                                </div>
                                <div>
                                    <label className="text-xs font-bold uppercase text-muted-light dark:text-muted-dark ml-1">Posição</label>
                                    <select value={newPlayerPosition} onChange={e => setNewPlayerPosition(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary focus:border-primary">
                                        <option value="GOL">Goleiro</option>
                                        <option value="ZAG">Zagueiro</option>
                                        <option value="LAT">Lateral</option>
                                        <option value="VOL">Volante</option>
                                        <option value="MEI">Meia</option>
                                        <option value="ATA">Atacante</option>
                                    </select>
                                </div>
                            </div>

                            <button type="submit" disabled={!newPlayerName || !newPlayerPhoto} className="w-full mt-4 bg-primary text-white font-bold py-3 rounded-xl hover:opacity-90 shadow-lg shadow-primary/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed">
                                Salvar Jogador
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}

      {/* MATCH RESULT MODAL */}
      {isMatchResultModalOpen && selectedMatch && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
           <div className="bg-surface-light dark:bg-surface-dark rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl border border-gray-700">
               {/* Header */}
               <div className="p-6 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-black/20">
                    <div>
                        <h2 className="text-xl font-bold">Súmula da Partida</h2>
                        <p className="text-sm text-muted-light">{new Date(selectedMatch.date + 'T00:00:00').toLocaleDateString('pt-BR')} - {selectedMatch.opponent}</p>
                    </div>
                    <button onClick={() => setIsMatchResultModalOpen(false)} className="p-2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"><span className="material-icons-outlined">close</span></button>
               </div>

               {/* Score Inputs */}
               <div className="p-8 flex justify-center items-center gap-4 md:gap-8 bg-surface-light dark:bg-surface-dark">
                    <div className="text-center">
                        <img src="https://i.imgur.com/GSj0ZPy.png" className="w-12 h-12 md:w-16 md:h-16 object-contain mx-auto mb-2" />
                        <h3 className="font-bold text-xs md:text-sm">PESADÃO</h3>
                        <input type="number" min="0" value={manualHomeScore} onChange={(e) => setManualHomeScore(parseInt(e.target.value) || 0)} className="mt-2 w-16 h-16 md:w-20 md:h-20 text-center text-3xl md:text-4xl font-bold bg-gray-100 dark:bg-black/30 border-2 border-gray-200 dark:border-gray-700 rounded-xl focus:border-primary focus:ring-0" />
                    </div>
                    <span className="text-2xl md:text-4xl font-bold text-muted-light">X</span>
                    <div className="text-center">
                        <div className="w-12 h-12 md:w-16 md:h-16 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center mx-auto mb-2 overflow-hidden">
                            {selectedMatch.locationImg ? <img src={selectedMatch.locationImg} className="w-full h-full object-cover" /> : <span className="material-icons-outlined">sports_soccer</span>}
                        </div>
                        <h3 className="font-bold text-xs md:text-sm truncate max-w-[80px] md:max-w-[100px]">{selectedMatch.opponent}</h3>
                         <input type="number" min="0" value={manualAwayScore} onChange={(e) => setManualAwayScore(parseInt(e.target.value) || 0)} className="mt-2 w-16 h-16 md:w-20 md:h-20 text-center text-3xl md:text-4xl font-bold bg-gray-100 dark:bg-black/30 border-2 border-gray-200 dark:border-gray-700 rounded-xl focus:border-primary focus:ring-0" />
                    </div>
               </div>

               {/* Stats Selection (Enabled even if previously finished to allow edits) */}
               <div className="flex-1 overflow-y-auto p-6 bg-gray-50 dark:bg-black/10">
                   <h4 className="font-bold text-sm uppercase text-muted-light mb-4 flex items-center gap-2"><span className="material-icons-outlined">analytics</span> Estatísticas dos Jogadores</h4>

                   <div className="space-y-2">
                       {players.filter(p => p.status === 'active').map(p => (
                           <div key={p.id} className="flex items-center justify-between p-3 bg-white dark:bg-surface-dark rounded-xl border border-gray-200 dark:border-gray-800 shadow-sm">
                               <div className="flex items-center gap-3">
                                   <img src={p.photoUrl} className="w-10 h-10 rounded-full object-cover" />
                                   <div>
                                       <p className="font-bold text-sm">{p.name}</p>
                                       <p className="text-[10px] text-muted-light">#{p.jerseyNumber}</p>
                                   </div>
                               </div>

                               <div className="flex gap-4">
                                   <div className="flex flex-col items-center">
                                       <span className="text-[10px] font-bold uppercase text-muted-light mb-1">Gols</span>
                                       <div className="flex items-center gap-2 bg-gray-100 dark:bg-gray-800 rounded-lg p-1">
                                           <button onClick={() => updateMatchStat(p.id, 'goals', -1)} className="w-6 h-6 flex items-center justify-center hover:bg-gray-300 dark:hover:bg-gray-700 rounded">-</button>
                                           <span className="w-4 text-center font-bold text-primary">{matchPlayerStats[p.id]?.goals || 0}</span>
                                           <button onClick={() => updateMatchStat(p.id, 'goals', 1)} className="w-6 h-6 flex items-center justify-center hover:bg-gray-300 dark:hover:bg-gray-700 rounded">+</button>
                                       </div>
                                   </div>
                               </div>
                           </div>
                       ))}
                   </div>
               </div>

               {/* Footer */}
               <div className="p-6 border-t border-gray-200 dark:border-gray-700 bg-surface-light dark:bg-surface-dark">
                   <button onClick={confirmMatchResult} disabled={isSubmitting} className="w-full py-4 bg-primary text-white font-bold rounded-xl shadow-lg shadow-primary/20 hover:opacity-90 transition-all text-lg flex items-center justify-center gap-2">
                       {isSubmitting ? 'Salvando...' : <><span className="material-icons-outlined">save</span> Confirmar Resultado</>}
                   </button>
               </div>
           </div>
        </div>
      )}

      {/* NEW PLAYER PROFILE MODAL (REPLACES OLD EDIT MODAL) */}
      {editingStatsId && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
              <div className="bg-surface-light dark:bg-surface-dark rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl border border-gray-200 dark:border-gray-700">
                  {/* Header with Close */}
                  <div className="p-4 border-b border-gray-200 dark:border-gray-700 flex justify-end">
                      <button onClick={() => setEditingStatsId(null)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"><span className="material-icons-outlined">close</span></button>
                  </div>

                  <div className="flex-1 overflow-y-auto">
                      {/* Player Hero Section */}
                      <div className="flex flex-col items-center pt-4 pb-8 px-6 bg-gradient-to-b from-transparent to-gray-50 dark:to-black/20">
                          <div className="relative mb-4">
                              <img 
                                src={players.find(p => p.id === editingStatsId)?.photoUrl} 
                                className="w-32 h-32 rounded-full object-cover border-4 border-primary shadow-2xl" 
                              />
                              <div className="absolute -bottom-3 left-1/2 -translate-x-1/2 bg-surface-dark text-white font-bold px-3 py-1 rounded-full text-sm border border-gray-600 shadow-md">
                                  {players.find(p => p.id === editingStatsId)?.position}
                              </div>
                          </div>
                          <h2 className="text-2xl font-bold">{players.find(p => p.id === editingStatsId)?.name}</h2>
                          <p className="text-muted-light font-bold">Camisa #{players.find(p => p.id === editingStatsId)?.jerseyNumber}</p>
                      </div>

                      {/* Stats Editor / Display */}
                      <div className="grid grid-cols-2 gap-4 px-6 py-6 border-t border-b border-gray-200 dark:border-gray-700">
                          <div className="flex flex-col items-center bg-gray-50 dark:bg-black/20 p-4 rounded-2xl">
                              <span className="text-xs font-bold uppercase text-muted-light mb-2">Gols</span>
                              <div className="flex items-center gap-3">
                                  <button onClick={() => setTempStats(prev => ({...prev, goals: Math.max(0, prev.goals - 1)}))} className="w-8 h-8 flex items-center justify-center bg-white dark:bg-gray-700 rounded-full shadow-sm hover:bg-gray-100 dark:hover:bg-gray-600 font-bold">-</button>
                                  <span className="text-3xl font-bold text-primary">{tempStats.goals}</span>
                                  <button onClick={() => setTempStats(prev => ({...prev, goals: prev.goals + 1}))} className="w-8 h-8 flex items-center justify-center bg-white dark:bg-gray-700 rounded-full shadow-sm hover:bg-gray-100 dark:hover:bg-gray-600 font-bold">+</button>
                              </div>
                          </div>
                          <div className="flex flex-col items-center bg-gray-50 dark:bg-black/20 p-4 rounded-2xl">
                              <span className="text-xs font-bold uppercase text-muted-light mb-2">Jogos</span>
                              <div className="flex items-center gap-3">
                                  <button onClick={() => setTempStats(prev => ({...prev, matchesPlayed: Math.max(0, prev.matchesPlayed - 1)}))} className="w-8 h-8 flex items-center justify-center bg-white dark:bg-gray-700 rounded-full shadow-sm hover:bg-gray-100 dark:hover:bg-gray-600 font-bold">-</button>
                                  <span className="text-3xl font-bold text-gray-900 dark:text-white">{tempStats.matchesPlayed}</span>
                                  <button onClick={() => setTempStats(prev => ({...prev, matchesPlayed: prev.matchesPlayed + 1}))} className="w-8 h-8 flex items-center justify-center bg-white dark:bg-gray-700 rounded-full shadow-sm hover:bg-gray-100 dark:hover:bg-gray-600 font-bold">+</button>
                              </div>
                          </div>
                      </div>

                      {/* Match History (Visual Context) */}
                      <div className="px-6 py-6">
                          <h4 className="font-bold text-sm uppercase text-muted-light mb-4 flex items-center gap-2"><span className="material-icons-outlined">history</span> Presença em Jogos</h4>
                          <div className="space-y-3">
                              {matches.filter(m => m.isFinished).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 5).map(m => (
                                  <div key={m.id} className="flex justify-between items-center p-3 bg-gray-50 dark:bg-black/20 rounded-xl border border-gray-100 dark:border-gray-800">
                                      <div className="flex items-center gap-3">
                                          <div className={`w-2 h-10 rounded-full ${m.result === 'win' ? 'bg-green-500' : m.result === 'loss' ? 'bg-red-500' : 'bg-gray-500'}`}></div>
                                          <div>
                                              <p className="font-bold text-sm">{m.opponent}</p>
                                              <p className="text-[10px] text-muted-light uppercase">{new Date(m.date + 'T00:00:00').toLocaleDateString('pt-BR')}</p>
                                          </div>
                                      </div>
                                      <div className="font-mono font-bold text-lg bg-white dark:bg-surface-dark px-3 py-1 rounded-lg border border-gray-200 dark:border-gray-700 shadow-sm">
                                          {m.homeScore}-{m.awayScore}
                                      </div>
                                  </div>
                              ))}
                              {matches.filter(m => m.isFinished).length === 0 && (
                                  <p className="text-center text-muted-light text-xs italic py-4">Nenhuma partida finalizada registrada.</p>
                              )}
                          </div>
                      </div>
                  </div>

                  <div className="p-4 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-black/10 flex justify-between items-center">
                      <button onClick={() => setEditingStatsId(null)} className="px-6 py-3 rounded-xl font-bold text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-white transition-colors">Cancelar</button>
                      <button onClick={savePlayerStats} className="px-8 py-3 bg-primary text-white font-bold rounded-xl shadow-lg hover:opacity-90 transition-opacity">Salvar Alterações</button>
                  </div>
              </div>
          </div>
      )}

      {apiKeyModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
            <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-8 w-full max-w-md shadow-2xl border border-gray-200 dark:border-gray-700 text-center">
                <span className="material-icons-outlined text-4xl text-primary mb-2">cloud_off</span>
                <h2 className="text-2xl font-bold">Erro de Conexão</h2>
                <p className="text-sm mt-2">Verifique a API Key no código.</p>
                <form onSubmit={handleSaveKey} className="mt-4"><input type="text" value={apiKeyInput} onChange={e => setApiKeyInput(e.target.value)} className="w-full p-2 rounded bg-gray-800 border border-gray-700" placeholder="Insira a chave manualmente" /><button className="mt-2 w-full bg-primary py-2 rounded font-bold">Salvar</button></form>
            </div>
        </div>
      )}
    </div>
  );
};

export default App;

export interface Player {
  id: string;
  name: string;
  photoUrl: string;
  isPaid: boolean;
  paymentDate?: string;
  value: number;
  jerseyNumber: number;
  status: 'active' | 'injured';
  paymentHistory: Record<string, string>; // Stores { "MM-YYYY": "DD/MM/YYYY" }

  // Novos campos de Estatísticas
  position: string;
  goals: number;
  matchesPlayed: number;
  lastPlayedDate?: string; // Data da última partida que jogou (YYYY-MM-DD)
  overall: number; // Para o card FIFA
}

export interface DbPlayer {
  id: number;
  name: string;
  photo_url: string;
  is_paid: boolean;
  payment_date: string | null;
  value: number;
  jersey_number: number;
  status: string;

  // Colunas DB
  position?: string;
  goals?: number;
  matches_played?: number;
  last_played_date?: string;
  overall?: number;
}

export interface Match {
  id: string;
  opponent: string;
  locationImg: string | null;
  location?: string; // Campo novo para nome do local
  date: string; // YYYY-MM-DD
  time: string; // HH:MM
  homeScore: number;
  awayScore: number;
  result: 'win' | 'loss' | 'draw' | 'pending';
  isFinished: boolean;
}

export interface DbMatch {
  id: number;
  opponent: string;
  location_img: string | null;
  location?: string;
  date: string;
  time: string;
  home_score: number;
  away_score: number;
  result: string;
  is_finished: boolean;
}

export interface DashboardStats {
  totalCollected: number;
  totalPending: number;
  currentDate: string;
  dueDate: string;
}

import React, { useState, useEffect, useMemo, ChangeEvent } from 'react';
import { Player, DbPlayer, Match, DbMatch } from './types';
import { getSupabase, saveSupabaseKey, SUPABASE_URL } from './supabaseClient';

const DEFAULT_FEE = 40;

const App: React.FC = () => {
  // --- STATE ---
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [currentTab, setCurrentTab] = useState<'financial' | 'matches' | 'stats'>('matches'); 

  // Data State
  const [players, setPlayers] = useState<Player[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);

  // Financial Specific State
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  // Connection State
  const [apiKeyModalOpen, setApiKeyModalOpen] = useState(false);
  const [apiKeyInput, setApiKeyInput] = useState('');
  const [isConnected, setIsConnected] = useState(false);

  // Inline Editing State
  const [editingDateId, setEditingDateId] = useState<string | null>(null);
  const [editingNameId, setEditingNameId] = useState<string | null>(null);
  const [editingJerseyId, setEditingJerseyId] = useState<string | null>(null);
  const [tempName, setTempName] = useState<string>('');

  // Modals State
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // Matches View Mode
  const [matchViewMode, setMatchViewMode] = useState<'upcoming' | 'history'>('upcoming');

  // MATCH RESULT MODAL STATE
  const [isMatchResultModalOpen, setIsMatchResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);
  const [manualHomeScore, setManualHomeScore] = useState(0);
  const [manualAwayScore, setManualAwayScore] = useState(0);
  const [matchPlayerStats, setMatchPlayerStats] = useState<Record<string, {goals: number}>>({});

  // Forms State
  const [newPlayerName, setNewPlayerName] = useState('');
  const [newPlayerNumber, setNewPlayerNumber] = useState('');
  const [newPlayerPhoto, setNewPlayerPhoto] = useState<string | null>(null);
  const [newPlayerPosition, setNewPlayerPosition] = useState('MEI');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [newMatchOpponent, setNewMatchOpponent] = useState('');
  const [newMatchLocation, setNewMatchLocation] = useState('');
  const [newMatchDate, setNewMatchDate] = useState(new Date().toISOString().split('T')[0]);
  const [newMatchTime, setNewMatchTime] = useState('');
  const [newMatchLocationImg, setNewMatchLocationImg] = useState<string | null>(null);

  // Edit Stats State
  const [editingStatsId, setEditingStatsId] = useState<string | null>(null);
  const [tempStats, setTempStats] = useState({ goals: 0, matchesPlayed: 0, overall: 0, position: '' });

  // --- INITIALIZATION ---

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  // Load Data
  useEffect(() => {
    const supabase = getSupabase();
    if (!supabase) {
      setApiKeyModalOpen(true);
      setLoading(false);
      return;
    }
    setIsConnected(true);
    fetchData();

    const channelPlayers = supabase.channel('realtime-players')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'players' }, () => fetchData())
      .subscribe();

    const channelMatches = supabase.channel('realtime-matches')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, () => fetchData())
      .subscribe();

    return () => {
      supabase.removeChannel(channelPlayers);
      supabase.removeChannel(channelMatches);
    };
  }, []);

  const fetchData = async () => {
    const supabase = getSupabase();
    if (!supabase) return;

    try {
      const { data: dataPlayers } = await supabase.from('players').select('*').order('name', { ascending: true });
      if (dataPlayers) {
        setPlayers(dataPlayers.map((p: any) => ({
          id: p.id.toString(),
          name: p.name,
          photoUrl: p.photo_url || 'https://via.placeholder.com/150',
          isPaid: false, 
          paymentDate: undefined,
          value: p.value,
          jerseyNumber: p.jersey_number,
          status: (p.status === 'injured' ? 'injured' : 'active') as 'active' | 'injured',
          paymentHistory: parsePaymentHistory(p.payment_date),
          position: p.position || 'MEI',
          goals: p.goals || 0,
          matchesPlayed: p.matches_played || 0,
          lastPlayedDate: p.last_played_date, // Mapeando do DB
          overall: p.overall || 75
        })));
      }

      const { data: dataMatches } = await supabase.from('matches').select('*').order('date', { ascending: true });
      if (dataMatches) {
        setMatches(dataMatches.map((m: DbMatch) => ({
          id: m.id.toString(),
          opponent: m.opponent,
          locationImg: m.location_img,
          location: m.location || '',
          date: m.date,
          time: m.time,
          homeScore: m.home_score,
          awayScore: m.away_score,
          result: m.result as any,
          isFinished: m.is_finished
        })));
      }
    } catch (error) {
      console.error("Erro ao buscar dados:", error);
    } finally {
      setLoading(false);
    }
  };

  // --- HELPERS ---

  const getMonthKey = (date: Date) => {
    const m = (date.getMonth() + 1).toString().padStart(2, '0');
    const y = date.getFullYear();
    return `${m}-${y}`;
  };

  const parsePaymentHistory = (dateStr: string | null): Record<string, string> => {
    if (!dateStr) return {};
    try {
        const parsed = JSON.parse(dateStr);
        if (typeof parsed === 'object' && parsed !== null) return parsed;
        return {};
    } catch (e) {
        return dateStr ? { [getMonthKey(new Date())]: dateStr } : {};
    }
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  const formattedDate = useMemo(() => {
    const options: Intl.DateTimeFormatOptions = { month: 'long', year: 'numeric' };
    const str = selectedDate.toLocaleDateString('pt-BR', options);
    return str.charAt(0).toUpperCase() + str.slice(1);
  }, [selectedDate]);

  const changeMonth = (increment: number) => {
    const newDate = new Date(selectedDate);
    newDate.setMonth(newDate.getMonth() + increment);
    setSelectedDate(newDate);
  };

  const getNextSundays = () => {
      const dates = [];
      let d = new Date();
      d.setDate(d.getDate() + (7 - d.getDay()) % 7);
      for(let i=0; i<6; i++) {
          dates.push(new Date(d));
          d.setDate(d.getDate() + 7);
      }
      return dates;
  };

  // --- STATS CALCULATION ---

  const currentMonthKey = getMonthKey(selectedDate);

  const playersView = useMemo(() => {
    return players.map(player => ({
        ...player,
        isPaid: !!player.paymentHistory[currentMonthKey],
        paymentDate: player.paymentHistory[currentMonthKey]
    }));
  }, [players, currentMonthKey]);

  const financialStats = useMemo(() => {
    const active = playersView.filter(p => p.status === 'active' || p.isPaid);
    const collected = playersView.reduce((acc, p) => acc + (p.isPaid ? p.value : 0), 0);
    const potential = active.reduce((acc, p) => acc + p.value, 0);
    const count = active.length;
    const paid = playersView.filter(p => p.isPaid).length;
    return { collected, potential, paid, count, progress: count > 0 ? (paid / count) * 100 : 0 };
  }, [playersView]);

  const topPayers = useMemo(() => playersView.filter(p => p.isPaid && p.status === 'active').slice(0, 3), [playersView]);

  const matchStats = useMemo(() => {
    const finished = matches.filter(m => m.isFinished);
    const wins = finished.filter(m => m.result === 'win').length;
    const draws = finished.filter(m => m.result === 'draw').length;
    const losses = finished.filter(m => m.result === 'loss').length;
    const total = finished.length;
    const goalsFor = finished.reduce((acc, m) => acc + m.homeScore, 0);
    const goalsAgainst = finished.reduce((acc, m) => acc + m.awayScore, 0);
    const goalDiff = goalsFor - goalsAgainst;

    return { 
        wins, draws, losses, total, 
        winRate: total > 0 ? Math.round((wins / total) * 100) : 0,
        goalsFor, goalsAgainst, goalDiff
    };
  }, [matches]);

  const topScorers = useMemo(() => [...players].sort((a, b) => b.goals - a.goals).slice(0, 5), [players]);

  const topAppearances = useMemo(() => [...players].sort((a, b) => b.matchesPlayed - a.matchesPlayed).slice(0, 3), [players]);

  // --- ACTIONS ---

  const handleSaveKey = (e: React.FormEvent) => {
    e.preventDefault();
    if (apiKeyInput.trim()) {
      saveSupabaseKey(apiKeyInput.trim());
      setApiKeyModalOpen(false);
    }
  };

  const togglePayment = async (id: string) => {
    const supabase = getSupabase();
    if (!supabase) return;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const newHistory = { ...player.paymentHistory };
    const isPaid = !!newHistory[currentMonthKey];

    if (isPaid) delete newHistory[currentMonthKey];
    else newHistory[currentMonthKey] = new Date().toLocaleDateString('pt-BR');

    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    await supabase.from('players').update({ payment_date: JSON.stringify(newHistory), is_paid: !isPaid }).eq('id', id);
  };

  const updatePaymentDate = async (id: string, dateValue: string) => {
    if (!dateValue) return;
    const [year, month, day] = dateValue.split('-');
    const formatted = `${day}/${month}/${year}`;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const newHistory = { ...player.paymentHistory, [currentMonthKey]: formatted };
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    setEditingDateId(null);
    const supabase = getSupabase();
    if (supabase) await supabase.from('players').update({ payment_date: JSON.stringify(newHistory) }).eq('id', id);
  };

  const handlePhotoUpload = (e: ChangeEvent<HTMLInputElement>, setter: (val: string) => void) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => setter(reader.result as string);
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const updatePlayerPhoto = async (id: string, e: ChangeEvent<HTMLInputElement>) => {
    handlePhotoUpload(e, async (base64) => {
        const supabase = getSupabase();
        if(supabase) await supabase.from('players').update({ photo_url: base64 }).eq('id', id);
        fetchData();
    });
  };

  const deletePlayer = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Remover jogador?")) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').delete().eq('id', id);
      setPlayers(prev => prev.filter(p => p.id !== id));
    }
  };

  const togglePlayerStatus = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const player = players.find(p => p.id === id);
    if(!player) return;
    const newStatus = player.status === 'active' ? 'injured' : 'active';
    const supabase = getSupabase();
    if(supabase) await supabase.from('players').update({ status: newStatus }).eq('id', id);
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
  };

  const startEditingName = (player: Player) => {
    setTempName(player.name);
    setEditingNameId(player.id);
  };

  const savePlayerName = async (id: string) => {
    if (tempName.trim()) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').update({ name: tempName.trim() }).eq('id', id);
      setPlayers(prev => prev.map(p => p.id === id ? { ...p, name: tempName.trim() } : p));
    }
    setEditingNameId(null);
  };

  const saveJerseyNumber = async (id: string, newNumber: string) => {
    const num = parseInt(newNumber);
    if (!isNaN(num)) {
         const supabase = getSupabase();
         if(supabase) await supabase.from('players').update({ jersey_number: num }).eq('id', id);
         setPlayers(prev => prev.map(p => p.id === id ? { ...p, jerseyNumber: num } : p));
    }
    setEditingJerseyId(null);
  };

  const handleAddPlayer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlayerName.trim() || !newPlayerPhoto || isSubmitting) return;

    setIsSubmitting(true);
    const supabase = getSupabase();
    if (supabase) {
        const fullPayload = {
            name: newPlayerName,
            photo_url: newPlayerPhoto,
            is_paid: false,
            value: DEFAULT_FEE,
            jersey_number: parseInt(newPlayerNumber) || 0,
            status: 'active',
            payment_date: JSON.stringify({}),
            position: newPlayerPosition,
            goals: 0,
            matches_played: 0,
            overall: 70
        };

        const { error } = await supabase.from('players').insert([fullPayload]);

        if (error) {
            console.warn("Insert completo falhou. Tentando fallback básico.", error.message);
            const basicPayload = {
                name: newPlayerName,
                photo_url: newPlayerPhoto,
                is_paid: false,
                value: DEFAULT_FEE,
                jersey_number: parseInt(newPlayerNumber) || 0,
                status: 'active',
                payment_date: JSON.stringify({})
            };
            const { error: basicError } = await supabase.from('players').insert([basicPayload]);
            if (basicError) {
                alert(`Erro ao salvar jogador: ${basicError.message}`);
                setIsSubmitting(false);
                return;
            }
        }
        await fetchData();
    }

    setNewPlayerName('');
    setNewPlayerNumber('');
    setNewPlayerPhoto(null);
    setIsAddModalOpen(false);
    setIsSubmitting(false);
  };

  const openPlayerProfile = (player: Player) => {
      setTempStats({
          goals: player.goals,
          matchesPlayed: player.matchesPlayed,
          overall: player.overall,
          position: player.position
      });
      setEditingStatsId(player.id);
  };

  const savePlayerStats = async () => {
      if(!editingStatsId) return;
      const supabase = getSupabase();
      if(supabase) {
          const { error } = await supabase.from('players').update({
              goals: tempStats.goals,
              matches_played: tempStats.matchesPlayed,
              overall: tempStats.overall,
              position: tempStats.position
          }).eq('id', editingStatsId);

          if (error) {
             alert("Erro ao atualizar estatísticas. Verifique se as colunas existem.\n" + error.message);
          } else {
             setPlayers(prev => prev.map(p => p.id === editingStatsId ? { ...p, ...tempStats } : p));
          }
      }
      setEditingStatsId(null);
  };

  const handleAddMatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if(isSubmitting) return;
    setIsSubmitting(true);

    const supabase = getSupabase();
    if(supabase) {
        if (matches.some(m => m.date === newMatchDate)) {
            if(!window.confirm("Já existe um jogo nesta data. Deseja marcar outro?")) {
                setIsSubmitting(false);
                return;
            }
        }

        const { error } = await supabase.from('matches').insert([{
            opponent: newMatchOpponent,
            location: newMatchLocation,
            date: newMatchDate,
            time: newMatchTime,
            location_img: newMatchLocationImg,
            result: 'pending',
            is_finished: false
        }]);

        if (error) {
            alert(`Erro ao criar partida: ${error.message}`);
            setIsSubmitting(false);
            return;
        }
        await fetchData();
    }
    setNewMatchOpponent('');
    setNewMatchLocation('');
    setNewMatchDate(new Date().toISOString().split('T')[0]);
    setNewMatchTime('');
    setNewMatchLocationImg(null);
    setIsAddModalOpen(false);
    setIsSubmitting(false);
  };

  const deleteMatch = async (id: string, e: React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();

      const confirmDelete = window.confirm("Tem certeza que deseja excluir esta partida?");
      if (!confirmDelete) return;

      const previousMatches = [...matches];
      setMatches(prev => prev.filter(m => m.id !== id));

      const supabase = getSupabase();
      if(!supabase) {
          setMatches(previousMatches); 
          return;
      }

      try {
          const { error } = await supabase.from('matches').delete().eq('id', parseInt(id));
          if (error) {
              alert("Erro ao excluir partida no banco de dados: " + error.message);
              setMatches(previousMatches); 
          }
      } catch (err: any) {
          alert("Ocorreu um erro ao tentar excluir: " + err.message);
          setMatches(previousMatches); 
      }
  };

  const openMatchResultModal = (match: Match) => {
      setSelectedMatch(match);
      setManualHomeScore(match.isFinished ? match.homeScore : 0);
      setManualAwayScore(match.isFinished ? match.awayScore : 0);

      const initialStats: Record<string, {goals: number}> = {};
      players.filter(p => p.status === 'active').forEach(p => {
          initialStats[p.id] = { goals: 0 };
      });
      setMatchPlayerStats(initialStats);

      setIsMatchResultModalOpen(true);
  };

  const updateMatchStat = (playerId: string, type: 'goals', delta: number) => {
      setMatchPlayerStats(prev => ({
          ...prev,
          [playerId]: {
              ...prev[playerId],
              [type]: Math.max(0, (prev[playerId]?.[type] || 0) + delta)
          }
      }));
  };

  const confirmMatchResult = async () => {
      if (!selectedMatch) return;
      const supabase = getSupabase();
      if (!supabase) return;

      setIsSubmitting(true);

      let result = 'draw';
      if (manualHomeScore > manualAwayScore) result = 'win';
      if (manualHomeScore < manualAwayScore) result = 'loss';

      const { error: matchError } = await supabase.from('matches').update({
          home_score: manualHomeScore,
          away_score: manualAwayScore,
          result: result,
          is_finished: true
      }).eq('id', parseInt(selectedMatch.id));

      if (matchError) {
          alert("Erro ao salvar placar: " + matchError.message);
          setIsSubmitting(false);
          return;
      }

      if (!selectedMatch.isFinished) {
          const updates = [];
          for (const playerId in matchPlayerStats) {
                const stats = matchPlayerStats[playerId];
                const player = players.find(p => p.id === playerId);

                if (player) {
                    updates.push(
                        supabase.from('players').update({
                            goals: (player.goals || 0) + stats.goals,
                            matches_played: (player.matchesPlayed || 0) + 1,
                            last_played_date: selectedMatch.date // Atualiza data do último jogo
                        }).eq('id', playerId)
                    );
                }
          }
          if(updates.length > 0) {
            await Promise.all(updates);
          }
      }

      await fetchData(); 
      setIsMatchResultModalOpen(false);
      setIsSubmitting(false);
  };

  // --- RENDERERS ---

  const renderFinancial = () => (
    <div className="space-y-8 md:space-y-10 animation-fade-in pb-20">
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 md:gap-8">
          <div className="xl:col-span-1 bg-surface-light dark:bg-surface-dark rounded-2xl p-6 md:p-8 border border-gray-200 dark:border-gray-800 shadow-sm relative overflow-hidden group flex flex-col justify-between min-h-[200px] md:min-h-[220px]">
             <div className="absolute top-0 right-0 w-64 h-64 bg-primary/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
             <div className="relative z-10">
               <h2 className="text-muted-light dark:text-muted-dark font-medium mb-1 text-sm md:text-base">Total em Caixa ({formattedDate})</h2>
               <div className="flex items-baseline gap-2 mb-6">
                 <span className="text-4xl md:text-5xl font-bold tracking-tighter text-gray-900 dark:text-white">R$ {financialStats.collected}</span>
                 <span className="text-sm md:text-lg text-muted-light dark:text-muted-dark font-medium">/ {financialStats.potential}</span>
               </div>
             </div>
             <div className="relative z-10 mt-auto">
               <div className="flex justify-between text-sm font-semibold mb-3">
                 <span className="text-primary">{financialStats.paid} Pagos</span>
                 <span className="text-muted-light dark:text-muted-dark">{financialStats.count - financialStats.paid} Pendentes</span>
               </div>
               <div className="w-full bg-gray-200 dark:bg-gray-800 rounded-full h-3 md:h-4 overflow-hidden">
                 <div className="bg-primary h-3 md:h-4 rounded-full transition-all duration-700 ease-out" style={{ width: `${financialStats.progress}%` }}></div>
               </div>
             </div>
          </div>

          <div className="xl:col-span-2 bg-surface-light dark:bg-surface-dark rounded-2xl p-6 md:p-8 border border-gray-200 dark:border-gray-800 shadow-sm relative overflow-hidden">
              <div className="flex items-center gap-2 mb-6"><span className="material-icons-outlined text-yellow-500">emoji_events</span><h3 className="font-bold text-lg">Pagadores Rápidos</h3></div>
              <div className="flex items-end justify-around h-36 md:h-40 pb-2">
                 {[1, 0, 2].map((idx) => {
                     const p = topPayers[idx];
                     const rank = idx + 1;
                     const isFirst = rank === 1;
                     return p ? (
                        <div key={p.id} className={`flex flex-col items-center gap-2 ${isFirst ? 'mb-4' : ''}`}>
                             <div className="relative">
                                 {isFirst && <span className="absolute -top-5 md:-top-6 left-1/2 -translate-x-1/2 material-icons-outlined text-yellow-400 animate-bounce">crown</span>}
                                 <img src={p.photoUrl} className={`${isFirst ? 'w-20 h-20 md:w-24 md:h-24 border-yellow-400' : 'w-14 h-14 md:w-16 md:h-16 border-gray-400'} rounded-full border-4 object-cover`} />
                                 <div className={`absolute -bottom-3 left-1/2 -translate-x-1/2 w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${isFirst ? 'bg-yellow-400 text-black' : 'bg-gray-400 text-white'}`}>{rank}</div>
                             </div>
                             <div className="text-center mt-2"><p className="font-bold text-xs md:text-sm truncate max-w-[80px] md:max-w-[100px]">{p.name}</p></div>
                        </div>
                     ) : <div key={idx} className="w-14 h-14 md:w-16 md:h-16 rounded-full bg-gray-800/10 flex items-center justify-center text-xs opacity-30">{rank}º</div>
                 })}
              </div>
          </div>
        </div>

        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <h3 className="text-xl font-bold flex items-center gap-2">Elenco <span className="text-xs bg-gray-200 dark:bg-gray-800 px-2 py-1 rounded">{playersView.length}</span></h3>
                <div className="flex w-full md:w-auto justify-between md:justify-end items-center gap-2">
                    <div className="flex items-center gap-2 bg-surface-light dark:bg-surface-dark px-2 py-1 rounded-full border border-gray-200 dark:border-gray-700">
                        <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><span className="material-icons-outlined">chevron_left</span></button>
                        <span className="font-bold text-sm px-2">{formattedDate}</span>
                        <button onClick={() => changeMonth(1)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><span className="material-icons-outlined">chevron_right</span></button>
                    </div>
                    <button onClick={() => setIsAddModalOpen(true)} className="hidden md:flex items-center justify-center gap-2 bg-primary hover:opacity-90 text-surface-light dark:text-surface-dark font-bold px-4 py-2 rounded-xl transition-all shadow-lg shadow-primary/20 text-sm">
                        <span className="material-icons-outlined text-lg">add</span> Novo Jogador
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4 md:gap-6">
                 {playersView.map(p => (
                     <div key={p.id} className={`relative bg-surface-light dark:bg-surface-dark rounded-2xl p-4 md:p-6 flex flex-col items-center border ${p.status === 'injured' ? 'border-orange-200 dark:border-orange-900/30 opacity-90' : p.isPaid ? 'border-primary/50 shadow-lg shadow-primary/10' : 'border-gray-200 dark:border-gray-800'} transition-all group`}>

                         {/* Action Buttons: Injury & Delete (Top Right) */}
                         <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                            <button 
                                onClick={(e) => togglePlayerStatus(p.id, e)}
                                className={`p-1 rounded text-[10px] ${p.status === 'injured' ? 'bg-orange-100 text-orange-600 hover:bg-orange-200' : 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-400 hover:text-orange-500'}`}
                                title={p.status === 'injured' ? "Retornar ao elenco" : "Reportar lesão"}
                            >
                                <span className="material-icons-outlined text-sm">medical_services</span>
                            </button>
                            <button onClick={(e) => deletePlayer(p.id, e)} className="p-1 hover:bg-red-100 dark:hover:bg-red-900/50 rounded text-red-500"><span className="material-icons-outlined text-sm">delete</span></button>
                         </div>

                         {/* Photo */}
                         <div className="relative mb-3 group/img">
                             <img src={p.photoUrl} className={`w-16 h-16 md:w-20 md:h-20 rounded-full object-cover border-2 ${p.status === 'injured' ? 'border-gray-300 grayscale opacity-80' : p.isPaid ? 'border-primary border-4' : 'border-transparent border-4'}`} />
                             <label className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover/img:opacity-100 rounded-full cursor-pointer transition-opacity">
                                 <span className="material-icons-outlined text-white">camera_alt</span>
                                 <input type="file" className="hidden" onChange={(e) => updatePlayerPhoto(p.id, e)} />
                             </label>
                             <div className="absolute top-0 left-0 bg-surface-dark text-white text-xs font-bold w-5 h-5 md:w-6 md:h-6 rounded-full flex items-center justify-center border border-white">{p.jerseyNumber}</div>
                         </div>

                         {/* Name */}
                         {editingNameId === p.id ? (
                             <input autoFocus className="w-full text-center bg-transparent border-b border-primary font-bold mb-1" value={tempName} onChange={e => setTempName(e.target.value)} onBlur={() => savePlayerName(p.id)} onKeyDown={e => e.key === 'Enter' && savePlayerName(p.id)} />
                         ) : (
                             <h4 onClick={() => startEditingName(p)} className="font-bold truncate w-full text-center cursor-pointer hover:text-primary transition-colors text-base md:text-lg">{p.name}</h4>
                         )}

                         {/* Status Badge */}
                         <div className="mt-2 mb-3 flex items-center justify-center gap-2">
                            {p.status === 'injured' ? (
                                <span className="flex items-center gap-1 text-[10px] font-bold text-orange-500 bg-orange-500/10 px-2 py-1 rounded-full uppercase">
                                    <span className="material-icons-outlined text-[12px]">healing</span>
                                    Afastado
                                </span>
                            ) : p.isPaid ? (
                                <span className="flex items-center gap-1 text-[10px] font-bold text-green-600 bg-green-100 dark:bg-green-900/30 px-2 py-1 rounded-full uppercase">
                                    <span className="material-icons-outlined text-[12px]">check_circle</span>
                                    Pagou
                                </span>
                            ) : (
                                <span className="flex items-center gap-1 text-[10px] font-bold text-red-500 bg-red-100 dark:bg-red-900/30 px-2 py-1 rounded-full uppercase">
                                    <span className="material-icons-outlined text-[12px]">cancel</span>
                                    Não Pagou
                                </span>
                            )}
                         </div>

                         {/* Footer Actions */}
                         <div className="mt-auto w-full flex items-center justify-between border-t border-gray-100 dark:border-gray-700/50 pt-3">
                             <span className={`font-bold text-xs md:text-sm ${p.status === 'injured' ? 'text-gray-400 line-through' : 'text-muted-light'}`}>R$ {p.value}</span>
                             <label className={`cursor-pointer ${p.status === 'injured' ? 'opacity-50 pointer-events-none' : ''}`}>
                                 <input type="checkbox" className="sr-only peer" checked={p.isPaid} onChange={() => togglePayment(p.id)} disabled={p.status === 'injured'} />
                                 <div className="w-8 h-5 md:w-10 md:h-6 bg-gray-300 dark:bg-gray-700 rounded-full peer-checked:bg-primary transition-colors relative">
                                     <div className={`absolute top-1 left-1 bg-white w-3 h-3 md:w-4 md:h-4 rounded-full transition-transform ${p.isPaid ? 'translate-x-3 md:translate-x-4' : ''}`}></div>
                                 </div>
                             </label>
                         </div>
                     </div>
                 ))}
                 <button onClick={() => setIsAddModalOpen(true)} className="flex flex-col items-center justify-center bg-surface-light dark:bg-surface-dark border border-gray-100 dark:border-gray-800 rounded-2xl p-6 hover:shadow-lg transition-all text-muted-light group min-h-[160px]">
                     <span className="material-icons-outlined text-3xl md:text-4xl mb-2 group-hover:scale-110 transition-transform group-hover:text-primary">add_circle_outline</span>
                     <span className="font-bold text-sm group-hover:text-primary">Adicionar</span>
                 </button>
            </div>
        </div>
    </div>
  );

  const renderMatches = () => {
    const nextSundays = getNextSundays();
    const upcomingMatches = matches.filter(m => !m.isFinished).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    const finishedMatches = matches.filter(m => m.isFinished).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const displayMatches = matchViewMode === 'upcoming' ? upcomingMatches : finishedMatches;

    return (
    <div className="space-y-8 animation-fade-in pb-20">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
             <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800 flex items-center justify-between relative overflow-hidden">
                  <div className="z-10">
                      <h3 className="text-muted-light font-bold text-sm uppercase">Aproveitamento</h3>
                      <p className="text-4xl font-bold mt-2">{matchStats.winRate}%</p>
                  </div>
                  <div className="relative w-24 h-24 p-1">
                      <svg className="w-full h-full transform -rotate-90" viewBox="0 0 100 100">
                          <circle cx="50" cy="50" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-200 dark:text-gray-800" />
                          <circle cx="50" cy="50" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={251} strokeDashoffset={251 - (251 * matchStats.winRate) / 100} className="text-green-500 transition-all duration-1000" />
                      </svg>
                  </div>
             </div>

             <div className="lg:col-span-2 grid grid-cols-3 gap-2 md:gap-4">
                 <div className="bg-green-500/10 border border-green-500/20 rounded-2xl p-2 md:p-4 flex flex-col items-center justify-center">
                     <span className="text-2xl md:text-3xl font-bold text-green-500">{matchStats.wins}</span>
                     <span className="text-[10px] md:text-xs font-bold uppercase text-green-700 dark:text-green-400">Vitórias</span>
                 </div>
                 <div className="bg-gray-200/50 dark:bg-gray-700/30 border border-gray-300 dark:border-gray-700 rounded-2xl p-2 md:p-4 flex flex-col items-center justify-center">
                     <span className="text-2xl md:text-3xl font-bold text-gray-500 dark:text-gray-300">{matchStats.draws}</span>
                     <span className="text-[10px] md:text-xs font-bold uppercase text-gray-600 dark:text-gray-400">Empates</span>
                 </div>
                 <div className="bg-red-500/10 border border-red-500/20 rounded-2xl p-2 md:p-4 flex flex-col items-center justify-center">
                     <span className="text-2xl md:text-3xl font-bold text-red-500">{matchStats.losses}</span>
                     <span className="text-[10px] md:text-xs font-bold uppercase text-red-700 dark:text-red-400">Derrotas</span>
                 </div>
             </div>

             <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800 flex flex-col justify-center">
                  <h3 className="text-muted-light font-bold text-xs uppercase mb-3">Resumo da Temporada</h3>
                  <div className="flex justify-between items-end border-b border-gray-100 dark:border-gray-700 pb-2 mb-2">
                      <span className="text-xs font-bold">Jogos</span>
                      <span className="font-bold text-gray-900 dark:text-white text-lg">{matchStats.total}</span>
                  </div>
                  <div className="flex justify-between items-end border-b border-gray-100 dark:border-gray-700 pb-2 mb-2">
                      <span className="text-xs font-bold">Gols Pró</span>
                      <span className="font-bold text-green-500 text-lg">{matchStats.goalsFor}</span>
                  </div>
                  <div className="flex justify-between items-end border-b border-gray-100 dark:border-gray-700 pb-2 mb-2">
                      <span className="text-xs font-bold">Gols Contra</span>
                      <span className="font-bold text-red-500 text-lg">{matchStats.goalsAgainst}</span>
                  </div>
                  <div className="flex justify-between items-end">
                      <span className="text-xs font-bold">Saldo</span>
                      <span className={`font-bold text-lg ${matchStats.goalDiff >= 0 ? 'text-primary' : 'text-red-500'}`}>{matchStats.goalDiff > 0 ? '+' : ''}{matchStats.goalDiff}</span>
                  </div>
             </div>
        </div>

        <div className="space-y-4">
            <h3 className="text-lg font-bold flex items-center gap-2"><span className="material-icons-outlined text-primary">event_available</span> Domingos de Jogo</h3>
            <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide">
                {nextSundays.map((d, i) => {
                    const dateStr = d.toISOString().split('T')[0];
                    const isBooked = matches.some(m => m.date === dateStr);
                    return (
                        <div key={i} className={`flex-shrink-0 w-20 h-24 rounded-2xl flex flex-col items-center justify-center border-2 transition-all ${isBooked ? 'bg-primary border-primary text-white shadow-lg shadow-primary/30' : 'bg-surface-light dark:bg-surface-dark border-gray-200 dark:border-gray-800 text-muted-light'}`}>
                             <span className="text-xs font-bold uppercase opacity-80">{d.toLocaleDateString('pt-BR', {month: 'short'}).replace('.','')}</span>
                             <span className="text-3xl font-bold my-1">{d.getDate()}</span>
                             <span className="text-[10px] font-bold uppercase">{isBooked ? 'JOGO' : 'LIVRE'}</span>
                        </div>
                    );
                })}
            </div>
        </div>

        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-4">
                <div className="flex items-center gap-4">
                    <h3 className="text-lg font-bold">Agenda de Jogos</h3>
                    <div className="flex bg-gray-200 dark:bg-surface-dark p-1 rounded-lg">
                        <button onClick={() => setMatchViewMode('upcoming')} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${matchViewMode === 'upcoming' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Próximos</button>
                        <button onClick={() => setMatchViewMode('history')} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${matchViewMode === 'history' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Histórico</button>
                    </div>
                </div>

                <button onClick={() => setIsAddModalOpen(true)} className="hidden md:flex bg-primary hover:opacity-90 text-white px-4 py-2 rounded-xl font-bold text-sm shadow-lg shadow-primary/20 items-center gap-2">
                    <span className="material-icons-outlined text-lg">add</span> Nova Partida
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {displayMatches.map(m => (
                    <div 
                        key={m.id} 
                        className={`relative rounded-2xl overflow-hidden flex flex-col shadow-sm animation-fade-in group transition-all duration-300
                            ${matchViewMode === 'upcoming' 
                                ? 'bg-gradient-to-br from-primary to-orange-500 dark:from-primary dark:to-orange-500 text-white shadow-lg' 
                                : 'bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-800 grayscale opacity-80 hover:grayscale-0 hover:opacity-100'
                            }`}
                    >
                        <div className="absolute top-3 right-3 z-50">
                            <button onClick={(e) => deleteMatch(m.id, e)} className={`p-2 rounded-full transition-colors cursor-pointer ${matchViewMode === 'upcoming' ? 'text-white/80 hover:bg-white/20 hover:text-white' : 'text-gray-400 hover:text-red-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}>
                                <span className="material-icons-outlined text-lg">delete_outline</span>
                            </button>
                        </div>

                        {/* Status Badge */}
                        <div className="absolute top-4 left-4 z-40">
                             {m.isFinished ? (
                                 <span className={`text-[10px] font-bold uppercase px-2 py-1 rounded backdrop-blur-md shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/20 text-white' : (m.result === 'win' ? 'bg-green-100 text-green-600' : m.result === 'loss' ? 'bg-red-100 text-red-600' : 'bg-gray-100 text-gray-600')}`}>
                                     {m.result === 'win' ? 'Vitória' : m.result === 'loss' ? 'Derrota' : 'Empate'}
                                 </span>
                             ) : (
                                 <span className="text-[10px] font-bold uppercase px-2 py-1 rounded bg-white/20 text-white backdrop-blur-md shadow-sm animate-pulse">Em Breve</span>
                             )}
                        </div>

                        <div className="p-6 pt-14 flex items-center justify-between">
                             <div className="flex flex-col items-center gap-2 w-1/3">
                                 <img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10 md:w-14 md:h-14 object-contain drop-shadow-md" />
                                 <span className={`font-bold text-xs md:text-sm hidden sm:block ${matchViewMode === 'upcoming' ? 'text-white' : ''}`}>Pesadão</span>
                             </div>

                             <div className="flex flex-col items-center justify-center w-1/3">
                                 <div className={`px-2 md:px-4 py-1 md:py-2 rounded-lg font-mono text-3xl md:text-4xl font-bold tracking-widest mb-2 ${matchViewMode === 'upcoming' ? 'text-white' : 'text-gray-900 dark:text-white'}`}>
                                     {m.isFinished ? `${m.homeScore}-{m.awayScore}` : 'VS'}
                                 </div>

                                 <div className={`flex flex-col items-center gap-1 text-[10px] md:text-xs font-bold uppercase ${matchViewMode === 'upcoming' ? 'text-white/90' : 'text-muted-light'}`}>
                                     <div className="flex items-center gap-1 bg-black/10 dark:bg-white/5 px-2 py-0.5 rounded-full">
                                        <span className="material-icons-outlined text-[12px]">calendar_today</span>
                                        <span>{new Date(m.date + 'T00:00:00').toLocaleDateString('pt-BR')}</span>
                                     </div>
                                     <div className="flex items-center gap-1">
                                        <span>{m.time.slice(0,5)}</span>
                                        {m.location && (
                                            <>
                                                <span>•</span>
                                                <span className="flex items-center gap-0.5"><span className="material-icons-outlined text-[10px]">place</span>{m.location}</span>
                                            </>
                                        )}
                                     </div>
                                 </div>
                             </div>

                             <div className="flex flex-col items-center gap-2 w-1/3">
                                 <div className={`w-10 h-10 md:w-14 md:h-14 rounded-full flex items-center justify-center overflow-hidden shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/90' : 'bg-gray-100 dark:bg-gray-700'}`}>
                                     {m.locationImg ? <img src={m.locationImg} className="w-full h-full object-cover" /> : <span className="material-icons-outlined text-gray-400">sports_soccer</span>}
                                 </div>
                                 <span className={`font-bold text-xs md:text-sm truncate max-w-full text-center ${matchViewMode === 'upcoming' ? 'text-white' : ''}`}>{m.opponent}</span>
                             </div>
                        </div>

                        <div className={`p-3 border-t flex justify-center ${matchViewMode === 'upcoming' ? 'border-white/10 bg-white/5' : 'border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-surface-dark/50'}`}>
                             <button onClick={() => openMatchResultModal(m)} className={`w-full py-3 rounded-lg text-xs font-bold uppercase text-center flex items-center justify-center gap-2 transition-all shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/20 text-white hover:bg-white hover:text-primary' : 'bg-white dark:bg-surface-dark border border-gray-200 dark:border-gray-700 hover:bg-primary hover:text-white hover:border-primary'}`}>
                                 <span className="material-icons-outlined text-[14px]">{m.isFinished ? "edit" : "sports_score"}</span>
                                 {m.isFinished ? "Editar Placar / Súmula" : "Informar Placar / Súmula"}
                             </button>
                        </div>
                    </div>
                ))}

                {displayMatches.length === 0 && (
                    <div className="col-span-full text-center py-10 bg-surface-light dark:bg-surface-dark rounded-2xl border border-dashed border-gray-200 dark:border-gray-800 flex flex-col items-center">
                        <span className="material-icons-outlined text-4xl text-muted-light mb-2">event_busy</span>
                        <p className="text-muted-light font-bold">Nenhum jogo encontrado nesta seção.</p>
                        {matchViewMode === 'upcoming' && (
                            <button onClick={() => setIsAddModalOpen(true)} className="mt-4 text-primary font-bold text-sm hover:underline">
                                Agendar agora
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
    </div>
  );
  };

  const renderStats = () => {
    // Find last finished match to display in cards
    const lastMatch = matches.filter(m => m.isFinished).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

    const renderRankingItem = (p: Player, i: number, value: number, type: 'goals' | 'matches') => {
        let rankColors = "border-gray-100 dark:border-gray-800 bg-surface-light dark:bg-surface-dark";
        let textRank = "text-muted-light";
        let icon = null;

        if (i === 0) {
            rankColors = "border-yellow-500/50 bg-gradient-to-r from-yellow-500/10 to-transparent";
            textRank = "text-yellow-500";
            icon = "emoji_events";
        } else if (i === 1) {
            rankColors = "border-gray-400/50 bg-gradient-to-r from-gray-400/10 to-transparent";
            textRank = "text-gray-400";
        } else if (i === 2) {
            rankColors = "border-orange-700/50 bg-gradient-to-r from-orange-700/10 to-transparent";
            textRank = "text-orange-700";
        }

        return (
            <div key={p.id} className={`flex items-center justify-between p-4 md:p-3 rounded-xl border ${rankColors} transition-all`}>
                <div className="flex items-center gap-4">
                    <div className={`flex flex-col items-center justify-center w-8 ${textRank}`}>
                        {i === 0 && icon ? <span className="material-icons-outlined text-xl mb-1">{icon}</span> : <span className="font-black text-xl md:text-lg">{i + 1}</span>}
                    </div>
                    <img src={p.photoUrl} className="w-14 h-14 md:w-10 md:h-10 rounded-full object-cover border-2 border-white/10 shadow-sm" />
                    <div>
                        <span className="font-bold text-base md:text-sm block">{p.name}</span>
                        <span className="text-xs text-muted-light font-bold bg-black/5 dark:bg-white/5 px-2 py-0.5 rounded-full">{p.position}</span>
                    </div>
                </div>
                <div className="flex flex-col items-end">
                    <span className={`text-2xl md:text-xl font-black ${textRank}`}>{value}</span>
                    <span className="text-[10px] uppercase font-bold text-muted-light">{type === 'goals' ? 'Gols' : 'Jogos'}</span>
                </div>
            </div>
        );
    };

    return (
    <div className="space-y-8 animation-fade-in pb-20">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800">
                <h3 className="font-bold mb-4 flex items-center gap-2 text-primary text-lg"><span className="material-icons-outlined">sports_soccer</span> Artilheiros</h3>
                <div className="space-y-3">
                    {topScorers.map((p, i) => renderRankingItem(p, i, p.goals, 'goals'))}
                    {topScorers.length === 0 && <p className="text-muted-light text-sm">Sem dados</p>}
                </div>
            </div>

            <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800">
                <h3 className="font-bold mb-4 flex items-center gap-2 text-primary text-lg"><span className="material-icons-outlined">history</span> Participações</h3>
                <div className="space-y-3">
                    {topAppearances.map((p, i) => renderRankingItem(p, i, p.matchesPlayed, 'matches'))}
                    {topAppearances.length === 0 && <p className="text-muted-light text-sm">Sem dados</p>}
                </div>
            </div>
        </div>

        <h3 className="text-xl font-bold mt-8">Jogadores</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
             {players.map(p => (
                 <div 
                    key={p.id} 
                    onClick={() => openPlayerProfile(p)} 
                    className="cursor-pointer group relative bg-surface-light dark:bg-surface-dark rounded-[2rem] border border-gray-200 dark:border-gray-800 p-5 transition-all duration-300 hover:shadow-2xl hover:-translate-y-1 hover:border-primary/40 overflow-hidden"
                 >
                      {/* Hover Decoration Background */}
                      <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-full blur-3xl -mr-16 -mt-16 transition-opacity opacity-0 group-hover:opacity-100 pointer-events-none"></div>

                      {/* Header: Number & Position */}
                      <div className="flex justify-between items-start mb-2 relative z-10">
                          <span className="font-display font-black text-3xl text-gray-100 dark:text-gray-800 group-hover:text-primary/10 transition-colors">
                              {p.jerseyNumber}
                          </span>
                          <span className="px-3 py-1 rounded-full bg-gray-100 dark:bg-gray-800/80 text-[10px] font-bold uppercase tracking-wider text-muted-light group-hover:bg-primary group-hover:text-white transition-colors shadow-sm backdrop-blur-sm">
                              {p.position}
                          </span>
                      </div>

                      {/* Center: Image & Name */}
                      <div className="flex flex-col items-center mb-6 relative z-10">
                          <div className="relative mb-3">
                              {/* Glow effect */}
                              <div className="absolute inset-0 bg-primary/20 rounded-full blur-md opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                              <img 
                                src={p.photoUrl} 
                                className="relative w-28 h-28 rounded-full object-cover border-4 border-surface-light dark:border-surface-dark shadow-lg group-hover:border-primary/50 transition-colors" 
                              />
                              {/* Status indicator */}
                              <div className={`absolute bottom-1 right-1 w-5 h-5 rounded-full border-4 border-surface-light dark:border-surface-dark ${p.status === 'active' ? 'bg-green-500' : 'bg-red-500'} shadow-sm`}></div>
                          </div>
                          <h4 className="font-bold text-xl text-center truncate w-full px-2 text-gray-900 dark:text-gray-100">{p.name}</h4>
                      </div>

                      {/* Footer: Last Match Info */}
                      {lastMatch && p.lastPlayedDate === lastMatch.date && (
                      <div className="relative z-10 mt-auto">
                          <div className="bg-gray-50 dark:bg-black/20 rounded-2xl p-3 border border-gray-100 dark:border-gray-800/50 group-hover:bg-white dark:group-hover:bg-gray-800/50 transition-colors">
                              <p className="text-[9px] uppercase font-bold text-muted-light mb-2 text-center tracking-wider">Último Jogo</p>
                              <div className="flex items-center justify-between">
                                  <div className="flex items-center gap-2 overflow-hidden">
                                      <div className={`w-2 h-8 rounded-full flex-shrink-0 ${lastMatch.result === 'win' ? 'bg-green-500' : lastMatch.result === 'loss' ? 'bg-red-500' : 'bg-gray-400'}`}></div>
                                      <div className="flex flex-col min-w-0">
                                          <span className="text-xs font-bold truncate">{lastMatch.opponent}</span>
                                          <span className={`text-[9px] font-bold uppercase ${lastMatch.result === 'win' ? 'text-green-600' : lastMatch.result === 'loss' ? 'text-red-500' : 'text-gray-500'}`}>
                                              {lastMatch.result === 'win' ? 'Vitória' : lastMatch.result === 'loss' ? 'Derrota' : 'Empate'}
                                          </span>
                                      </div>
                                  </div>
                                  <span className="font-mono text-xs font-black bg-white dark:bg-black/40 px-2 py-1 rounded-lg border border-gray-100 dark:border-gray-700 shadow-sm">
                                      {lastMatch.homeScore}-{lastMatch.awayScore}
                                  </span>
                              </div>
                          </div>
                      </div>
                      )}
                 </div>
             ))}
        </div>
    </div>
    );
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark text-gray-900 dark:text-gray-100 font-display p-4 md:p-8 transition-colors duration-300 pb-24 md:pb-8">

        {/* Navigation Header */}
        <div className="max-w-7xl mx-auto flex flex-row items-center justify-between mb-4 md:mb-8 gap-4 sticky top-0 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur z-40 py-2 md:py-4">
             <div className="flex items-center gap-3">
                 <img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10 md:w-12 md:h-12 object-contain" />
                 <div>
                     <h1 className="text-lg md:text-xl font-bold tracking-tight">Pesadão F.C<span className="text-primary">.</span></h1>
                     <div className={`text-[10px] font-bold uppercase tracking-wider flex items-center gap-1 ${isConnected ? 'text-green-500' : 'text-red-500'}`}>
                         <span className={`w-1.5 h-1.5 rounded-full ${isConnected ? 'bg-green-500' : 'bg-red-500'}`}></span>
                         {isConnected ? 'Online' : 'Offline'}
                     </div>
                 </div>
             </div>

             {/* Desktop Navigation */}
             <nav className="hidden md:flex bg-gray-200 dark:bg-surface-dark p-1.5 rounded-full">
                 <button onClick={() => setCurrentTab('financial')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${currentTab === 'financial' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Financeiro</button>
                 <button onClick={() => setCurrentTab('matches')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${currentTab === 'matches' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Jogos</button>
                 <button onClick={() => setCurrentTab('stats')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${currentTab === 'stats' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Jogadores</button>
             </nav>

             <button onClick={toggleTheme} className="w-10 h-10 rounded-full bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-700 flex items-center justify-center hover:text-primary transition-colors">
                 <span className="material-icons-outlined">{theme === 'dark' ? 'light_mode' : 'dark_mode'}</span>
             </button>
        </div>

        <main className="max-w-7xl mx-auto">
             {currentTab === 'financial' && renderFinancial()}
             {currentTab === 'matches' && renderMatches()}
             {currentTab === 'stats' && renderStats()}
        </main>

        {/* Mobile Bottom Navigation */}
        <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-surface-light/90 dark:bg-surface-dark/90 backdrop-blur-xl border-t border-gray-200 dark:border-gray-800 p-2 z-50 flex justify-around items-center safe-area-bottom pb-4 shadow-[0_-5px_20px_rgba(0,0,0,0.1)]">
