                    {!isConnected && (
                        <button onClick={() => setApiKeyModalOpen(true)} className="flex items-center gap-1.5 px-3 py-1.5 bg-red-500/10 text-red-500 rounded-full text-xs font-bold animate-pulse hover:bg-red-500/20 transition-colors">
                            <span className="material-icons-outlined text-sm">wifi_off</span>
                            <span className="hidden md:inline">Conectar</span>
                        </button>
