        <main className="max-w-7xl mx-auto px-4 pt-24 pb-10">
            {loading ? (
                <div className="flex flex-col items-center justify-center h-[60vh] gap-4">
                    <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                    <p className="text-muted-light font-bold text-sm animate-pulse">Carregando dados...</p>
                </div>
            ) : (
                <>
                    {currentTab === 'matches' && renderMatches()}
                    {currentTab === 'financial' && renderFinancial()}
                    {currentTab === 'stats' && (
                        <div className="flex flex-col items-center justify-center h-[50vh] text-muted-light gap-4 animation-fade-in">
                            <div className="w-20 h-20 rounded-full bg-surface-light dark:bg-surface-dark border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center">
                                <span className="material-icons-outlined text-4xl opacity-50">bar_chart</span>
                            </div>
                            <div className="text-center">
                                <h3 className="font-bold text-lg">Estatísticas</h3>
                                <p className="text-sm opacity-60">Em desenvolvimento</p>
                            </div>
                        </div>
                    )}
