                                </div>
                                <div>
                                    <label className="text-xs font-bold text-muted-light uppercase mb-1 block">Posição</label>
                                    <select value={newPlayerPosition} onChange={e => setNewPlayerPosition(e.target.value)} className="w-full bg-gray-100 dark:bg-gray-800/50 border border-gray-200 dark:border-gray-700 rounded-xl px-4 py-3 font-bold focus:border-primary focus:outline-none appearance-none">
