                    <div className="overflow-y-auto p-6">
                        {/* Score Inputs */}
                        <div className="flex items-center justify-center gap-6 mb-8 bg-gray-50 dark:bg-gray-800/30 p-4 rounded-2xl">
                             <div className="flex flex-col items-center gap-2">
                                 <span className="font-bold text-sm tracking-wider">PESADÃO</span>
                                 <input type="number" min="0" value={manualHomeScore} onChange={e => setManualHomeScore(parseInt(e.target.value) || 0)} className="w-16 h-16 text-center text-3xl font-bold rounded-xl bg-white dark:bg-black/20 border border-gray-300 dark:border-gray-600 focus:border-primary focus:outline-none" />
                             </div>
                             <span className="text-2xl font-bold text-muted-light opacity-50">X</span>
                             <div className="flex flex-col items-center gap-2">
                                 <span className="font-bold text-sm tracking-wider uppercase truncate max-w-[100px]">{selectedMatch.opponent}</span>
                                 <input type="number" min="0" value={manualAwayScore} onChange={e => setManualAwayScore(parseInt(e.target.value) || 0)} className="w-16 h-16 text-center text-3xl font-bold rounded-xl bg-white dark:bg-black/20 border border-gray-300 dark:border-gray-600 focus:border-primary focus:outline-none" />
                             </div>
                        </div>

                        {/* Players List */}
                        <div className="mb-4">
                            <div className="flex justify-between items-end mb-3">
                                <h3 className="font-bold text-sm uppercase text-muted-light">Jogadores Relacionados</h3>
                                <div className="flex gap-3">
                                    <button onClick={selectActivePlayers} className="text-xs font-bold text-primary hover:text-primary/80">Selecionar Time</button>
                                    <button onClick={resetMatchStats} className="text-xs font-bold text-red-500 hover:text-red-600">Limpar Tudo</button>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                                {players.filter(p => p.status === 'active').map(p => {
                                    const stat = matchPlayerStats[p.id] || { goals: 0, present: false };
                                    return (
                                        <div key={p.id} className={`flex items-center justify-between p-2 rounded-lg border transition-all ${stat.present ? 'bg-primary/5 border-primary/30' : 'bg-transparent border-gray-200 dark:border-gray-800 opacity-60'}`}>
                                            <div className="flex items-center gap-3">
                                                <label className="relative flex items-center cursor-pointer p-1">
                                                    <input type="checkbox" className="sr-only peer" checked={stat.present} onChange={() => toggleMatchPresence(p.id)} />
                                                    <div className="w-5 h-5 rounded border-2 border-gray-300 dark:border-gray-600 peer-checked:bg-primary peer-checked:border-primary flex items-center justify-center transition-colors">
                                                        <span className="material-icons-outlined text-white text-[12px] opacity-0 peer-checked:opacity-100">check</span>
                                                    </div>
                                                </label>
                                                <img src={p.photoUrl} className="w-8 h-8 rounded-full object-cover bg-gray-200" />
                                                <div className="flex flex-col">
                                                    <span className="text-sm font-bold leading-none mb-0.5">{p.name}</span>
                                                    <span className="text-[10px] text-muted-light font-mono">{p.position}</span>
                                                </div>
                                            </div>

                                            {stat.present && (
                                                <div className="flex items-center gap-1.5">
                                                    <button onClick={() => updateMatchStat(p.id, 'goals', -1)} className="w-6 h-6 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center hover:bg-gray-300 dark:hover:bg-gray-600 text-sm font-bold">-</button>
                                                    <span className="w-4 text-center font-bold text-sm">{stat.goals}</span>
                                                    <button onClick={() => updateMatchStat(p.id, 'goals', 1)} className="w-6 h-6 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center hover:bg-gray-300 dark:hover:bg-gray-600 text-sm font-bold text-primary">+</button>
                                                    <span className="text-[9px] font-bold uppercase text-muted-light ml-1">Gol</span>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>

                    <div className="p-4 border-t border-gray-100 dark:border-gray-800 flex gap-3 bg-gray-50 dark:bg-surface-dark">
                        <button onClick={() => setIsMatchResultModalOpen(false)} className="flex-1 py-3 rounded-xl font-bold border border-gray-200 dark:border-gray-700 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">
                            Cancelar
                        </button>
                        <button onClick={confirmMatchResult} disabled={isSubmitting} className="flex-1 py-3 rounded-xl font-bold bg-primary text-white hover:opacity-90 transition-opacity shadow-lg shadow-primary/20">
                            {isSubmitting ? 'Salvando...' : 'Confirmar Súmula'}
                        </button>
                    </div>
                </div>
            </div>
        )}

    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, ChangeEvent } from 'react';
import { Player, DbPlayer, Match, DbMatch } from './types';
import { getSupabase, saveSupabaseKey, SUPABASE_URL } from './supabaseClient';

const DEFAULT_FEE = 40;

const App: React.FC = () => {
  // --- STATE ---
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [currentTab, setCurrentTab] = useState<'financial' | 'matches' | 'stats'>('matches'); 

  // Data State
  const [players, setPlayers] = useState<Player[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);

  // Financial Specific State
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  // Connection State
  const [apiKeyModalOpen, setApiKeyModalOpen] = useState(false);
  const [apiKeyInput, setApiKeyInput] = useState('');
  const [isConnected, setIsConnected] = useState(false);

  // Inline Editing State
  const [editingDateId, setEditingDateId] = useState<string | null>(null);
  const [editingNameId, setEditingNameId] = useState<string | null>(null);
  const [editingJerseyId, setEditingJerseyId] = useState<string | null>(null);
  const [tempName, setTempName] = useState<string>('');

  // Modals State
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // Matches View Mode
  const [matchViewMode, setMatchViewMode] = useState<'upcoming' | 'history'>('upcoming');

  // MATCH RESULT MODAL STATE
  const [isMatchResultModalOpen, setIsMatchResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);
  const [manualHomeScore, setManualHomeScore] = useState(0);
  const [manualAwayScore, setManualAwayScore] = useState(0);
  // Atualizado para controlar presença
  const [matchPlayerStats, setMatchPlayerStats] = useState<Record<string, {goals: number, present: boolean}>>({});

  // Forms State
  const [newPlayerName, setNewPlayerName] = useState('');
  const [newPlayerNumber, setNewPlayerNumber] = useState('');
  const [newPlayerPhoto, setNewPlayerPhoto] = useState<string | null>(null);
  const [newPlayerPosition, setNewPlayerPosition] = useState('MEI');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [newMatchOpponent, setNewMatchOpponent] = useState('');
  const [newMatchLocation, setNewMatchLocation] = useState('');
  const [newMatchDate, setNewMatchDate] = useState(new Date().toISOString().split('T')[0]);
  const [newMatchTime, setNewMatchTime] = useState('');
  const [newMatchLocationImg, setNewMatchLocationImg] = useState<string | null>(null);

  // Edit Stats State
  const [editingStatsId, setEditingStatsId] = useState<string | null>(null);
  const [tempStats, setTempStats] = useState({ goals: 0, matchesPlayed: 0, overall: 0, position: '' });

  // --- INITIALIZATION ---

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  // Load Data
  useEffect(() => {
    const supabase = getSupabase();
    if (!supabase) {
      setApiKeyModalOpen(true);
      setLoading(false);
      return;
    }
    setIsConnected(true);
    fetchData();

    const channelPlayers = supabase.channel('realtime-players')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'players' }, () => fetchData())
      .subscribe();

    const channelMatches = supabase.channel('realtime-matches')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, () => fetchData())
      .subscribe();

    return () => {
      supabase.removeChannel(channelPlayers);
      supabase.removeChannel(channelMatches);
    };
  }, []);

  const fetchData = async () => {
    const supabase = getSupabase();
    if (!supabase) return;

    try {
      const { data: dataPlayers } = await supabase.from('players').select('*').order('name', { ascending: true });
      if (dataPlayers) {
        setPlayers(dataPlayers.map((p: any) => ({
          id: p.id.toString(),
          name: p.name,
          photoUrl: p.photo_url || 'https://via.placeholder.com/150',
          isPaid: false, 
          paymentDate: undefined,
          value: p.value,
          jerseyNumber: p.jersey_number,
          status: (p.status === 'injured' ? 'injured' : 'active') as 'active' | 'injured',
          paymentHistory: parsePaymentHistory(p.payment_date),
          position: p.position || 'MEI',
          goals: p.goals || 0,
          matchesPlayed: p.matches_played || 0,
          lastPlayedDate: p.last_played_date, // Mapeando do DB
          overall: p.overall || 75
        })));
      }

      const { data: dataMatches } = await supabase.from('matches').select('*').order('date', { ascending: true });
      if (dataMatches) {
        setMatches(dataMatches.map((m: DbMatch) => ({
          id: m.id.toString(),
          opponent: m.opponent,
          locationImg: m.location_img,
          location: m.location || '',
          date: m.date,
          time: m.time,
          homeScore: m.home_score,
          awayScore: m.away_score,
          result: m.result as any,
          isFinished: m.is_finished
        })));
      }
    } catch (error) {
      console.error("Erro ao buscar dados:", error);
    } finally {
      setLoading(false);
    }
  };

  // --- HELPERS ---

  const getMonthKey = (date: Date) => {
    const m = (date.getMonth() + 1).toString().padStart(2, '0');
    const y = date.getFullYear();
    return `${m}-${y}`;
  };

  const parsePaymentHistory = (dateStr: string | null): Record<string, string> => {
    if (!dateStr) return {};
    try {
        const parsed = JSON.parse(dateStr);
        if (typeof parsed === 'object' && parsed !== null) return parsed;
        return {};
    } catch (e) {
        return dateStr ? { [getMonthKey(new Date())]: dateStr } : {};
    }
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  const formattedDate = useMemo(() => {
    const options: Intl.DateTimeFormatOptions = { month: 'long', year: 'numeric' };
    const str = selectedDate.toLocaleDateString('pt-BR', options);
    return str.charAt(0).toUpperCase() + str.slice(1);
  }, [selectedDate]);

  const changeMonth = (increment: number) => {
    const newDate = new Date(selectedDate);
    newDate.setMonth(newDate.getMonth() + increment);
    setSelectedDate(newDate);
  };

  const getNextSundays = () => {
      const dates = [];
      let d = new Date();
      d.setDate(d.getDate() + (7 - d.getDay()) % 7);
      for(let i=0; i<6; i++) {
          dates.push(new Date(d));
          d.setDate(d.getDate() + 7);
      }
      return dates;
  };

  // --- STATS CALCULATION ---

  const currentMonthKey = getMonthKey(selectedDate);

  const playersView = useMemo(() => {
    return players.map(player => ({
        ...player,
        isPaid: !!player.paymentHistory[currentMonthKey],
        paymentDate: player.paymentHistory[currentMonthKey]
    }));
  }, [players, currentMonthKey]);

  const financialStats = useMemo(() => {
    const active = playersView.filter(p => p.status === 'active' || p.isPaid);
    const collected = playersView.reduce((acc, p) => acc + (p.isPaid ? p.value : 0), 0);
    const potential = active.reduce((acc, p) => acc + p.value, 0);
    const count = active.length;
    const paid = playersView.filter(p => p.isPaid).length;
    return { collected, potential, paid, count, progress: count > 0 ? (paid / count) * 100 : 0 };
  }, [playersView]);

  const topPayers = useMemo(() => playersView.filter(p => p.isPaid && p.status === 'active').slice(0, 3), [playersView]);

  const matchStats = useMemo(() => {
    const finished = matches.filter(m => m.isFinished);
    const wins = finished.filter(m => m.result === 'win').length;
    const draws = finished.filter(m => m.result === 'draw').length;
    const losses = finished.filter(m => m.result === 'loss').length;
    const total = finished.length;
    const goalsFor = finished.reduce((acc, m) => acc + m.homeScore, 0);
    const goalsAgainst = finished.reduce((acc, m) => acc + m.awayScore, 0);
    const goalDiff = goalsFor - goalsAgainst;

    return { 
        wins, draws, losses, total, 
        winRate: total > 0 ? Math.round((wins / total) * 100) : 0,
        goalsFor, goalsAgainst, goalDiff
    };
  }, [matches]);

  const topScorers = useMemo(() => [...players].sort((a, b) => b.goals - a.goals).slice(0, 5), [players]);

  const topAppearances = useMemo(() => [...players].sort((a, b) => b.matchesPlayed - a.matchesPlayed).slice(0, 3), [players]);

  // --- ACTIONS ---

  const handleSaveKey = (e: React.FormEvent) => {
    e.preventDefault();
    if (apiKeyInput.trim()) {
      saveSupabaseKey(apiKeyInput.trim());
      setApiKeyModalOpen(false);
    }
  };

  const togglePayment = async (id: string) => {
    const supabase = getSupabase();
    if (!supabase) return;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const newHistory = { ...player.paymentHistory };
    const isPaid = !!newHistory[currentMonthKey];

    if (isPaid) delete newHistory[currentMonthKey];
    else newHistory[currentMonthKey] = new Date().toLocaleDateString('pt-BR');

    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    await supabase.from('players').update({ payment_date: JSON.stringify(newHistory), is_paid: !isPaid }).eq('id', id);
  };

  const updatePaymentDate = async (id: string, dateValue: string) => {
    if (!dateValue) return;
    const [year, month, day] = dateValue.split('-');
    const formatted = `${day}/${month}/${year}`;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const newHistory = { ...player.paymentHistory, [currentMonthKey]: formatted };
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    setEditingDateId(null);
    const supabase = getSupabase();
    if (supabase) await supabase.from('players').update({ payment_date: JSON.stringify(newHistory) }).eq('id', id);
  };

  const handlePhotoUpload = (e: ChangeEvent<HTMLInputElement>, setter: (val: string) => void) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => setter(reader.result as string);
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const updatePlayerPhoto = async (id: string, e: ChangeEvent<HTMLInputElement>) => {
    handlePhotoUpload(e, async (base64) => {
        const supabase = getSupabase();
        if(supabase) await supabase.from('players').update({ photo_url: base64 }).eq('id', id);
        fetchData();
    });
  };

  const deletePlayer = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Remover jogador?")) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').delete().eq('id', id);
      setPlayers(prev => prev.filter(p => p.id !== id));
    }
  };

  const togglePlayerStatus = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const player = players.find(p => p.id === id);
    if(!player) return;
    const newStatus = player.status === 'active' ? 'injured' : 'active';
    const supabase = getSupabase();
    if(supabase) await supabase.from('players').update({ status: newStatus }).eq('id', id);
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
  };

  const startEditingName = (player: Player) => {
    setTempName(player.name);
    setEditingNameId(player.id);
  };

  const savePlayerName = async (id: string) => {
    if (tempName.trim()) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').update({ name: tempName.trim() }).eq('id', id);
      setPlayers(prev => prev.map(p => p.id === id ? { ...p, name: tempName.trim() } : p));
    }
    setEditingNameId(null);
  };

  const saveJerseyNumber = async (id: string, newNumber: string) => {
    const num = parseInt(newNumber);
    if (!isNaN(num)) {
         const supabase = getSupabase();
         if(supabase) await supabase.from('players').update({ jersey_number: num }).eq('id', id);
         setPlayers(prev => prev.map(p => p.id === id ? { ...p, jerseyNumber: num } : p));
    }
    setEditingJerseyId(null);
  };

  const handleAddPlayer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlayerName.trim() || !newPlayerPhoto || isSubmitting) return;

    setIsSubmitting(true);
    const supabase = getSupabase();
    if (supabase) {
        const fullPayload = {
            name: newPlayerName,
            photo_url: newPlayerPhoto,
            is_paid: false,
            value: DEFAULT_FEE,
            jersey_number: parseInt(newPlayerNumber) || 0,
            status: 'active',
            payment_date: JSON.stringify({}),
            position: newPlayerPosition,
            goals: 0,
            matches_played: 0,
            overall: 70
        };

        const { error } = await supabase.from('players').insert([fullPayload]);

        if (error) {
            console.warn("Insert completo falhou. Tentando fallback básico.", error.message);
            const basicPayload = {
                name: newPlayerName,
                photo_url: newPlayerPhoto,
                is_paid: false,
                value: DEFAULT_FEE,
                jersey_number: parseInt(newPlayerNumber) || 0,
                status: 'active',
                payment_date: JSON.stringify({})
            };
            const { error: basicError } = await supabase.from('players').insert([basicPayload]);
            if (basicError) {
                alert(`Erro ao salvar jogador: ${basicError.message}`);
                setIsSubmitting(false);
                return;
            }
        }
        await fetchData();
    }

    setNewPlayerName('');
    setNewPlayerNumber('');
    setNewPlayerPhoto(null);
    setIsAddModalOpen(false);
    setIsSubmitting(false);
  };

  const openPlayerProfile = (player: Player) => {
      setTempStats({
          goals: player.goals,
          matchesPlayed: player.matchesPlayed,
          overall: player.overall,
          position: player.position
      });
      setEditingStatsId(player.id);
  };

  const savePlayerStats = async () => {
      if(!editingStatsId) return;
      const supabase = getSupabase();
      if(supabase) {
          const { error } = await supabase.from('players').update({
              goals: tempStats.goals,
              matches_played: tempStats.matchesPlayed,
              overall: tempStats.overall,
              position: tempStats.position
          }).eq('id', editingStatsId);

          if (error) {
             alert("Erro ao atualizar estatísticas. Verifique se as colunas existem.\n" + error.message);
          } else {
             setPlayers(prev => prev.map(p => p.id === editingStatsId ? { ...p, ...tempStats } : p));
          }
      }
      setEditingStatsId(null);
  };

  const handleAddMatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if(isSubmitting) return;
    setIsSubmitting(true);

    const supabase = getSupabase();
    if(supabase) {
        if (matches.some(m => m.date === newMatchDate)) {
            if(!window.confirm("Já existe um jogo nesta data. Deseja marcar outro?")) {
                setIsSubmitting(false);
                return;
            }
        }

        const { error } = await supabase.from('matches').insert([{
            opponent: newMatchOpponent,
            location: newMatchLocation,
            date: newMatchDate,
            time: newMatchTime,
            location_img: newMatchLocationImg,
            result: 'pending',
            is_finished: false
        }]);

        if (error) {
            alert(`Erro ao criar partida: ${error.message}`);
            setIsSubmitting(false);
            return;
        }
        await fetchData();
    }
    setNewMatchOpponent('');
    setNewMatchLocation('');
    setNewMatchDate(new Date().toISOString().split('T')[0]);
    setNewMatchTime('');
    setNewMatchLocationImg(null);
    setIsAddModalOpen(false);
    setIsSubmitting(false);
  };

  const deleteMatch = async (id: string, e: React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();

      const confirmDelete = window.confirm("Tem certeza que deseja excluir esta partida?");
      if (!confirmDelete) return;

      const previousMatches = [...matches];
      setMatches(prev => prev.filter(m => m.id !== id));

      const supabase = getSupabase();
      if(!supabase) {
          setMatches(previousMatches); 
          return;
      }

      try {
          const { error } = await supabase.from('matches').delete().eq('id', parseInt(id));
          if (error) {
              alert("Erro ao excluir partida no banco de dados: " + error.message);
              setMatches(previousMatches); 
          }
      } catch (err: any) {
          alert("Ocorreu um erro ao tentar excluir: " + err.message);
          setMatches(previousMatches); 
      }
  };

  const openMatchResultModal = (match: Match) => {
      setSelectedMatch(match);
      setManualHomeScore(match.isFinished ? match.homeScore : 0);
      setManualAwayScore(match.isFinished ? match.awayScore : 0);

      const initialStats: Record<string, {goals: number, present: boolean}> = {};
      players.filter(p => p.status === 'active').forEach(p => {
          // Por padrão, ninguém está presente até ser selecionado
          initialStats[p.id] = { goals: 0, present: false };
      });
      setMatchPlayerStats(initialStats);

      setIsMatchResultModalOpen(true);
  };

  const toggleMatchPresence = (playerId: string) => {
      setMatchPlayerStats(prev => ({
          ...prev,
          [playerId]: {
              ...prev[playerId],
              present: !prev[playerId].present,
              // Se desmarcar presença, zera os gols
              goals: !prev[playerId].present ? prev[playerId].goals : 0
          }
      }));
  };

  const selectActivePlayers = () => {
       const newStats = { ...matchPlayerStats };
       // Seleciona os primeiros 11 jogadores como exemplo ou todos
       Object.keys(newStats).forEach((key, index) => {
           if (index < 11) newStats[key].present = true;
       });
       setMatchPlayerStats(newStats);
  };

  const resetMatchStats = () => {
      const newStats = { ...matchPlayerStats };
      Object.keys(newStats).forEach(key => {
          newStats[key] = { goals: 0, present: false };
      });
      setMatchPlayerStats(newStats);
  };

  const updateMatchStat = (playerId: string, type: 'goals', delta: number) => {
      setMatchPlayerStats(prev => {
          if (!prev[playerId].present) return prev; // Não altera se não estiver presente
          return {
              ...prev,
              [playerId]: {
                  ...prev[playerId],
                  [type]: Math.max(0, (prev[playerId]?.[type] || 0) + delta)
              }
          }
      });
  };

  const confirmMatchResult = async () => {
      if (!selectedMatch) return;
      const supabase = getSupabase();
      if (!supabase) return;

      setIsSubmitting(true);

      let result = 'draw';
      if (manualHomeScore > manualAwayScore) result = 'win';
      if (manualHomeScore < manualAwayScore) result = 'loss';

      const { error: matchError } = await supabase.from('matches').update({
          home_score: manualHomeScore,
          away_score: manualAwayScore,
          result: result,
          is_finished: true
      }).eq('id', parseInt(selectedMatch.id));

      if (matchError) {
          alert("Erro ao salvar placar: " + matchError.message);
          setIsSubmitting(false);
          return;
      }

      if (!selectedMatch.isFinished) {
          const updates = [];
          for (const playerId in matchPlayerStats) {
                const stats = matchPlayerStats[playerId];
                const player = players.find(p => p.id === playerId);

