                               <div className="flex items-center gap-3">
                                   <div className={`w-6 h-6 rounded-full flex items-center justify-center border transition-colors ${isPresent ? 'bg-green-500 border-green-500' : 'border-gray-400 bg-transparent'}`}>
                                       {isPresent && <span className="material-icons-outlined text-white text-sm">check</span>}
