             </div>
         </div>
      )}

      {/* Editing Stats Modal */}
      {editingStatsId && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
             <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl w-full max-w-sm border border-gray-200 dark:border-gray-700 shadow-2xl">
                 <h3 className="font-bold text-lg mb-4">Editar Estatísticas</h3>
