                         <input type="number" className="w-full bg-gray-100 dark:bg-gray-900 border-none rounded-xl px-4 py-2 outline-none" value={tempStats.overall} onChange={e => setTempStats({...tempStats, overall: parseInt(e.target.value)})} />
                     </div>
                     <div>
                         <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Gols Totais</label>
                         <input type="number" className="w-full bg-gray-100 dark:bg-gray-900 border-none rounded-xl px-4 py-2 outline-none" value={tempStats.goals} onChange={e => setTempStats({...tempStats, goals: parseInt(e.target.value)})} />
                     </div>
                     <div>
                         <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Partidas Jogadas</label>
                         <input type="number" className="w-full bg-gray-100 dark:bg-gray-900 border-none rounded-xl px-4 py-2 outline-none" value={tempStats.matchesPlayed} onChange={e => setTempStats({...tempStats, matchesPlayed: parseInt(e.target.value)})} />
                     </div>
                     <div className="flex gap-2 pt-2">
                         <button onClick={() => setEditingStatsId(null)} className="flex-1 bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 font-bold py-2 rounded-xl">Cancelar</button>
                         <button onClick={savePlayerStats} className="flex-1 bg-primary text-white font-bold py-2 rounded-xl">Salvar</button>
                     </div>
                 </div>
             </div>
        </div>
      )}
    </div>
  );
};

export default App;

