                                className={`p-1 rounded text-[10px] ${p.status === 'injured' ? 'bg-orange-100 text-orange-600 hover:bg-orange-200' : 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-400 hover:text-orange-500'}`}
                                title={p.status === 'injured' ? "Retornar ao elenco" : "Reportar lesão"}
