                            <button onClick={() => setIsAddModalOpen(true)} className="mt-4 text-primary font-bold text-sm hover:underline">
                                Agendar agora
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
    </div>
  );
  };

  const renderStats = () => {
    // Find last finished match to display in cards
    const lastMatch = matches.filter(m => m.isFinished).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

    const renderRankingItem = (p: Player, i: number, value: number, type: 'goals' | 'matches') => {
        let rankColors = "border-gray-100 dark:border-gray-800 bg-surface-light dark:bg-surface-dark";
        let textRank = "text-muted-light";
        let icon = null;

        if (i === 0) {
            rankColors = "border-yellow-500/50 bg-gradient-to-r from-yellow-500/10 to-transparent";
            textRank = "text-yellow-500";
            icon = "emoji_events";
        } else if (i === 1) {
            rankColors = "border-gray-400/50 bg-gradient-to-r from-gray-400/10 to-transparent";
            textRank = "text-gray-400";
        } else if (i === 2) {
            rankColors = "border-orange-700/50 bg-gradient-to-r from-orange-700/10 to-transparent";
            textRank = "text-orange-700";
        }

        return (
            <div key={p.id} className={`flex items-center justify-between p-4 md:p-3 rounded-xl border ${rankColors} transition-all`}>
                <div className="flex items-center gap-4">
                    <div className={`flex flex-col items-center justify-center w-8 ${textRank}`}>
                        {i === 0 && icon ? <span className="material-icons-outlined text-xl mb-1">{icon}</span> : <span className="font-black text-xl md:text-lg">{i + 1}</span>}
                    </div>
                    <img src={p.photoUrl} className="w-14 h-14 md:w-10 md:h-10 rounded-full object-cover border-2 border-white/10 shadow-sm" />
                    <div>
                        <span className="font-bold text-base md:text-sm block">{p.name}</span>
                        <span className="text-xs text-muted-light font-bold bg-black/5 dark:bg-white/5 px-2 py-0.5 rounded-full">{p.position}</span>
                    </div>
                </div>
                <div className="flex flex-col items-end">
                    <span className={`text-2xl md:text-xl font-black ${textRank}`}>{value}</span>
                    <span className="text-[10px] uppercase font-bold text-muted-light">{type === 'goals' ? 'Gols' : 'Jogos'}</span>
                </div>
            </div>
        );
    };

    return (
    <div className="space-y-8 animation-fade-in pb-20">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800">
                <h3 className="font-bold mb-4 flex items-center gap-2 text-primary text-lg"><span className="material-icons-outlined">sports_soccer</span> Artilheiros</h3>
                <div className="space-y-3">
                    {topScorers.map((p, i) => renderRankingItem(p, i, p.goals, 'goals'))}
                    {topScorers.length === 0 && <p className="text-muted-light text-sm">Sem dados</p>}
                </div>
            </div>

            <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800">
