                 return (
                 <div 
                    key={p.id} 
                    onClick={() => openPlayerProfile(p)} 
                    className="relative group h-[400px] bg-gradient-to-b from-white to-gray-100 dark:from-[#1a1d22] dark:to-[#0f1115] rounded-[2.5rem] border border-gray-200 dark:border-gray-800 transition-all duration-500 hover:-translate-y-2 hover:shadow-2xl hover:border-primary/50 overflow-hidden flex flex-col items-center justify-between py-6 cursor-pointer"
                 >
                      {/* Background Accents */}
                      <div className="absolute top-0 right-0 w-40 h-40 bg-primary/10 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
                      <div className="absolute bottom-0 left-0 w-40 h-40 bg-primary/5 rounded-full blur-3xl -ml-16 -mb-16 pointer-events-none"></div>

