                                key={p.id} 
                                onClick={() => toggleMatchPresence(p.id)}
                                className={`flex items-center justify-between p-3 rounded-xl border transition-all cursor-pointer select-none ${isPresent ? 'bg-white dark:bg-surface-dark border-green-500 shadow-md ring-1 ring-green-500/20' : 'bg-gray-100 dark:bg-black/20 border-transparent opacity-60 hover:opacity-80'}`}
