                                     ) : (
                                         <span className="text-[10px] font-bold uppercase text-white bg-red-500 px-2 py-0.5 rounded-full shadow-lg shadow-red-500/20">Não Pagou</span>
                                     )}
                                  </div>
                             </div>

                             {/* Footer Controls */}
                             <div className="absolute bottom-0 w-full px-6 z-20 bg-gradient-to-t from-black/90 to-transparent pt-10 pb-6">
                                 <div className="flex items-center justify-between border-t border-white/20 pt-4">
                                     <div className="flex flex-col">
                                        <span className="text-[9px] uppercase font-bold text-gray-400 tracking-wider">Mensalidade</span>
                                        <span className={`font-bold text-lg ${p.status === 'injured' ? 'line-through text-gray-500' : 'text-white'}`}>R$ {p.value}</span>
                                     </div>

                                     <label className={`cursor-pointer ${p.status === 'injured' ? 'opacity-50 pointer-events-none' : ''}`}>
                                          <input type="checkbox" className="sr-only peer" checked={p.isPaid} onChange={() => togglePayment(p.id)} disabled={p.status === 'injured'} />
                                          <div className="w-12 h-7 bg-white/10 rounded-full peer-checked:bg-primary transition-all relative backdrop-blur-md border border-white/10 shadow-inner">
                                              <div className={`absolute top-1 left-1 bg-white w-5 h-5 rounded-full transition-all shadow-md ${p.isPaid ? 'translate-x-5' : ''}`}></div>
                                          </div>
                                     </label>
                                 </div>
                             </div>
                         </div>
                     )
                 })}
                 <button onClick={() => setIsAddModalOpen(true)} className="group h-[280px] md:h-[340px] flex flex-col items-center justify-center bg-surface-light dark:bg-surface-dark border-2 border-dashed border-gray-200 dark:border-gray-800 rounded-[2.5rem] hover:border-primary/50 hover:bg-primary/5 transition-all">
                      <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center mb-4 group-hover:bg-primary group-hover:text-white transition-colors">
                         <span className="material-icons-outlined text-3xl text-gray-400 group-hover:text-white">add</span>
                      </div>
                      <span className="font-bold text-muted-light group-hover:text-primary">Adicionar Jogador</span>
                 </button>
            </div>
        </div>
    </div>
  );

