                            <button onClick={() => setIsAddModalOpen(true)} className="mt-4 text-primary font-bold text-sm hover:underline">
                                Agendar agora
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
    </div>
  );
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${theme === 'dark' ? 'dark bg-[#0f1115]' : 'bg-gray-50'}`}>
      <div className="dark:text-white min-h-screen flex flex-col font-sans">
        <nav className="sticky top-0 z-40 w-full backdrop-blur-xl bg-white/70 dark:bg-[#0f1115]/80 border-b border-gray-200 dark:border-gray-800">
            <div className="container mx-auto px-4 h-16 flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <span className="material-icons-outlined text-primary text-2xl">sports_soccer</span>
