                <div className="flex items-center gap-1 bg-gray-100 dark:bg-gray-800 p-1 rounded-full">
                    <button onClick={() => setCurrentTab('matches')} className={`px-4 py-1.5 rounded-full text-sm font-bold transition-all ${currentTab === 'matches' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary' : 'text-gray-500 hover:text-gray-900 dark:hover:text-white'}`}>Partidas</button>
                    <button onClick={() => setCurrentTab('financial')} className={`px-4 py-1.5 rounded-full text-sm font-bold transition-all ${currentTab === 'financial' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary' : 'text-gray-500 hover:text-gray-900 dark:hover:text-white'}`}>Financeiro</button>
                    <button onClick={() => setCurrentTab('stats')} className={`px-4 py-1.5 rounded-full text-sm font-bold transition-all ${currentTab === 'stats' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary' : 'text-gray-500 hover:text-gray-900 dark:hover:text-white'}`}>Estatísticas</button>
                </div>

                <button onClick={toggleTheme} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">
                    <span className="material-icons-outlined">{theme === 'dark' ? 'light_mode' : 'dark_mode'}</span>
                </button>
            </div>
        </nav>

        <main className="container mx-auto px-4 py-8 flex-grow">
            {loading ? (
                <div className="flex items-center justify-center h-64">
                    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary"></div>
