                                          <input type="checkbox" className="sr-only peer" checked={p.isPaid} onChange={() => togglePayment(p.id)} disabled={p.status === 'injured'} />
                                          <div className="w-12 h-7 bg-white/10 rounded-full peer-checked:bg-primary transition-all relative backdrop-blur-md border border-white/10 shadow-inner">
                                              <div className={`absolute top-1 left-1 bg-white w-5 h-5 rounded-full transition-all shadow-md ${p.isPaid ? 'translate-x-5' : ''}`}></div>
                                          </div>
                                     </label>
                                 </div>
                             </div>
                         </div>
                     )
                 })}
                 <button onClick={() => setIsAddModalOpen(true)} className="flex flex-col items-center justify-center bg-surface-light dark:bg-surface-dark border border-gray-100 dark:border-gray-800 rounded-2xl p-6 hover:shadow-lg transition-all text-muted-light group min-h-[160px]">
                     <span className="material-icons-outlined text-3xl md:text-4xl mb-2 group-hover:scale-110 transition-transform group-hover:text-primary">add_circle_outline</span>
                     <span className="font-bold text-sm group-hover:text-primary">Adicionar</span>
                 </button>
            </div>
        </div>
    </div>
  );

  const renderMatches = () => {
    const nextSundays = getNextSundays();
    const upcomingMatches = matches.filter(m => !m.isFinished).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    const finishedMatches = matches.filter(m => m.isFinished).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const displayMatches = matchViewMode === 'upcoming' ? upcomingMatches : finishedMatches;

    // Filtro de busca (client-side)
    const filteredMatches = displayMatches.filter(m => 
        m.opponent.toLowerCase().includes(searchQuery.toLowerCase()) || 
        (m.location && m.location.toLowerCase().includes(searchQuery.toLowerCase()))
    );

    return (
    <div className="space-y-8 animation-fade-in pb-20">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
             <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800 flex items-center justify-between relative overflow-hidden">
                  <div className="z-10">
                      <h3 className="text-muted-light font-bold text-sm uppercase">Aproveitamento</h3>
                      <p className="text-4xl font-bold mt-2">{matchStats.winRate}%</p>
                  </div>
                  <div className="relative w-24 h-24 p-1">
                      <svg className="w-full h-full transform -rotate-90" viewBox="0 0 100 100">
                          <circle cx="50" cy="50" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-200 dark:text-gray-800" />
                          <circle cx="50" cy="50" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={251} strokeDashoffset={251 - (251 * matchStats.winRate) / 100} className="text-green-500 transition-all duration-1000" />
                      </svg>
                  </div>
             </div>

             <div className="lg:col-span-2 grid grid-cols-3 gap-2 md:gap-4">
                 <div className="bg-green-500/10 border border-green-500/20 rounded-2xl p-2 md:p-4 flex flex-col items-center justify-center">
                     <span className="text-2xl md:text-3xl font-bold text-green-500">{matchStats.wins}</span>
                     <span className="text-[10px] md:text-xs font-bold uppercase text-green-700 dark:text-green-400">Vitórias</span>
                 </div>
                 <div className="bg-gray-200/50 dark:bg-gray-700/30 border border-gray-300 dark:border-gray-700 rounded-2xl p-2 md:p-4 flex flex-col items-center justify-center">
                     <span className="text-2xl md:text-3xl font-bold text-gray-500 dark:text-gray-300">{matchStats.draws}</span>
                     <span className="text-[10px] md:text-xs font-bold uppercase text-gray-600 dark:text-gray-400">Empates</span>
                 </div>
                 <div className="bg-red-500/10 border border-red-500/20 rounded-2xl p-2 md:p-4 flex flex-col items-center justify-center">
                     <span className="text-2xl md:text-3xl font-bold text-red-500">{matchStats.losses}</span>
                     <span className="text-[10px] md:text-xs font-bold uppercase text-red-700 dark:text-red-400">Derrotas</span>
                 </div>
             </div>

             <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800 flex flex-col justify-center">
                  <h3 className="text-muted-light font-bold text-xs uppercase mb-3">Resumo da Temporada</h3>
                  <div className="flex justify-between items-end border-b border-gray-100 dark:border-gray-700 pb-2 mb-2">
                      <span className="text-xs font-bold">Jogos</span>
                      <span className="font-bold text-gray-900 dark:text-white text-lg">{matchStats.total}</span>
                  </div>
                  <div className="flex justify-between items-end border-b border-gray-100 dark:border-gray-700 pb-2 mb-2">
                      <span className="text-xs font-bold">Gols Pró</span>
                      <span className="font-bold text-green-500 text-lg">{matchStats.goalsFor}</span>
                  </div>
                  <div className="flex justify-between items-end border-b border-gray-100 dark:border-gray-700 pb-2 mb-2">
                      <span className="text-xs font-bold">Gols Contra</span>
                      <span className="font-bold text-red-500 text-lg">{matchStats.goalsAgainst}</span>
                  </div>
                  <div className="flex justify-between items-end">
                      <span className="text-xs font-bold">Saldo</span>
                      <span className={`font-bold text-lg ${matchStats.goalDiff >= 0 ? 'text-primary' : 'text-red-500'}`}>{matchStats.goalDiff > 0 ? '+' : ''}{matchStats.goalDiff}</span>
                  </div>
             </div>
        </div>

        <div className="space-y-4">
            <h3 className="text-lg font-bold flex items-center gap-2"><span className="material-icons-outlined text-primary">event_available</span> Domingos de Jogo</h3>
            <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide">
                {nextSundays.map((d, i) => {
                    const dateStr = d.toISOString().split('T')[0];
                    const isBooked = matches.some(m => m.date === dateStr);
                    return (
                        <div key={i} className={`flex-shrink-0 w-20 h-24 rounded-2xl flex flex-col items-center justify-center border-2 transition-all ${isBooked ? 'bg-primary border-primary text-white shadow-lg shadow-primary/30' : 'bg-surface-light dark:bg-surface-dark border-gray-200 dark:border-gray-800 text-muted-light'}`}>
                             <span className="text-xs font-bold uppercase opacity-80">{d.toLocaleDateString('pt-BR', {month: 'short'}).replace('.','')}</span>
                             <span className="text-3xl font-bold my-1">{d.getDate()}</span>
                             <span className="text-[10px] font-bold uppercase">{isBooked ? 'JOGO' : 'LIVRE'}</span>
                        </div>
                    );
                })}
            </div>
        </div>

        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-4">
                <div className="flex flex-col sm:flex-row items-center gap-4 w-full md:w-auto">
                    <h3 className="text-lg font-bold">Agenda de Jogos</h3>
                    <div className="flex bg-gray-200 dark:bg-surface-dark p-1 rounded-lg">
                        <button onClick={() => setMatchViewMode('upcoming')} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${matchViewMode === 'upcoming' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Próximos</button>
                        <button onClick={() => setMatchViewMode('history')} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${matchViewMode === 'history' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Histórico</button>
                    </div>
                </div>

                <div className="flex w-full md:w-auto items-center gap-3">
                    <div className="relative group w-full md:w-auto">
                         <span className="absolute left-3 top-1/2 -translate-y-1/2 material-icons-outlined text-gray-400 group-focus-within:text-primary transition-colors text-sm">search</span>
                         <input 
                            type="text" 
                            placeholder="Buscar..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full md:w-40 focus:w-64 transition-all duration-300 ease-out bg-white dark:bg-black/20 hover:bg-white dark:hover:bg-surface-dark focus:bg-white dark:focus:bg-surface-dark border border-gray-200 dark:border-gray-700 focus:border-primary/30 rounded-full pl-9 pr-4 py-2 text-sm font-bold placeholder-gray-400 focus:outline-none focus:shadow-lg focus:shadow-primary/10"
                         />
                    </div>

                    <button onClick={() => setIsAddModalOpen(true)} className="hidden md:flex bg-primary hover:opacity-90 text-white px-4 py-2 rounded-xl font-bold text-sm shadow-lg shadow-primary/20 items-center gap-2 whitespace-nowrap">
                        <span className="material-icons-outlined text-lg">add</span> Nova Partida
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {filteredMatches.map(m => (
                    <div 
                        key={m.id} 
                        className={`relative rounded-2xl overflow-hidden flex flex-col shadow-sm animation-fade-in group transition-all duration-300
                            ${matchViewMode === 'upcoming' 
                                ? 'bg-gradient-to-br from-primary to-orange-500 dark:from-primary dark:to-orange-500 text-white shadow-lg' 
                                : 'bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-800 grayscale opacity-80 hover:grayscale-0 hover:opacity-100'
                            }`}
                    >
                        <div className="absolute top-3 right-3 z-50">
                            <button onClick={(e) => deleteMatch(m.id, e)} className={`p-2 rounded-full transition-colors cursor-pointer ${matchViewMode === 'upcoming' ? 'text-white/80 hover:bg-white/20 hover:text-white' : 'text-gray-400 hover:text-red-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}>
                                <span className="material-icons-outlined text-lg">delete_outline</span>
                            </button>
                        </div>

                        {/* Status Badge */}
                        <div className="absolute top-4 left-4 z-40">
                             {m.isFinished ? (
                                 <span className={`text-[10px] font-bold uppercase px-2 py-1 rounded backdrop-blur-md shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/20 text-white' : (m.result === 'win' ? 'bg-green-100 text-green-600' : m.result === 'loss' ? 'bg-red-100 text-red-600' : 'bg-gray-100 text-gray-600')}`}>
                                     {m.result === 'win' ? 'Vitória' : m.result === 'loss' ? 'Derrota' : 'Empate'}
                                 </span>
                             ) : (
                                 <span className="text-[10px] font-bold uppercase px-2 py-1 rounded bg-white/20 text-white backdrop-blur-md shadow-sm animate-pulse">Em Breve</span>
                             )}
                        </div>

                        <div className="p-6 pt-14 flex items-center justify-between">
                             <div className="flex flex-col items-center gap-2 w-1/3">
                                 <img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10 md:w-14 md:h-14 object-contain drop-shadow-md" />
                                 <span className={`font-bold text-xs md:text-sm hidden sm:block ${matchViewMode === 'upcoming' ? 'text-white' : ''}`}>Pesadão</span>
                             </div>

                             <div className="flex flex-col items-center justify-center w-1/3">
                                 <div className={`px-2 md:px-4 py-1 md:py-2 rounded-lg font-mono text-3xl md:text-4xl font-bold tracking-widest mb-2 ${matchViewMode === 'upcoming' ? 'text-white' : 'text-gray-900 dark:text-white'}`}>
                                     {m.isFinished ? `${m.homeScore}-${m.awayScore}` : 'VS'}
                                 </div>

                                 <div className={`flex flex-col items-center gap-1 text-[10px] md:text-xs font-bold uppercase ${matchViewMode === 'upcoming' ? 'text-white/90' : 'text-muted-light'}`}>
                                     <div className="flex items-center gap-1 bg-black/10 dark:bg-white/5 px-2 py-0.5 rounded-full">
                                        <span className="material-icons-outlined text-[12px]">calendar_today</span>
                                        <span>{new Date(m.date + 'T00:00:00').toLocaleDateString('pt-BR')}</span>
                                     </div>
                                     <div className="flex items-center gap-1">
                                        <span>{m.time.slice(0,5)}</span>
                                        {m.location && (
                                            <>
                                                <span>•</span>
                                                <span className="flex items-center gap-0.5"><span className="material-icons-outlined text-[10px]">place</span>{m.location}</span>
                                            </>
                                        )}
                                     </div>
                                 </div>
                             </div>

                             <div className="flex flex-col items-center gap-2 w-1/3">
                                 <div className={`w-10 h-10 md:w-14 md:h-14 rounded-full flex items-center justify-center overflow-hidden shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/90' : 'bg-gray-100 dark:bg-gray-700'}`}>
                                     {m.locationImg ? <img src={m.locationImg} className="w-full h-full object-cover" /> : <span className="material-icons-outlined text-gray-400">sports_soccer</span>}
                                 </div>
                                 <span className={`font-bold text-xs md:text-sm truncate max-w-full text-center ${matchViewMode === 'upcoming' ? 'text-white' : ''}`}>{m.opponent}</span>
                             </div>
                        </div>

                        <div className={`p-3 border-t flex justify-center ${matchViewMode === 'upcoming' ? 'border-white/10 bg-white/5' : 'border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-surface-dark/50'}`}>
                             <button onClick={() => openMatchResultModal(m)} className={`w-full py-3 rounded-lg text-xs font-bold uppercase text-center flex items-center justify-center gap-2 transition-all shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/20 text-white hover:bg-white hover:text-primary' : 'bg-white dark:bg-surface-dark border border-gray-200 dark:border-gray-700 hover:bg-primary hover:text-white hover:border-primary'}`}>
                                 <span className="material-icons-outlined text-[14px]">{m.isFinished ? "edit" : "sports_score"}</span>
                                 {m.isFinished ? "Editar Placar / Súmula" : "Informar Placar / Súmula"}
                             </button>
                        </div>
                    </div>
                ))}

                {filteredMatches.length === 0 && (
                    <div className="col-span-full text-center py-10 bg-surface-light dark:bg-surface-dark rounded-2xl border border-dashed border-gray-200 dark:border-gray-800 flex flex-col items-center">
                        <span className="material-icons-outlined text-4xl text-muted-light mb-2">search_off</span>
                        <p className="text-muted-light font-bold">{searchQuery ? 'Nenhuma partida encontrada para a busca.' : 'Nenhum jogo encontrado nesta seção.'}</p>
                        {matchViewMode === 'upcoming' && !searchQuery && (
                            <button onClick={() => setIsAddModalOpen(true)} className="mt-4 text-primary font-bold text-sm hover:underline">
                                Agendar agora
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
    </div>
  );
  };

  return (
    <div className={`min-h-screen font-sans text-gray-900 dark:text-gray-100 transition-colors duration-500 ${theme === 'dark' ? 'bg-[#0f1115]' : 'bg-gray-50'}`}>

      {/* API Key Modal */}
      {apiKeyModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animation-fade-in">
           <div className="bg-white dark:bg-surface-dark w-full max-w-md rounded-3xl p-8 shadow-2xl border border-gray-100 dark:border-gray-800">
              <h2 className="text-2xl font-black mb-2 text-center">Conectar Database</h2>
              <p className="text-center text-muted-light mb-6 text-sm">Insira sua chave de API do Supabase para continuar.</p>
              <form onSubmit={handleSaveKey} className="space-y-4">
                  <input type="text" placeholder="Supabase Anon Key" value={apiKeyInput} onChange={e => setApiKeyInput(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-transparent focus:border-primary focus:bg-white dark:focus:bg-black/40 rounded-xl px-4 py-3 text-sm font-bold transition-all outline-none" autoFocus />
                  <button type="submit" className="w-full bg-primary hover:opacity-90 text-white font-bold py-3 rounded-xl shadow-lg shadow-primary/20 transition-all">Conectar</button>
              </form>
           </div>
        </div>
      )}

      {/* Add Item Modal (Player or Match) */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-[90] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animation-fade-in" onClick={() => setIsAddModalOpen(false)}>
           <div className="bg-white dark:bg-surface-dark w-full max-w-lg rounded-3xl p-8 shadow-2xl border border-gray-100 dark:border-gray-800 relative" onClick={e => e.stopPropagation()}>
               <button onClick={() => setIsAddModalOpen(false)} className="absolute top-4 right-4 p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"><span className="material-icons-outlined">close</span></button>

               <h2 className="text-2xl font-black mb-6">{currentTab === 'financial' ? 'Novo Jogador' : 'Nova Partida'}</h2>

               {currentTab === 'financial' ? (
                   <form onSubmit={handleAddPlayer} className="space-y-4">
                       <div className="flex justify-center mb-6">
                           <label className="relative w-24 h-24 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center cursor-pointer overflow-hidden border-2 border-dashed border-gray-300 dark:border-gray-700 hover:border-primary transition-colors group">
                               {newPlayerPhoto ? <img src={newPlayerPhoto} className="w-full h-full object-cover" /> : <span className="material-icons-outlined text-3xl text-gray-400 group-hover:text-primary">add_a_photo</span>}
                               <input type="file" className="hidden" onChange={(e) => handlePhotoUpload(e, setNewPlayerPhoto)} />
                           </label>
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                           <input type="text" placeholder="Nome / Apelido" value={newPlayerName} onChange={e => setNewPlayerName(e.target.value)} className="col-span-2 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-800 rounded-xl px-4 py-3 font-bold outline-none focus:border-primary" />
                           <input type="number" placeholder="Número Camisa" value={newPlayerNumber} onChange={e => setNewPlayerNumber(e.target.value)} className="bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-800 rounded-xl px-4 py-3 font-bold outline-none focus:border-primary" />
                           <select value={newPlayerPosition} onChange={e => setNewPlayerPosition(e.target.value)} className="bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-800 rounded-xl px-4 py-3 font-bold outline-none focus:border-primary">
                               <option value="GOL">Goleiro</option>
                               <option value="ZAG">Zagueiro</option>
                               <option value="LAT">Lateral</option>
                               <option value="VOL">Volante</option>
                               <option value="MEI">Meia</option>
                               <option value="ATA">Atacante</option>
                           </select>
                       </div>
                       <button disabled={isSubmitting} type="submit" className="w-full bg-primary hover:opacity-90 text-white font-bold py-4 rounded-xl shadow-lg shadow-primary/20 transition-all mt-4">{isSubmitting ? 'Salvando...' : 'Adicionar Jogador'}</button>
                   </form>
               ) : (
                   <form onSubmit={handleAddMatch} className="space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                            <input type="text" placeholder="Adversário" value={newMatchOpponent} onChange={e => setNewMatchOpponent(e.target.value)} className="col-span-2 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-800 rounded-xl px-4 py-3 font-bold outline-none focus:border-primary" />
                            <input type="date" value={newMatchDate} onChange={e => setNewMatchDate(e.target.value)} className="bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-800 rounded-xl px-4 py-3 font-bold outline-none focus:border-primary" />
                            <input type="time" value={newMatchTime} onChange={e => setNewMatchTime(e.target.value)} className="bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-800 rounded-xl px-4 py-3 font-bold outline-none focus:border-primary" />
                            <input type="text" placeholder="Local" value={newMatchLocation} onChange={e => setNewMatchLocation(e.target.value)} className="col-span-2 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-800 rounded-xl px-4 py-3 font-bold outline-none focus:border-primary" />
                        </div>
                        <button disabled={isSubmitting} type="submit" className="w-full bg-primary hover:opacity-90 text-white font-bold py-4 rounded-xl shadow-lg shadow-primary/20 transition-all mt-4">{isSubmitting ? 'Agendando...' : 'Agendar Partida'}</button>
                   </form>
               )}
           </div>
        </div>
      )}

      {/* Match Result Modal */}
      {isMatchResultModalOpen && selectedMatch && (
          <div className="fixed inset-0 z-[90] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animation-fade-in" onClick={() => setIsMatchResultModalOpen(false)}>
              <div className="bg-white dark:bg-surface-dark w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-3xl p-6 md:p-8 shadow-2xl border border-gray-100 dark:border-gray-800 relative flex flex-col" onClick={e => e.stopPropagation()}>
                  <h2 className="text-xl font-black mb-6 text-center uppercase tracking-wider">Súmula da Partida</h2>

                  <div className="flex items-center justify-center gap-8 mb-8">
                      <div className="text-center">
                          <span className="block font-bold text-sm mb-2">PESADÃO</span>
                          <input type="number" value={manualHomeScore} onChange={e => setManualHomeScore(parseInt(e.target.value) || 0)} className="w-20 h-20 text-center text-4xl font-black bg-gray-100 dark:bg-black/20 rounded-2xl border-2 border-transparent focus:border-primary outline-none" />
                      </div>
                      <span className="text-2xl font-bold text-muted-light">X</span>
                      <div className="text-center">
                          <span className="block font-bold text-sm mb-2 truncate max-w-[100px]">{selectedMatch.opponent}</span>
                          <input type="number" value={manualAwayScore} onChange={e => setManualAwayScore(parseInt(e.target.value) || 0)} className="w-20 h-20 text-center text-4xl font-black bg-gray-100 dark:bg-black/20 rounded-2xl border-2 border-transparent focus:border-primary outline-none" />
                      </div>
                  </div>

                  <div className="space-y-4 mb-8">
                      <div className="flex justify-between items-center">
                          <h3 className="font-bold text-sm uppercase text-muted-light">Jogadores / Gols</h3>
                          <div className="space-x-2">
                               <button type="button" onClick={selectActivePlayers} className="text-xs font-bold text-primary hover:underline">Selecionar Elenco</button>
                               <span className="text-gray-500">•</span>
                               <button type="button" onClick={resetMatchStats} className="text-xs font-bold text-gray-500 hover:text-red-500">Limpar</button>
                          </div>
                      </div>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-60 overflow-y-auto pr-2 custom-scrollbar">
                          {players.map(p => {
                              const stat = matchPlayerStats[p.id] || { goals: 0, present: false };
                              return (
                                  <div key={p.id} className={`flex items-center justify-between p-3 rounded-xl border transition-all ${stat.present ? 'bg-primary/5 border-primary/30' : 'bg-gray-50 dark:bg-black/20 border-transparent opacity-60'}`}>
                                      <div className="flex items-center gap-3" onClick={() => toggleMatchPresence(p.id)}>
                                          <div className={`w-5 h-5 rounded-md border flex items-center justify-center cursor-pointer ${stat.present ? 'bg-primary border-primary text-white' : 'border-gray-400'}`}>
                                              {stat.present && <span className="material-icons-outlined text-sm">check</span>}
                                          </div>
                                          <span className="font-bold text-sm truncate max-w-[100px]">{p.name}</span>
                                      </div>

                                      {stat.present && (
                                          <div className="flex items-center gap-2">
                                              <button onClick={() => updateMatchStat(p.id, 'goals', -1)} className="w-6 h-6 flex items-center justify-center bg-gray-200 dark:bg-black/40 rounded hover:bg-red-500 hover:text-white transition-colors">-</button>
                                              <span className="font-mono font-bold w-4 text-center">{stat.goals}</span>
                                              <button onClick={() => updateMatchStat(p.id, 'goals', 1)} className="w-6 h-6 flex items-center justify-center bg-gray-200 dark:bg-black/40 rounded hover:bg-green-500 hover:text-white transition-colors">+</button>
                                              <span className="text-[10px] uppercase font-bold text-muted-light ml-1">Gols</span>
                                          </div>
                                      )}
                                  </div>
                              );
                          })}
                      </div>
                  </div>

                  <textarea placeholder="Comentários sobre a partida..." value={matchComments} onChange={e => setMatchComments(e.target.value)} className="w-full bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-800 rounded-xl px-4 py-3 text-sm mb-6 outline-none focus:border-primary resize-none h-24" />

                  <div className="flex gap-4 mt-auto">
                      <button onClick={() => setIsMatchResultModalOpen(false)} className="flex-1 py-4 rounded-xl font-bold bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors">Cancelar</button>
                      <button onClick={confirmMatchResult} disabled={isSubmitting} className="flex-1 py-4 rounded-xl font-bold bg-primary text-white hover:opacity-90 shadow-lg shadow-primary/20 transition-all">{isSubmitting ? 'Salvando...' : 'Salvar Súmula'}</button>
                  </div>
              </div>
          </div>
      )}

      {/* Main Layout */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10 animation-slide-down">
          <div>
            <h1 className="text-4xl md:text-5xl font-black tracking-tighter italic uppercase bg-gradient-to-r from-gray-900 to-gray-600 dark:from-white dark:to-gray-400 bg-clip-text text-transparent">
              Pesadão <span className="text-primary">FC</span>
            </h1>
            <p className="text-muted-light dark:text-muted-dark font-medium mt-1">Painel de Gestão Esportiva</p>
          </div>

          <div className="flex items-center gap-4">
             <div className="flex bg-white dark:bg-surface-dark p-1.5 rounded-2xl shadow-sm border border-gray-200 dark:border-gray-800">
                <button onClick={() => setCurrentTab('matches')} className={`px-6 py-2.5 rounded-xl text-sm font-bold transition-all ${currentTab === 'matches' ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-muted-light hover:text-gray-900 dark:hover:text-white'}`}>Jogos</button>
                <button onClick={() => setCurrentTab('financial')} className={`px-6 py-2.5 rounded-xl text-sm font-bold transition-all ${currentTab === 'financial' ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-muted-light hover:text-gray-900 dark:hover:text-white'}`}>Financeiro</button>
             </div>

             <button onClick={toggleTheme} className="p-3 rounded-xl bg-white dark:bg-surface-dark border border-gray-200 dark:border-gray-800 text-gray-500 hover:text-primary transition-colors shadow-sm">
                <span className="material-icons-outlined">{theme === 'dark' ? 'light_mode' : 'dark_mode'}</span>
             </button>
          </div>
        </header>

        {/* Content */}
        <main>
           {currentTab === 'financial' && renderFinancial()}
           {currentTab === 'matches' && renderMatches()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, ChangeEvent } from 'react';
import { Player, DbPlayer, Match, DbMatch } from './types';
import { getSupabase, saveSupabaseKey, SUPABASE_URL } from './supabaseClient';

const DEFAULT_FEE = 40;

const App: React.FC = () => {
  // --- STATE ---
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [currentTab, setCurrentTab] = useState<'financial' | 'matches' | 'stats'>('matches'); 

  // Data State
  const [players, setPlayers] = useState<Player[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);

  // Financial Specific State
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  // Connection State
  const [apiKeyModalOpen, setApiKeyModalOpen] = useState(false);
  const [apiKeyInput, setApiKeyInput] = useState('');
  const [isConnected, setIsConnected] = useState(false);

  // Inline Editing State
  const [editingDateId, setEditingDateId] = useState<string | null>(null);
  const [editingNameId, setEditingNameId] = useState<string | null>(null);
  const [editingJerseyId, setEditingJerseyId] = useState<string | null>(null);
  const [tempName, setTempName] = useState<string>('');

  // Modals State
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // Ranking Modals State
  const [isScorersModalOpen, setIsScorersModalOpen] = useState(false);
  const [isAppearancesModalOpen, setIsAppearancesModalOpen] = useState(false);

  // Matches View Mode
  const [matchViewMode, setMatchViewMode] = useState<'upcoming' | 'history'>('upcoming');
  const [searchQuery, setSearchQuery] = useState(''); // Estado para busca

  // MATCH RESULT MODAL STATE
  const [isMatchResultModalOpen, setIsMatchResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);
  const [manualHomeScore, setManualHomeScore] = useState(0);
  const [manualAwayScore, setManualAwayScore] = useState(0);
  const [matchComments, setMatchComments] = useState('');
  // Atualizado para controlar presença
  const [matchPlayerStats, setMatchPlayerStats] = useState<Record<string, {goals: number, present: boolean}>>({});

  // Forms State
  const [newPlayerName, setNewPlayerName] = useState('');
  const [newPlayerNumber, setNewPlayerNumber] = useState('');
  const [newPlayerPhoto, setNewPlayerPhoto] = useState<string | null>(null);
  const [newPlayerPosition, setNewPlayerPosition] = useState('MEI');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [newMatchOpponent, setNewMatchOpponent] = useState('');
  const [newMatchLocation, setNewMatchLocation] = useState('');
  const [newMatchDate, setNewMatchDate] = useState(new Date().toISOString().split('T')[0]);
  const [newMatchTime, setNewMatchTime] = useState('');
  const [newMatchLocationImg, setNewMatchLocationImg] = useState<string | null>(null);

  // Edit Stats State
  const [editingStatsId, setEditingStatsId] = useState<string | null>(null);
  const [tempStats, setTempStats] = useState({ goals: 0, matchesPlayed: 0, overall: 0, position: '' });

  // --- INITIALIZATION ---

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  // Load Data
  useEffect(() => {
    const supabase = getSupabase();
    if (!supabase) {
      setApiKeyModalOpen(true);
      setLoading(false);
      return;
    }
    setIsConnected(true);
    fetchData();

    const channelPlayers = supabase.channel('realtime-players')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'players' }, () => fetchData())
      .subscribe();

    const channelMatches = supabase.channel('realtime-matches')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, () => fetchData())
      .subscribe();

    return () => {
      supabase.removeChannel(channelPlayers);
      supabase.removeChannel(channelMatches);
    };
  }, []);

  const fetchData = async () => {
    const supabase = getSupabase();
    if (!supabase) return;

    try {
      const { data: dataPlayers } = await supabase.from('players').select('*').order('name', { ascending: true });
      if (dataPlayers) {
        setPlayers(dataPlayers.map((p: any) => ({
          id: p.id.toString(),
          name: p.name,
          photoUrl: p.photo_url || 'https://via.placeholder.com/150',
          isPaid: false, 
          paymentDate: undefined,
          value: p.value,
          jerseyNumber: p.jersey_number,
          status: (p.status === 'injured' ? 'injured' : 'active') as 'active' | 'injured',
          paymentHistory: parsePaymentHistory(p.payment_date),
          position: p.position || 'MEI',
          goals: p.goals || 0,
          matchesPlayed: p.matches_played || 0,
          lastPlayedDate: p.last_played_date, // Mapeando do DB
          overall: p.overall || 75
        })));
      }

      const { data: dataMatches } = await supabase.from('matches').select('*').order('date', { ascending: true });
      if (dataMatches) {
        setMatches(dataMatches.map((m: DbMatch) => ({
          id: m.id.toString(),
          opponent: m.opponent,
          locationImg: m.location_img,
          location: m.location || '',
          date: m.date,
          time: m.time,
          homeScore: m.home_score,
          awayScore: m.away_score,
          result: m.result as any,
          isFinished: m.is_finished,
          lineup: m.lineup || undefined,
          comments: m.comments || ''
        })));
      }
    } catch (error) {
      console.error("Erro ao buscar dados:", error);
    } finally {
      setLoading(false);
    }
  };

  // --- HELPERS ---

  const getMonthKey = (date: Date) => {
    const m = (date.getMonth() + 1).toString().padStart(2, '0');
    const y = date.getFullYear();
    return `${m}-${y}`;
  };

  const parsePaymentHistory = (dateStr: string | null): Record<string, string> => {
    if (!dateStr) return {};
    try {
        const parsed = JSON.parse(dateStr);
        if (typeof parsed === 'object' && parsed !== null) return parsed;
        return {};
    } catch (e) {
        return dateStr ? { [getMonthKey(new Date())]: dateStr } : {};
    }
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  const formattedDate = useMemo(() => {
    const options: Intl.DateTimeFormatOptions = { month: 'long', year: 'numeric' };
    const str = selectedDate.toLocaleDateString('pt-BR', options);
    return str.charAt(0).toUpperCase() + str.slice(1);
  }, [selectedDate]);

  const changeMonth = (increment: number) => {
    const newDate = new Date(selectedDate);
    newDate.setMonth(newDate.getMonth() + increment);
    setSelectedDate(newDate);
  };

  const getNextSundays = () => {
      const dates = [];
      let d = new Date();
      d.setDate(d.getDate() + (7 - d.getDay()) % 7);
      for(let i=0; i<6; i++) {
          dates.push(new Date(d));
          d.setDate(d.getDate() + 7);
      }
      return dates;
  };

  // --- STATS CALCULATION ---

  const currentMonthKey = getMonthKey(selectedDate);

  const playersView = useMemo(() => {
    return players.map(player => ({
        ...player,
        isPaid: !!player.paymentHistory[currentMonthKey],
        paymentDate: player.paymentHistory[currentMonthKey]
    }));
  }, [players, currentMonthKey]);

  const financialStats = useMemo(() => {
    const active = playersView.filter(p => p.status === 'active' || p.isPaid);
    const collected = playersView.reduce((acc, p) => acc + (p.isPaid ? p.value : 0), 0);
    const potential = active.reduce((acc, p) => acc + p.value, 0);
    const count = active.length;
    const paid = playersView.filter(p => p.isPaid).length;
    return { collected, potential, paid, count, progress: count > 0 ? (paid / count) * 100 : 0 };
  }, [playersView]);

  const topPayers = useMemo(() => playersView.filter(p => p.isPaid && p.status === 'active').slice(0, 3), [playersView]);

  const matchStats = useMemo(() => {
    const finished = matches.filter(m => m.isFinished);
    const wins = finished.filter(m => m.result === 'win').length;
    const draws = finished.filter(m => m.result === 'draw').length;
    const losses = finished.filter(m => m.result === 'loss').length;
    const total = finished.length;
    const goalsFor = finished.reduce((acc, m) => acc + m.homeScore, 0);
    const goalsAgainst = finished.reduce((acc, m) => acc + m.awayScore, 0);
    const goalDiff = goalsFor - goalsAgainst;

    return { 
        wins, draws, losses, total, 
        winRate: total > 0 ? Math.round((wins / total) * 100) : 0,
        goalsFor, goalsAgainst, goalDiff
    };
  }, [matches]);

  const topScorers = useMemo(() => [...players].sort((a, b) => b.goals - a.goals).slice(0, 5), [players]);

  const topAppearances = useMemo(() => [...players].sort((a, b) => b.matchesPlayed - a.matchesPlayed).slice(0, 3), [players]);

  // --- ACTIONS ---

  const handleSaveKey = (e: React.FormEvent) => {
    e.preventDefault();
    if (apiKeyInput.trim()) {
      saveSupabaseKey(apiKeyInput.trim());
      setApiKeyModalOpen(false);
    }
  };

  const togglePayment = async (id: string) => {
    const supabase = getSupabase();
    if (!supabase) return;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const newHistory = { ...player.paymentHistory };
    const isPaid = !!newHistory[currentMonthKey];

    if (isPaid) delete newHistory[currentMonthKey];
    else newHistory[currentMonthKey] = new Date().toLocaleDateString('pt-BR');

    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    await supabase.from('players').update({ payment_date: JSON.stringify(newHistory), is_paid: !isPaid }).eq('id', id);
  };

  const updatePaymentDate = async (id: string, dateValue: string) => {
    if (!dateValue) return;
    const [year, month, day] = dateValue.split('-');
    const formatted = `${day}/${month}/${year}`;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const newHistory = { ...player.paymentHistory, [currentMonthKey]: formatted };
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    setEditingDateId(null);
    const supabase = getSupabase();
    if (supabase) await supabase.from('players').update({ payment_date: JSON.stringify(newHistory) }).eq('id', id);
  };

  const handlePhotoUpload = (e: ChangeEvent<HTMLInputElement>, setter: (val: string) => void) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => setter(reader.result as string);
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const updatePlayerPhoto = async (id: string, e: ChangeEvent<HTMLInputElement>) => {
    handlePhotoUpload(e, async (base64) => {
        const supabase = getSupabase();
        if(supabase) await supabase.from('players').update({ photo_url: base64 }).eq('id', id);
        fetchData();
    });
  };

  const deletePlayer = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Remover jogador?")) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').delete().eq('id', id);
      setPlayers(prev => prev.filter(p => p.id !== id));
    }
  };

  const togglePlayerStatus = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const player = players.find(p => p.id === id);
    if(!player) return;
    const newStatus = player.status === 'active' ? 'injured' : 'active';
    const supabase = getSupabase();
    if(supabase) await supabase.from('players').update({ status: newStatus }).eq('id', id);
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
  };

  const startEditingName = (player: Player) => {
    setTempName(player.name);
    setEditingNameId(player.id);
  };

  const savePlayerName = async (id: string) => {
    if (tempName.trim()) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').update({ name: tempName.trim() }).eq('id', id);
      setPlayers(prev => prev.map(p => p.id === id ? { ...p, name: tempName.trim() } : p));
    }
    setEditingNameId(null);
  };

  const saveJerseyNumber = async (id: string, newNumber: string) => {
    const num = parseInt(newNumber);
    if (!isNaN(num)) {
         const supabase = getSupabase();
         if(supabase) await supabase.from('players').update({ jersey_number: num }).eq('id', id);
         setPlayers(prev => prev.map(p => p.id === id ? { ...p, jerseyNumber: num } : p));
    }
    setEditingJerseyId(null);
  };

  const handleAddPlayer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlayerName.trim() || !newPlayerPhoto || isSubmitting) return;

    setIsSubmitting(true);
    const supabase = getSupabase();
    if (supabase) {
        const fullPayload = {
            name: newPlayerName,
            photo_url: newPlayerPhoto,
            is_paid: false,
            value: DEFAULT_FEE,
            jersey_number: parseInt(newPlayerNumber) || 0,
            status: 'active',
            payment_date: JSON.stringify({}),
            position: newPlayerPosition,
            goals: 0,
            matches_played: 0,
            overall: 70
        };

        const { error } = await supabase.from('players').insert([fullPayload]);

        if (error) {
            console.warn("Insert completo falhou. Tentando fallback básico.", error.message);
            const basicPayload = {
                name: newPlayerName,
                photo_url: newPlayerPhoto,
                is_paid: false,
                value: DEFAULT_FEE,
                jersey_number: parseInt(newPlayerNumber) || 0,
                status: 'active',
                payment_date: JSON.stringify({})
            };
            const { error: basicError } = await supabase.from('players').insert([basicPayload]);
            if (basicError) {
                alert(`Erro ao salvar jogador: ${basicError.message}`);
                setIsSubmitting(false);
                return;
            }
        }
        await fetchData();
    }

    setNewPlayerName('');
    setNewPlayerNumber('');
    setNewPlayerPhoto(null);
    setIsAddModalOpen(false);
    setIsSubmitting(false);
  };

  const openPlayerProfile = (player: Player) => {
      setTempStats({
          goals: player.goals,
          matchesPlayed: player.matchesPlayed,
          overall: player.overall,
          position: player.position
      });
      setEditingStatsId(player.id);
  };

  const savePlayerStats = async () => {
      if(!editingStatsId) return;
      const supabase = getSupabase();
      if(supabase) {
          const { error } = await supabase.from('players').update({
              goals: tempStats.goals,
              matches_played: tempStats.matchesPlayed,
              overall: tempStats.overall,
              position: tempStats.position
          }).eq('id', editingStatsId);

          if (error) {
             alert("Erro ao atualizar estatísticas. Verifique se as colunas existem.\n" + error.message);
          } else {
             setPlayers(prev => prev.map(p => p.id === editingStatsId ? { ...p, ...tempStats } : p));
          }
      }
      setEditingStatsId(null);
  };

  const handleAddMatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if(isSubmitting) return;
    setIsSubmitting(true);

    const supabase = getSupabase();
    if(supabase) {
        if (matches.some(m => m.date === newMatchDate)) {
            if(!window.confirm("Já existe um jogo nesta data. Deseja marcar outro?")) {
                setIsSubmitting(false);
                return;
            }
        }

        const { error } = await supabase.from('matches').insert([{
            opponent: newMatchOpponent,
            location: newMatchLocation,
            date: newMatchDate,
            time: newMatchTime,
            location_img: newMatchLocationImg,
            result: 'pending',
            is_finished: false
        }]);

        if (error) {
            alert(`Erro ao criar partida: ${error.message}`);
            setIsSubmitting(false);
            return;
        }
        await fetchData();
    }
    setNewMatchOpponent('');
    setNewMatchLocation('');
    setNewMatchDate(new Date().toISOString().split('T')[0]);
    setNewMatchTime('');
    setNewMatchLocationImg(null);
    setIsAddModalOpen(false);
    setIsSubmitting(false);
  };

  const deleteMatch = async (id: string, e: React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();

      const confirmDelete = window.confirm("Tem certeza que deseja excluir esta partida?");
      if (!confirmDelete) return;

      const previousMatches = [...matches];
      setMatches(prev => prev.filter(m => m.id !== id));

      const supabase = getSupabase();
      if(!supabase) {
          setMatches(previousMatches); 
          return;
      }

      try {
          const { error } = await supabase.from('matches').delete().eq('id', parseInt(id));
          if (error) {
              alert("Erro ao excluir partida no banco de dados: " + error.message);
              setMatches(previousMatches); 
          }
      } catch (err: any) {
          alert("Ocorreu um erro ao tentar excluir: " + err.message);
          setMatches(previousMatches); 
      }
  };

  const openMatchResultModal = (match: Match) => {
      setSelectedMatch(match);
      setManualHomeScore(match.isFinished ? match.homeScore : 0);
      setManualAwayScore(match.isFinished ? match.awayScore : 0);
      setMatchComments(match.comments || '');

      const statsMap: Record<string, {goals: number, present: boolean}> = {};

      // 1. Carrega a súmula salva (lineup) se existir
      if (match.lineup) {
        // CORREÇÃO CRÍTICA: Supabase pode retornar JSONB como string ou objeto dependendo do driver
        try {
            const loadedLineup = typeof match.lineup === 'string' ? JSON.parse(match.lineup) : match.lineup;
            if (loadedLineup && typeof loadedLineup === 'object') {
                Object.assign(statsMap, loadedLineup);
            }
        } catch (e) {
            console.error("Erro ao fazer parse do lineup", e);
        }
      }

      // 2. Mescla com os jogadores ATIVOS atuais para garantir que todos apareçam na lista inicial para seleção
      players.forEach(p => {
          if (p.status === 'active' && !statsMap[p.id]) {
              statsMap[p.id] = { goals: 0, present: false };
          }
      });

      setMatchPlayerStats(statsMap);
      setIsMatchResultModalOpen(true);
  };

  const toggleMatchPresence = (playerId: string) => {
      setMatchPlayerStats(prev => {
          const currentStat = prev[playerId] || { goals: 0, present: false };
          return {
              ...prev,
              [playerId]: {
                  ...currentStat,
                  present: !currentStat.present,
                  // Se desmarcar presença, zera os gols
                  goals: !currentStat.present ? currentStat.goals : 0
              }
          };
      });
  };

  const selectActivePlayers = () => {
       const newStats = { ...matchPlayerStats };
       // Seleciona os primeiros 11 jogadores como exemplo ou todos
       Object.keys(newStats).forEach((key, index) => {
           if (index < 11) newStats[key].present = true;
       });
       setMatchPlayerStats(newStats);
  };

  const resetMatchStats = () => {
      const newStats = { ...matchPlayerStats };
      Object.keys(newStats).forEach(key => {
          newStats[key] = { goals: 0, present: false };
      });
      setMatchPlayerStats(newStats);
  };

  const updateMatchStat = (playerId: string, type: 'goals', delta: number) => {
      setMatchPlayerStats(prev => {
          const currentStat = prev[playerId] || { goals: 0, present: false };
          if (!currentStat.present) return prev; // Não altera se não estiver presente
          return {
              ...prev,
              [playerId]: {
                  ...currentStat,
                  [type]: Math.max(0, (currentStat[type] || 0) + delta)
              }
          }
      });
  };

  const confirmMatchResult = async () => {
      if (!selectedMatch) return;
      const supabase = getSupabase();
      if (!supabase) return;

      setIsSubmitting(true);

      let result = 'draw';
      if (manualHomeScore > manualAwayScore) result = 'win';
      if (manualHomeScore < manualAwayScore) result = 'loss';

      const { error: matchError } = await supabase.from('matches').update({
          home_score: manualHomeScore,
          away_score: manualAwayScore,
          result: result,
          is_finished: true,
          lineup: matchPlayerStats, // Salva o JSON da escalação
          comments: matchComments
      }).eq('id', parseInt(selectedMatch.id));

      if (matchError) {
          alert("Erro ao salvar placar: " + matchError.message);
          setIsSubmitting(false);
          return;
      }

      // Atualiza stats dos jogadores
      const updates = [];
      for (const playerId in matchPlayerStats) {
            const stats = matchPlayerStats[playerId];
            const player = players.find(p => p.id === playerId);

            // Só atualiza estatísticas se o jogador esteve PRESENTE
            if (player && stats.present) {
                updates.push(
                    supabase.from('players').update({
                        goals: (player.goals || 0) + stats.goals,
                        matches_played: (player.matchesPlayed || 0) + 1,
                        last_played_date: selectedMatch.date 
                    }).eq('id', parseInt(playerId))
                );
            }
      }
      if(updates.length > 0) {
