                       {players.filter(p => p.status === 'active' || (matchPlayerStats[p.id] && matchPlayerStats[p.id].present))
                       .sort((a, b) => {
                           const aPresent = matchPlayerStats[a.id]?.present ? 1 : 0;
                           const bPresent = matchPlayerStats[b.id]?.present ? 1 : 0;
                           // Primeiro por Presença (Decrescente), depois por Nome (Crescente)
                           if (bPresent !== aPresent) return bPresent - aPresent;
                           return a.name.localeCompare(b.name);
                       })
                       .map(p => {
                           const isPresent = matchPlayerStats[p.id]?.present;
                           return (
                           <div 
                                key={p.id} 
                                onClick={() => toggleMatchPresence(p.id)}
                                className={`flex items-center justify-between p-3 rounded-xl border transition-all cursor-pointer select-none ${isPresent ? 'bg-white dark:bg-surface-dark border-green-500 shadow-md ring-1 ring-green-500/20' : 'bg-gray-100 dark:bg-black/20 border-transparent opacity-60 hover:opacity-80'}`}
