  const updateMatchStat = (playerId: string, type: 'goals', delta: number) => {
      setMatchPlayerStats(prev => {
          const currentStat = prev[playerId] || { goals: 0, present: false };
          if (!currentStat.present) return prev; // Não altera se não estiver presente
          return {
              ...prev,
              [playerId]: {
                  ...currentStat,
                  [type]: Math.max(0, (currentStat[type] || 0) + delta)
              }
          }
      });
  };

  const confirmMatchResult = async () => {
