                            <button type="submit" disabled={!newMatchOpponent || !newMatchDate} className="w-full mt-4 bg-primary text-white font-bold py-3 rounded-xl hover:opacity-90 shadow-lg shadow-primary/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed">
