                                ) : (
                                    <span className="material-icons-outlined text-muted-dark text-4xl">add_a_photo</span>
                                )}
                            </div>
                            <label className="absolute inset-0 cursor-pointer rounded-full">
                                <input type="file" accept="image/*" onChange={(e) => handlePhotoUpload(e, setEditPlayerPhoto)} className="hidden" />
                            </label>
                        </div>
                    </div>

                    <div>
                        <label className="text-xs font-bold uppercase text-muted-light dark:text-muted-dark ml-1">Nome</label>
                        <input type="text" value={editPlayerName} onChange={e => setEditPlayerName(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary focus:border-primary" />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
