                        </div>
                        <div>
                            <label className="text-xs font-bold uppercase text-muted-light dark:text-muted-dark ml-1">Posição</label>
                            <select value={editPlayerPosition} onChange={e => setEditPlayerPosition(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary focus:border-primary">
