                                      <input autoFocus className="w-full text-center bg-transparent border-b border-primary text-3xl font-black uppercase text-white focus:outline-none" value={tempName} onChange={e => setTempName(e.target.value)} onBlur={() => savePlayerName(p.id)} onKeyDown={e => e.key === 'Enter' && savePlayerName(p.id)} />
