                                      <span onClick={() => startEditingName(p)} className="block text-3xl md:text-5xl font-black uppercase text-white leading-none tracking-tighter drop-shadow-lg truncate cursor-pointer hover:text-primary transition-colors">
                                         {firstName}
                                      </span>
                                  )}

                                  {/* Status Badge */}
                                  <div className="mt-2 flex justify-center">
                                     {p.status === 'injured' ? (
                                         <span className="text-[10px] font-bold uppercase text-white bg-orange-500 px-2 py-0.5 rounded-full shadow-lg shadow-orange-500/20">Afastado</span>
