                {nextSundays.map((d, i) => {
                    const dateStr = d.toISOString().split('T')[0];
                    const isBooked = matches.some(m => m.date === dateStr);
                    return (
                        <div key={i} className={`flex-shrink-0 w-20 h-24 rounded-2xl flex flex-col items-center justify-center border-2 transition-all ${isBooked ? 'bg-primary border-primary text-white shadow-lg shadow-primary/30' : 'bg-surface-light dark:bg-surface-dark border-gray-200 dark:border-gray-800 text-muted-light'}`}>
                             <span className="text-xs font-bold uppercase opacity-80">{d.toLocaleDateString('pt-BR', {month: 'short'}).replace('.','')}</span>
                             <span className="text-3xl font-bold my-1">{d.getDate()}</span>
                             <span className="text-[10px] font-bold uppercase">{isBooked ? 'JOGO' : 'LIVRE'}</span>
                        </div>
                    );
                })}
            </div>
        </div>

        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-4">
