                                 <div className="relative w-full h-full flex items-end justify-center group/img">
                                      <img 
                                        src={p.photoUrl} 
                                        className={`h-full w-auto max-w-[120%] object-cover object-top drop-shadow-2xl transition-all duration-500 mask-image-gradient ${p.status === 'injured' ? 'grayscale opacity-60' : ''}`}
                                        style={{ maskImage: 'linear-gradient(to bottom, black 70%, transparent 100%)' }}
                                     />
                                      <label className="absolute inset-0 flex items-center justify-center cursor-pointer z-40 opacity-0 group-hover/img:opacity-100 transition-opacity">
                                          <div className="bg-black/50 backdrop-blur-sm rounded-full p-3 text-white">
                                              <span className="material-icons-outlined">camera_alt</span>
                                          </div>
                                          <input type="file" className="hidden" onChange={(e) => updatePlayerPhoto(p.id, e)} />
                                      </label>
