                            <button onClick={(e) => deleteMatch(m.id, e)} className={`p-2 rounded-full transition-colors cursor-pointer ${matchViewMode === 'upcoming' ? 'text-white/80 hover:bg-white/20 hover:text-white' : 'text-gray-400 hover:text-red-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}>
                                <span className="material-icons-outlined text-lg">delete_outline</span>
                            </button>
                        </div>

                        {/* Status Badge */}
                        <div className="absolute top-4 left-4 z-40">
                             {m.isFinished ? (
                                 <span className={`text-[10px] font-bold uppercase px-2 py-1 rounded backdrop-blur-md shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/20 text-white' : (m.result === 'win' ? 'bg-green-100 text-green-600' : m.result === 'loss' ? 'bg-red-100 text-red-600' : 'bg-gray-100 text-gray-600')}`}>
                                     {m.result === 'win' ? 'Vitória' : m.result === 'loss' ? 'Derrota' : 'Empate'}
                                 </span>
                             ) : (
                                 <span className="text-[10px] font-bold uppercase px-2 py-1 rounded bg-white/20 text-white backdrop-blur-md shadow-sm animate-pulse">Em Breve</span>
                             )}
                        </div>

                        <div className="p-6 pt-14 flex items-center justify-between">
                             <div className="flex flex-col items-center gap-2 w-1/3">
                                 <img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10 md:w-14 md:h-14 object-contain drop-shadow-md" />
                                 <span className={`font-bold text-xs md:text-sm hidden sm:block ${matchViewMode === 'upcoming' ? 'text-white' : ''}`}>Pesadão</span>
                             </div>

                             <div className="flex flex-col items-center justify-center w-1/3">
                                 <div className={`px-2 md:px-4 py-1 md:py-2 rounded-lg font-mono text-3xl md:text-4xl font-bold tracking-widest mb-2 ${matchViewMode === 'upcoming' ? 'text-white' : 'text-gray-900 dark:text-white'}`}>
                                     {m.isFinished ? `${m.homeScore}-${m.awayScore}` : 'VS'}
                                 </div>

                                 <div className={`flex flex-col items-center gap-1 text-[10px] md:text-xs font-bold uppercase ${matchViewMode === 'upcoming' ? 'text-white/90' : 'text-muted-light'}`}>
                                     <div className="flex items-center gap-1 bg-black/10 dark:bg-white/5 px-2 py-0.5 rounded-full">
                                        <span className="material-icons-outlined text-[12px]">calendar_today</span>
                                        <span>{new Date(m.date + 'T00:00:00').toLocaleDateString('pt-BR')}</span>
                                     </div>
                                     <div className="flex items-center gap-1">
                                        <span>{m.time.slice(0,5)}</span>
                                        {m.location && (
                                            <>
                                                <span>•</span>
                                                <span className="flex items-center gap-0.5"><span className="material-icons-outlined text-[10px]">place</span>{m.location}</span>
                                            </>
                                        )}
                                     </div>
                                 </div>
                             </div>

                             <div className="flex flex-col items-center gap-2 w-1/3">
                                 <div className={`w-10 h-10 md:w-14 md:h-14 rounded-full flex items-center justify-center overflow-hidden shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/90' : 'bg-gray-100 dark:bg-gray-700'}`}>
                                     {m.locationImg ? <img src={m.locationImg} className="w-full h-full object-cover" /> : <span className="material-icons-outlined text-gray-400">sports_soccer</span>}
                                 </div>
                                 <span className={`font-bold text-xs md:text-sm truncate max-w-full text-center ${matchViewMode === 'upcoming' ? 'text-white' : ''}`}>{m.opponent}</span>
                             </div>
                        </div>

                        <div className={`p-3 border-t flex justify-center ${matchViewMode === 'upcoming' ? 'border-white/10 bg-white/5' : 'border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-surface-dark/50'}`}>
                             <button onClick={() => openMatchResultModal(m)} className={`w-full py-3 rounded-lg text-xs font-bold uppercase text-center flex items-center justify-center gap-2 transition-all shadow-sm ${matchViewMode === 'upcoming' ? 'bg-white/20 text-white hover:bg-white hover:text-primary' : 'bg-white dark:bg-surface-dark border border-gray-200 dark:border-gray-700 hover:bg-primary hover:text-white hover:border-primary'}`}>
                                 <span className="material-icons-outlined text-[14px]">{m.isFinished ? "edit" : "sports_score"}</span>
                                 {m.isFinished ? "Editar Placar / Súmula" : "Informar Placar / Súmula"}
                             </button>
                        </div>
                    </div>
                ))}

                {filteredMatches.length === 0 && (
                    <div className="col-span-full text-center py-10 bg-surface-light dark:bg-surface-dark rounded-2xl border border-dashed border-gray-200 dark:border-gray-800 flex flex-col items-center">
                        <span className="material-icons-outlined text-4xl text-muted-light mb-2">search_off</span>
                        <p className="text-muted-light font-bold">{searchQuery ? 'Nenhuma partida encontrada para a busca.' : 'Nenhum jogo encontrado nesta seção.'}</p>
                        {matchViewMode === 'upcoming' && !searchQuery && (
                            <button onClick={() => setIsAddModalOpen(true)} className="mt-4 text-primary font-bold text-sm hover:underline">
                                Agendar agora
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
        </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-100 dark:bg-[#0f1115] text-gray-900 dark:text-gray-100 font-sans transition-colors duration-300 pb-10">
      <div className="max-w-7xl mx-auto p-4 md:p-6 lg:p-8">

        {/* HEADER & TABS */}
        <div className="flex flex-col md:flex-row justify-between items-center gap-6 mb-8">
             <div className="flex items-center gap-3">
                 <div className="w-12 h-12 bg-white dark:bg-white/5 rounded-full flex items-center justify-center shadow-sm">
                    <img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10 object-contain" />
