                             </button>
                        </div>
                    </div>
                ))}

                {filteredMatches.length === 0 && (
                    <div className="col-span-full text-center py-10 bg-surface-light dark:bg-surface-dark rounded-2xl border border-dashed border-gray-200 dark:border-gray-800 flex flex-col items-center">
                        <span className="material-icons-outlined text-4xl text-muted-light mb-2">search_off</span>
                        <p className="text-muted-light font-bold">{searchQuery ? 'Nenhuma partida encontrada para a busca.' : 'Nenhum jogo encontrado nesta seção.'}</p>
                        {matchViewMode === 'upcoming' && !searchQuery && (
                            <button onClick={() => setIsAddModalOpen(true)} className="mt-4 text-primary font-bold text-sm hover:underline">
                                Agendar agora
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
    </div>
  );
  };

  const renderStats = () => {
    const renderRankingItem = (p: Player, i: number, value: number, type: 'goals' | 'matches') => {
        let rankColors = "border-gray-100 dark:border-gray-800 bg-surface-light dark:bg-surface-dark";
        let textRank = "text-muted-light";
        let icon = null;

        if (i === 0) {
            rankColors = "border-yellow-500/50 bg-gradient-to-r from-yellow-500/10 to-transparent";
            textRank = "text-yellow-500";
            icon = "emoji_events";
        } else if (i === 1) {
            rankColors = "border-gray-400/50 bg-gradient-to-r from-gray-400/10 to-transparent";
            textRank = "text-gray-400";
        } else if (i === 2) {
            rankColors = "border-orange-700/50 bg-gradient-to-r from-orange-700/10 to-transparent";
            textRank = "text-orange-700";
        }

        return (
            <div key={p.id} className={`flex items-center justify-between p-4 md:p-3 rounded-xl border ${rankColors} transition-all`}>
                <div className="flex items-center gap-4">
                    <div className={`flex flex-col items-center justify-center w-8 ${textRank}`}>
                        {i === 0 && icon ? <span className="material-icons-outlined text-xl mb-1">{icon}</span> : <span className="font-black text-xl md:text-lg">{i + 1}</span>}
                    </div>
                    <img src={p.photoUrl} className="w-14 h-14 md:w-10 md:h-10 rounded-full object-cover object-top border-2 border-white/10 shadow-sm" />
                    <div>
                        <span className="font-bold text-base md:text-sm block">{p.name}</span>
                        <span className="text-xs text-muted-light font-bold bg-black/5 dark:bg-white/5 px-2 py-0.5 rounded-full">{p.position}</span>
                    </div>
                </div>
                <div className="flex flex-col items-end">
                    <span className={`text-2xl md:text-xl font-black ${textRank}`}>{value}</span>
                    <span className="text-[10px] uppercase font-bold text-muted-light">{type === 'goals' ? 'Gols' : 'Jogos'}</span>
                </div>
            </div>
        );
    };

    const topScorerLeader = topScorers[0];
    const topAppearanceLeader = topAppearances[0];

    return (
    <div className="space-y-8 animation-fade-in pb-20">

        {/* New Summary Cards for Stats */}
        <div className="grid grid-cols-2 gap-4 md:gap-6">
            <button onClick={() => setIsScorersModalOpen(true)} className="relative overflow-hidden bg-surface-light dark:bg-surface-dark rounded-2xl p-4 md:p-6 border border-gray-200 dark:border-gray-800 shadow-sm hover:border-primary/50 transition-all group text-left flex flex-col justify-between">
                <div className="absolute top-0 right-0 w-24 h-24 bg-yellow-500/10 rounded-full blur-2xl -mr-10 -mt-10 pointer-events-none"></div>
                <div className="relative z-10 w-full">
                    <div>
                        <div className="flex items-center gap-2 mb-2 text-yellow-600 dark:text-yellow-500">
                             <span className="material-icons-outlined">sports_soccer</span>
                             <span className="text-xs font-bold uppercase tracking-wider">Artilharia</span>
                        </div>
                        {topScorerLeader ? (
                            <div className="flex items-center gap-3 mt-4">
                                <img src={topScorerLeader.photoUrl} className="w-12 h-12 rounded-full object-cover object-top border-2 border-yellow-500" />
                                <div>
                                    <span className="text-xs text-muted-light font-bold">Líder</span>
                                    <p className="font-bold text-sm truncate max-w-[100px]">{topScorerLeader.name}</p>
                                </div>
                            </div>
                        ) : <p className="text-muted-light text-xs italic mt-2">Sem dados</p>}
                    </div>
                </div>
                <div className="mt-5 w-full py-2 rounded-xl border border-gray-200 dark:border-gray-700 text-muted-light dark:text-gray-400 text-[10px] md:text-xs font-bold uppercase tracking-wider group-hover:border-primary group-hover:text-primary transition-all flex items-center justify-center gap-2 relative z-10 bg-white/50 dark:bg-black/20 backdrop-blur-sm">
                    Ver Ranking <span className="material-icons-outlined text-sm">arrow_forward</span>
                </div>
            </button>

            <button onClick={() => setIsAppearancesModalOpen(true)} className="relative overflow-hidden bg-surface-light dark:bg-surface-dark rounded-2xl p-4 md:p-6 border border-gray-200 dark:border-gray-800 shadow-sm hover:border-primary/50 transition-all group text-left flex flex-col justify-between">
                <div className="absolute top-0 right-0 w-24 h-24 bg-blue-500/10 rounded-full blur-2xl -mr-10 -mt-10 pointer-events-none"></div>
                <div className="relative z-10 w-full">
                    <div>
                         <div className="flex items-center gap-2 mb-2 text-blue-600 dark:text-blue-500">
                             <span className="material-icons-outlined">history</span>
                             <span className="text-xs font-bold uppercase tracking-wider">Participações</span>
                        </div>
                        {topAppearanceLeader ? (
                            <div className="flex items-center gap-3 mt-4">
                                <img src={topAppearanceLeader.photoUrl} className="w-12 h-12 rounded-full object-cover object-top border-2 border-blue-500" />
                                <div>
                                    <span className="text-xs text-muted-light font-bold">Líder</span>
                                    <p className="font-bold text-sm truncate max-w-[100px]">{topAppearanceLeader.name}</p>
                                </div>
                            </div>
                        ) : <p className="text-muted-light text-xs italic mt-2">Sem dados</p>}
                    </div>
                </div>
                <div className="mt-5 w-full py-2 rounded-xl border border-gray-200 dark:border-gray-700 text-muted-light dark:text-gray-400 text-[10px] md:text-xs font-bold uppercase tracking-wider group-hover:border-primary group-hover:text-primary transition-all flex items-center justify-center gap-2 relative z-10 bg-white/50 dark:bg-black/20 backdrop-blur-sm">
                    Ver Ranking <span className="material-icons-outlined text-sm">arrow_forward</span>
                </div>
            </button>
        </div>

        {/* Players Grid */}
        <h3 className="text-xl font-bold mt-8">Jogadores</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
             {players.map(p => {
                 const nameParts = p.name.split(' ');
                 const firstName = nameParts[0]; // Usar apenas o primeiro nome

                 return (
                 <div 
                    key={p.id} 
                    onClick={() => openPlayerProfile(p)} 
                    className="relative group h-[280px] md:h-[340px] bg-gradient-to-b from-white to-gray-200 dark:from-[#1a1d22] dark:to-[#0f1115] rounded-[2.5rem] border border-gray-200 dark:border-gray-800 transition-all duration-500 hover:-translate-y-2 hover:shadow-2xl hover:border-primary/50 overflow-hidden flex flex-col justify-end cursor-pointer"
                 >
