                          <img 
                            src={p.photoUrl} 
                            className="h-full w-auto max-w-[120%] object-cover object-top drop-shadow-2xl filter group-hover:brightness-110 transition-all duration-500 mask-image-gradient" 
                            style={{ maskImage: 'linear-gradient(to bottom, black 70%, transparent 100%)' }}
