                      {/* Name Section - Single Name, Huge */}
                      <div className="relative z-20 w-full text-center mb-28 md:mb-24">
                          <span className="block text-3xl md:text-5xl font-black uppercase text-white leading-none tracking-tighter drop-shadow-lg truncate px-2">
                             {firstName}
                          </span>
                      </div>

                      {/* Stats Footer Grid */}
                      <div className="absolute bottom-0 w-full px-6 z-20 bg-gradient-to-t from-black/90 to-transparent pt-10 pb-6">
                          <div className="grid grid-cols-2 gap-2 w-full border-t border-white/20 pt-4">
                              <div className="flex flex-col items-center border-r border-white/10">
                                   <span className="text-[9px] uppercase font-bold text-gray-400 tracking-wider mb-1">POS</span>
                                   <span className="font-bold text-white text-lg">{p.position}</span>
                              </div>
                              <div className="flex flex-col items-center">
                                   <span className="text-[9px] uppercase font-bold text-gray-400 tracking-wider mb-1">GOLS</span>
                                   <span className="font-black text-primary text-xl">{p.goals}</span>
                              </div>
                          </div>
                      </div>
                 </div>
             )})}
        </div>

        {/* MODAL: Scorers */}
        {isScorersModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animation-fade-in">
                <div className="bg-surface-light dark:bg-surface-dark rounded-2xl w-full max-w-md max-h-[80vh] overflow-hidden flex flex-col shadow-2xl border border-gray-200 dark:border-gray-700">
                    <div className="p-4 border-b border-gray-100 dark:border-gray-800 flex justify-between items-center bg-gray-50 dark:bg-black/20">
                        <h3 className="font-bold text-lg flex items-center gap-2"><span className="material-icons-outlined text-yellow-500">emoji_events</span> Ranking de Artilheiros</h3>
                        <button onClick={() => setIsScorersModalOpen(false)} className="p-2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"><span className="material-icons-outlined">close</span></button>
                    </div>
                    <div className="overflow-y-auto p-4 space-y-3">
                        {topScorers.map((p, i) => renderRankingItem(p, i, p.goals, 'goals'))}
                        {topScorers.length === 0 && <p className="text-center text-muted-light py-8">Nenhum gol registrado.</p>}
                    </div>
                </div>
            </div>
        )}

        {/* MODAL: Appearances */}
        {isAppearancesModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animation-fade-in">
