                    <div className="p-4 border-b border-gray-100 dark:border-gray-800 flex justify-between items-center bg-gray-50 dark:bg-black/20">
                        <h3 className="font-bold text-lg flex items-center gap-2"><span className="material-icons-outlined text-blue-500">history</span> Ranking de Participação</h3>
                        <button onClick={() => setIsAppearancesModalOpen(false)} className="p-2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"><span className="material-icons-outlined">close</span></button>
