const CACHE_NAME = 'pesadao-fc-v2';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/manifest.json'
];

// Instalação do Service Worker e cache de recursos estáticos
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => cache.addAll(ASSETS_TO_CACHE))
      .then(() => self.skipWaiting())
  );
});

// Ativação e limpeza de caches antigos
self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.filter(name => name !== CACHE_NAME)
          .map(name => caches.delete(name))
      );
    })
  );
});

// Estratégia de Fetch: Tenta rede primeiro, se falhar tenta cache (para dados dinâmicos)
// Mas para o shell do app (index.html), pode usar cache primeiro se desejar
self.addEventListener('fetch', event => {
  // Ignora requisições do Supabase para não cachear dados obsoletos ou dar erro de CORS no cache
  if (event.request.url.includes('supabase.co')) {
    return;
  }

  event.respondWith(
    caches.match(event.request)
      .then(response => {
        // Retorna o recurso do cache se encontrado, senão busca na rede
        return response || fetch(event.request).catch(() => {
            // Se falhar e for navegação, retorna o index.html do cache
            if (event.request.mode === 'navigate') {
                return caches.match('/index.html');
            }
        });
      })
  );
});

