  const [newMatchLocationImg, setNewMatchLocationImg] = useState<string | null>(null);

  const [editingStatsId, setEditingStatsId] = useState<string | null>(null);
  const [tempStats, setTempStats] = useState({ goals: 0, matchesPlayed: 0, overall: 0, position: '' });

  // --- INITIALIZATION ---
  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const supabase = getSupabase();
    if (!supabase) {
      setApiKeyModalOpen(true);
      setLoading(false);
      return;
    }
    setIsConnected(true);
    fetchData();

    const channelPlayers = supabase.channel('realtime-players')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'players' }, () => fetchData())
      .subscribe();

    const channelMatches = supabase.channel('realtime-matches')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, () => fetchData())
      .subscribe();

    return () => {
      supabase.removeChannel(channelPlayers);
      supabase.removeChannel(channelMatches);
    };
  }, []);

  const fetchData = async () => {
    const supabase = getSupabase();
    if (!supabase) return;

    try {
      const { data: dataPlayers } = await supabase.from('players').select('*').order('name', { ascending: true });
      if (dataPlayers) {
        setPlayers(dataPlayers.map((p: any) => ({
          id: p.id.toString(),
          name: p.name,
          photoUrl: p.photo_url || 'https://via.placeholder.com/150',
          isPaid: false, 
          paymentDate: undefined,
          value: p.value,
          jerseyNumber: p.jersey_number,
          status: (p.status === 'injured' ? 'injured' : 'active') as 'active' | 'injured',
          paymentHistory: parsePaymentHistory(p.payment_date),
          position: p.position || 'MEI',
          goals: p.goals || 0,
          matchesPlayed: p.matches_played || 0,
          lastPlayedDate: p.last_played_date,
          overall: p.overall || 75
        })));
      }

      const { data: dataMatches } = await supabase.from('matches').select('*').order('date', { ascending: true });
      if (dataMatches) {
        setMatches(dataMatches.map((m: DbMatch) => ({
          id: m.id.toString(),
          opponent: m.opponent,
          locationImg: m.location_img,
          location: m.location || '',
          date: m.date,
          time: m.time,
          homeScore: m.home_score,
          awayScore: m.away_score,
          result: m.result as any,
          isFinished: m.is_finished,
          lineup: m.lineup || undefined,
          comments: m.comments || ''
        })));
      }
    } catch (error) {
      console.error("Erro ao buscar dados:", error);
    } finally {
      setLoading(false);
    }
  };

  const parsePaymentHistory = (dateStr: string | null): Record<string, string> => {
    if (!dateStr) return {};
    try {
        const parsed = JSON.parse(dateStr);
        return (typeof parsed === 'object' && parsed !== null) ? parsed : {};
    } catch (e) { return {}; }
  };

  const getMonthKey = (date: Date) => {
    const m = (date.getMonth() + 1).toString().padStart(2, '0');
    const y = date.getFullYear();
    return `${m}-${y}`;
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  const changeMonth = (increment: number) => {
    const newDate = new Date(selectedDate);
    newDate.setMonth(newDate.getMonth() + increment);
    setSelectedDate(newDate);
  };

  const getNextSundays = () => {
      const dates = [];
      let d = new Date();
      d.setDate(d.getDate() + (7 - d.getDay()) % 7);
      for(let i=0; i<6; i++) {
          dates.push(new Date(d));
          d.setDate(d.getDate() + 7);
      }
      return dates;
  };

  const financialStats = useMemo(() => {
    const currentMonthKey = getMonthKey(selectedDate);
    const playersView = players.map(p => ({ ...p, isPaid: !!p.paymentHistory[currentMonthKey] }));
    const active = playersView.filter(p => p.status === 'active' || p.isPaid);
    let collected = playersView.reduce((acc, p) => acc + (p.isPaid ? p.value : 0), 0);
    if (selectedDate.getMonth() === 0) collected += 130;
    const potential = active.reduce((acc, p) => acc + p.value, 0);
    const paid = playersView.filter(p => p.isPaid).length;
    return { collected, potential, paid, count: active.length, progress: active.length > 0 ? (paid / active.length) * 100 : 0 };
  }, [players, selectedDate]);

  const matchStats = useMemo(() => {
    const finished = matches.filter(m => m.isFinished);
    const wins = finished.filter(m => m.result === 'win').length;
    const draws = finished.filter(m => m.result === 'draw').length;
    const losses = finished.filter(m => m.result === 'loss').length;
    const goalsFor = finished.reduce((acc, m) => acc + m.homeScore, 0);
    const goalsAgainst = finished.reduce((acc, m) => acc + m.awayScore, 0);
    return { wins, draws, losses, total: finished.length, winRate: finished.length > 0 ? Math.round((wins / finished.length) * 100) : 0, goalsFor, goalsAgainst, goalDiff: goalsFor - goalsAgainst };
  }, [matches]);

  const topScorers = useMemo(() => [...players].sort((a, b) => b.goals - a.goals).slice(0, 5), [players]);
  const topAppearances = useMemo(() => [...players].sort((a, b) => b.matchesPlayed - a.matchesPlayed).slice(0, 3), [players]);

  const handleSaveKey = (e: React.FormEvent) => {
    e.preventDefault();
    if (apiKeyInput.trim()) {
      saveSupabaseKey(apiKeyInput.trim());
      setApiKeyModalOpen(false);
    }
  };

  const togglePayment = async (id: string) => {
    const supabase = getSupabase();
    if (!supabase) return;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const currentMonthKey = getMonthKey(selectedDate);
    const newHistory = { ...player.paymentHistory };
    const isPaidNow = !!newHistory[currentMonthKey];
    if (isPaidNow) delete newHistory[currentMonthKey];
    else newHistory[currentMonthKey] = new Date().toLocaleDateString('pt-BR');
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    await supabase.from('players').update({ payment_date: JSON.stringify(newHistory) }).eq('id', id);
  };

  const handlePhotoUpload = (e: ChangeEvent<HTMLInputElement>, setter: (val: string) => void) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => setter(reader.result as string);
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const updatePlayerPhoto = async (id: string, e: ChangeEvent<HTMLInputElement>) => {
    handlePhotoUpload(e, async (base64) => {
        const supabase = getSupabase();
        if(supabase) await supabase.from('players').update({ photo_url: base64 }).eq('id', id);
        fetchData();
    });
  };

  const deletePlayer = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Remover jogador?")) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').delete().eq('id', id);
      setPlayers(prev => prev.filter(p => p.id !== id));
    }
  };

  const togglePlayerStatus = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const player = players.find(p => p.id === id);
    if(!player) return;
    const newStatus = player.status === 'active' ? 'injured' : 'active';
    const supabase = getSupabase();
    if(supabase) await supabase.from('players').update({ status: newStatus }).eq('id', id);
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
  };

  const openEditPlayerModal = (player: Player, e: React.MouseEvent) => {
      e.stopPropagation();
      setEditingPlayer(player);
      setEditPlayerName(player.name);
      setEditPlayerNumber(player.jerseyNumber.toString());
      setEditPlayerPosition(player.position);
      setEditPlayerPhoto(player.photoUrl);
      setIsEditPlayerModalOpen(true);
  };

  const handleUpdatePlayer = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!editingPlayer || !editPlayerName.trim()) return;
      setIsSubmitting(true);
      const supabase = getSupabase();
      if (supabase) {
          const { error } = await supabase.from('players').update({ name: editPlayerName, jersey_number: parseInt(editPlayerNumber) || 0, position: editPlayerPosition, photo_url: editPlayerPhoto }).eq('id', editingPlayer.id);
          if (!error) {
              setPlayers(prev => prev.map(p => p.id === editingPlayer.id ? { ...p, name: editPlayerName, jerseyNumber: parseInt(editPlayerNumber) || 0, position: editPlayerPosition, photoUrl: editPlayerPhoto || p.photoUrl } : p));
              setIsEditPlayerModalOpen(false);
          }
      }
      setIsSubmitting(false);
  };

  const handleAddPlayer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlayerName.trim() || !newPlayerPhoto || isSubmitting) return;
    setIsSubmitting(true);
    const supabase = getSupabase();
    if (supabase) {
        const fullPayload = { name: newPlayerName, photo_url: newPlayerPhoto, is_paid: false, value: DEFAULT_FEE, jersey_number: parseInt(newPlayerNumber) || 0, status: 'active', payment_date: JSON.stringify({}), position: newPlayerPosition, goals: 0, matches_played: 0, overall: 70 };
        const { error } = await supabase.from('players').insert([fullPayload]);
        if (!error) await fetchData();
    }
    setNewPlayerName(''); setNewPlayerNumber(''); setNewPlayerPhoto(null); setIsAddModalOpen(false); setIsSubmitting(false);
  };

  const openPlayerProfile = (player: Player) => {
      setTempStats({ goals: player.goals, matchesPlayed: player.matchesPlayed, overall: player.overall, position: player.position });
      setEditingStatsId(player.id);
  };

  const savePlayerStats = async () => {
      if(!editingStatsId) return;
      const supabase = getSupabase();
      if(supabase) {
          const { error } = await supabase.from('players').update({ goals: tempStats.goals, matches_played: tempStats.matchesPlayed, overall: tempStats.overall, position: tempStats.position }).eq('id', editingStatsId);
          if (!error) setPlayers(prev => prev.map(p => p.id === editingStatsId ? { ...p, ...tempStats } : p));
      }
      setEditingStatsId(null);
  };

  const handleAddMatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if(isSubmitting) return;
    setIsSubmitting(true);
    const supabase = getSupabase();
    if(supabase) {
        const { error } = await supabase.from('matches').insert([{ opponent: newMatchOpponent, location: newMatchLocation, date: newMatchDate, time: newMatchTime, location_img: newMatchLocationImg, result: 'pending', is_finished: false }]);
        if (!error) await fetchData();
    }
    setNewMatchOpponent(''); setNewMatchLocation(''); setNewMatchDate(new Date().toISOString().split('T')[0]); setNewMatchTime(''); setNewMatchLocationImg(null); setIsAddModalOpen(false); setIsSubmitting(false);
  };

  const deleteMatch = async (id: string, e: React.MouseEvent) => {
      e.preventDefault(); e.stopPropagation();
      if (!window.confirm("Remover esta partida?")) return;
      const supabase = getSupabase();
      if(supabase) {
          const { error } = await supabase.from('matches').delete().eq('id', parseInt(id));
          if (!error) setMatches(prev => prev.filter(m => m.id !== id));
      }
  };

  // --- MATCH STATS FUNCTIONS ---
  const toggleMatchPresence = (playerId: string) => {
      setMatchPlayerStats(prev => {
          const current = prev[playerId] || { goals: 0, present: false };
          return { ...prev, [playerId]: { ...current, present: !current.present, goals: !current.present ? current.goals : 0 } };
      });
  };

  const updateMatchStat = (playerId: string, delta: number) => {
      setMatchPlayerStats(prev => {
          const current = prev[playerId];
          if (!current || !current.present) return prev;
          return { ...prev, [playerId]: { ...current, goals: Math.max(0, current.goals + delta) } };
      });
  };

  const resetMatchStats = () => {
      const reset = { ...matchPlayerStats };
      Object.keys(reset).forEach(k => { reset[k] = { goals: 0, present: false }; });
      setMatchPlayerStats(reset);
  };

  const selectActivePlayers = () => {
       const next = { ...matchPlayerStats };
       Object.keys(next).forEach((k, i) => { if (i < 11) next[k].present = true; });
       setMatchPlayerStats(next);
  };

  const openMatchResultModal = (match: Match) => {
      setSelectedMatch(match);
      setManualHomeScore(match.isFinished ? match.homeScore : 0);
      setManualAwayScore(match.isFinished ? match.awayScore : 0);
      setMatchComments(match.comments || '');
      const statsMap: Record<string, {goals: number, present: boolean}> = {};
      if (match.lineup) {
          const loaded = typeof match.lineup === 'string' ? JSON.parse(match.lineup) : match.lineup;
          if (loaded) Object.assign(statsMap, loaded);
      }
      players.forEach(p => { if (p.status === 'active' && !statsMap[p.id]) statsMap[p.id] = { goals: 0, present: false }; });
      setMatchPlayerStats(statsMap);
      setIsMatchResultModalOpen(true);
  };

  const confirmMatchResult = async () => {
      if (!selectedMatch) return;
      const supabase = getSupabase();
      if (!supabase) return;
      setIsSubmitting(true);
      let result = 'draw';
      if (manualHomeScore > manualAwayScore) result = 'win';
      else if (manualHomeScore < manualAwayScore) result = 'loss';

      const { error: mError } = await supabase.from('matches').update({ home_score: manualHomeScore, away_score: manualAwayScore, result, is_finished: true, lineup: matchPlayerStats, comments: matchComments }).eq('id', parseInt(selectedMatch.id));

      if (!mError) {
          // Atualiza estatísticas dos jogadores baseadas na súmula
          const updates = [];
          for (const pid in matchPlayerStats) {
              const stat = matchPlayerStats[pid];
              const player = players.find(p => p.id === pid);
              if (player && stat.present && !selectedMatch.isFinished) {
                  updates.push(supabase.from('players').update({ goals: (player.goals || 0) + stat.goals, matches_played: (player.matchesPlayed || 0) + 1 }).eq('id', parseInt(pid)));
              }
          }
          if (updates.length) await Promise.all(updates);
          await fetchData();
      }
      setIsMatchResultModalOpen(false); setIsSubmitting(false);
  };

  const renderFinancial = () => (
    <div className="space-y-8 md:space-y-10 animation-fade-in pb-20">
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 md:gap-8">
          <div className="xl:col-span-1 bg-surface-light dark:bg-surface-dark rounded-2xl p-6 md:p-8 border border-gray-200 dark:border-gray-800 shadow-sm relative overflow-hidden flex flex-col justify-between min-h-[200px] md:min-h-[220px]">
             <div className="absolute top-0 right-0 w-64 h-64 bg-primary/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
             <div className="relative z-10">
               <h2 className="text-muted-light dark:text-muted-dark font-medium mb-1 text-sm md:text-base">Total em Caixa ({selectedDate.toLocaleDateString('pt-BR', {month: 'long', year: 'numeric'})})</h2>
               <div className="flex items-baseline gap-2 mb-6">
                 <span className="text-4xl md:text-5xl font-bold tracking-tighter text-gray-900 dark:text-white">R$ {financialStats.collected}</span>
                 <span className="text-sm md:text-lg text-muted-light dark:text-muted-dark font-medium">/ {financialStats.potential}</span>
               </div>
             </div>
             <div className="relative z-10 mt-auto">
               <div className="flex justify-between text-sm font-semibold mb-3">
                 <span className="text-primary">{financialStats.paid} Pagos</span>
                 <span className="text-muted-light dark:text-muted-dark">{financialStats.count - financialStats.paid} Pendentes</span>
               </div>
               <div className="w-full bg-gray-200 dark:bg-gray-800 rounded-full h-3 md:h-4 overflow-hidden">
                 <div className="bg-primary h-3 md:h-4 rounded-full transition-all duration-700 ease-out" style={{ width: `${financialStats.progress}%` }}></div>
               </div>
             </div>
          </div>
          <div className="xl:col-span-2 bg-surface-light dark:bg-surface-dark rounded-2xl p-6 md:p-8 border border-gray-200 dark:border-gray-800 shadow-sm relative overflow-hidden">
              <div className="flex items-center gap-2 mb-6"><span className="material-icons-outlined text-yellow-500">emoji_events</span><h3 className="font-bold text-lg">Pagadores Rápidos</h3></div>
              <div className="flex items-end justify-around h-36 md:h-40 pb-2">
                 {[1, 0, 2].map((idx) => {
                     const p = (players.filter(p => !!p.paymentHistory[getMonthKey(selectedDate)] && p.status === 'active'))[idx];
                     return p ? (
                        <div key={p.id} className={`flex flex-col items-center gap-2 ${idx === 0 ? 'mb-4' : ''}`}>
                             <div className="relative">
                                 {idx === 0 && <span className="absolute -top-5 left-1/2 -translate-x-1/2 material-icons-outlined text-yellow-400 animate-bounce">crown</span>}
                                 <img src={p.photoUrl} className={`${idx === 0 ? 'w-20 h-20 md:w-24 md:h-24 border-yellow-400' : 'w-14 h-14 md:w-16 md:h-16 border-gray-400'} rounded-full border-4 object-cover object-top`} />
                             </div>
                             <div className="text-center mt-2"><p className="font-bold text-xs truncate max-w-[80px]">{p.name}</p></div>
                        </div>
                     ) : null;
                 })}
              </div>
          </div>
        </div>
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <h3 className="text-xl font-bold flex items-center gap-2">Elenco <span className="text-xs bg-gray-200 dark:bg-gray-800 px-2 py-1 rounded">{players.length}</span></h3>
                <div className="flex w-full md:w-auto items-center gap-2">
                    <div className="flex items-center gap-2 bg-surface-light dark:bg-surface-dark px-2 py-1 rounded-full border border-gray-200 dark:border-gray-700">
                        <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><span className="material-icons-outlined">chevron_left</span></button>
                        <span className="font-bold text-sm px-2">{selectedDate.toLocaleDateString('pt-BR', {month: 'long', year: 'numeric'})}</span>
                        <button onClick={() => changeMonth(1)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><span className="material-icons-outlined">chevron_right</span></button>
                    </div>
                    <button onClick={() => setIsAddModalOpen(true)} className="hidden md:flex items-center justify-center gap-2 bg-primary text-white font-bold px-4 py-2 rounded-xl text-sm shadow-lg shadow-primary/20"><span className="material-icons-outlined text-lg">add</span> Novo Jogador</button>
                </div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                 {players.map(p => (
                     <div key={p.id} className={`relative group h-[280px] md:h-[340px] bg-gradient-to-b from-white to-gray-200 dark:from-[#1a1d22] dark:to-[#0f1115] rounded-[2.5rem] border ${p.status === 'injured' ? 'border-orange-500/50' : (!!p.paymentHistory[getMonthKey(selectedDate)] ? 'border-green-500/50' : 'border-gray-200 dark:border-gray-800')} transition-all duration-500 hover:-translate-y-2 hover:shadow-2xl overflow-hidden flex flex-col justify-end`}>
                         <div className="absolute top-6 right-6 z-30 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={(e) => openEditPlayerModal(p, e)} className="w-8 h-8 rounded-full flex items-center justify-center bg-white/20 backdrop-blur-md text-gray-400 hover:text-white hover:bg-primary transition-colors"><span className="material-icons-outlined text-sm">edit</span></button>
                            <button onClick={(e) => togglePlayerStatus(p.id, e)} className={`w-8 h-8 rounded-full flex items-center justify-center backdrop-blur-md ${p.status === 'injured' ? 'bg-orange-500 text-white' : 'bg-white/20 text-gray-400 hover:text-orange-500'}`}><span className="material-icons-outlined text-sm">medical_services</span></button>
                            <button onClick={(e) => deletePlayer(p.id, e)} className="w-8 h-8 rounded-full flex items-center justify-center bg-white/20 backdrop-blur-md text-gray-400 hover:text-red-500 transition-colors"><span className="material-icons-outlined text-sm">delete</span></button>
                         </div>
                         <div className="absolute top-0 left-0 w-full px-6 py-6 flex justify-between items-start z-20 pointer-events-none">
                             <img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10 object-contain opacity-80" />
                             <span className="font-display font-black text-5xl text-gray-300 dark:text-gray-800 group-hover:text-primary/20 transition-colors">{p.jerseyNumber}</span>
                         </div>
                         <div className="absolute bottom-14 left-0 right-0 h-4/5 z-10 flex items-end justify-center">
                             <img src={p.photoUrl} className={`h-full w-auto max-w-[120%] object-cover object-top transition-all duration-500 ${p.status === 'injured' ? 'grayscale opacity-60' : ''}`} style={{ WebkitMaskImage: 'linear-gradient(to bottom, black 70%, transparent 100%)' }} />
                             <div className="absolute inset-0 bg-gradient-to-t from-gray-200 dark:from-[#0f1115] via-transparent to-transparent pointer-events-none"></div>
                         </div>
                         <div className="relative z-20 w-full text-center mb-28 md:mb-24 px-2">
                              <span className="block text-3xl md:text-5xl font-black uppercase text-white leading-none tracking-tighter truncate">{p.name.split(' ')[0]}</span>
                              <div className="mt-2 flex justify-center">
                                 <span className={`text-[10px] font-bold uppercase text-white px-2 py-0.5 rounded-full ${p.status === 'injured' ? 'bg-orange-500' : (!!p.paymentHistory[getMonthKey(selectedDate)] ? 'bg-green-500' : 'bg-red-500')}`}>{p.status === 'injured' ? 'Afastado' : (!!p.paymentHistory[getMonthKey(selectedDate)] ? 'Pago' : 'Não Pagou')}</span>
                              </div>
                         </div>
                         <div className="absolute bottom-0 w-full px-6 z-20 bg-gradient-to-t from-black/90 to-transparent pt-10 pb-6">
                             <div className="flex items-center justify-between border-t border-white/20 pt-4">
                                 <div className="flex flex-col"><span className="text-[9px] uppercase font-bold text-gray-400 mb-1">Mensalidade</span><span className="font-bold text-white text-lg">R$ {p.value}</span></div>
                                 <label className="cursor-pointer">
                                      <input type="checkbox" className="sr-only peer" checked={!!p.paymentHistory[getMonthKey(selectedDate)]} onChange={() => togglePayment(p.id)} disabled={p.status === 'injured'} />
                                      <div className="w-12 h-7 bg-white/10 rounded-full peer-checked:bg-primary transition-all relative backdrop-blur-md border border-white/10 shadow-inner">
                                          <div className={`absolute top-1 left-1 bg-white w-5 h-5 rounded-full transition-all shadow-md ${!!p.paymentHistory[getMonthKey(selectedDate)] ? 'translate-x-5' : ''}`}></div>
                                      </div>
                                 </label>
                             </div>
                         </div>
                     </div>
                 ))}
            </div>
        </div>
    </div>
  );

  const renderMatches = () => {
    const upcoming = matches.filter(m => !m.isFinished).sort((a,b) => a.date.localeCompare(b.date));
    const history = matches.filter(m => m.isFinished).sort((a,b) => b.date.localeCompare(a.date));
    const list = matchViewMode === 'upcoming' ? upcoming : history;
    const filtered = list.filter(m => m.opponent.toLowerCase().includes(searchQuery.toLowerCase()));

    return (
    <div className="space-y-8 animation-fade-in pb-20">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
             <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800 flex items-center justify-between">
                  <div><h3 className="text-muted-light font-bold text-sm uppercase">Aproveitamento</h3><p className="text-4xl font-bold mt-2">{matchStats.winRate}%</p></div>
                  <div className="w-16 h-16"><svg className="w-full h-full transform -rotate-90"><circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="6" fill="transparent" className="text-gray-200 dark:text-gray-800" /><circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="6" fill="transparent" strokeDasharray={176} strokeDashoffset={176 - (176 * matchStats.winRate) / 100} className="text-green-500" /></svg></div>
             </div>
             <div className="lg:col-span-2 grid grid-cols-3 gap-2">
                 <div className="bg-green-500/10 rounded-2xl p-4 flex flex-col items-center"><span className="text-2xl font-bold text-green-500">{matchStats.wins}</span><span className="text-[10px] font-bold uppercase text-green-600">Vitórias</span></div>
                 <div className="bg-gray-200/50 dark:bg-gray-700/30 rounded-2xl p-4 flex flex-col items-center"><span className="text-2xl font-bold text-gray-500">{matchStats.draws}</span><span className="text-[10px] font-bold uppercase text-gray-600">Empates</span></div>
                 <div className="bg-red-500/10 rounded-2xl p-4 flex flex-col items-center"><span className="text-2xl font-bold text-red-500">{matchStats.losses}</span><span className="text-[10px] font-bold uppercase text-red-600">Derrotas</span></div>
             </div>
             <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 border border-gray-200 dark:border-gray-800 flex flex-col justify-center">
                  <h3 className="text-muted-light font-bold text-xs uppercase mb-1">Saldo de Gols</h3>
                  <p className={`text-2xl font-bold ${matchStats.goalDiff >= 0 ? 'text-primary' : 'text-red-500'}`}>{matchStats.goalDiff > 0 ? '+' : ''}{matchStats.goalDiff}</p>
             </div>
        </div>
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-4">
                <div className="flex bg-gray-200 dark:bg-surface-dark p-1 rounded-lg">
                    <button onClick={() => setMatchViewMode('upcoming')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${matchViewMode === 'upcoming' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Próximos</button>
                    <button onClick={() => setMatchViewMode('history')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${matchViewMode === 'history' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Histórico</button>
                </div>
                <div className="flex w-full md:w-auto items-center gap-2">
                    <input type="text" placeholder="Buscar..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full md:w-64 bg-white dark:bg-black/20 border border-gray-200 dark:border-gray-700 rounded-full px-4 py-2 text-sm font-bold" />
                    <button onClick={() => setIsAddModalOpen(true)} className="hidden md:flex bg-primary text-white px-4 py-2 rounded-xl font-bold text-sm shadow-lg shadow-primary/20 whitespace-nowrap">Novo Jogo</button>
                </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {filtered.map(m => (
                    <div key={m.id} className={`relative rounded-2xl overflow-hidden flex flex-col transition-all duration-300 ${matchViewMode === 'upcoming' ? 'bg-gradient-to-br from-primary to-orange-500 text-white' : 'bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-800'}`}>
                        <div className="absolute top-3 right-3 z-50"><button onClick={(e) => deleteMatch(m.id, e)} className="p-2 rounded-full hover:bg-black/10"><span className="material-icons-outlined text-lg">delete_outline</span></button></div>
                        <div className="p-6 pt-10 flex items-center justify-between">
                             <div className="flex flex-col items-center gap-2 w-1/3"><img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10 object-contain" /><span className="font-bold text-xs truncate">Pesadão</span></div>
                             <div className="flex flex-col items-center justify-center w-1/3">
                                 <div className="px-3 py-1.5 rounded-lg font-mono text-3xl font-bold mb-2">{m.isFinished ? `${m.homeScore}-${m.awayScore}` : 'VS'}</div>
                                 <div className="text-[10px] font-bold uppercase opacity-80 text-center"><span>{new Date(m.date + 'T00:00:00').toLocaleDateString('pt-BR')}</span><br/><span>{m.time.slice(0,5)} • {m.location}</span></div>
                             </div>
                             <div className="flex flex-col items-center gap-2 w-1/3 text-center"><div className="w-10 h-10 rounded-full flex items-center justify-center bg-white/10 overflow-hidden">{m.locationImg ? <img src={m.locationImg} className="w-full h-full object-cover" /> : <span className="material-icons-outlined">sports_soccer</span>}</div><span className="font-bold text-xs truncate w-full">{m.opponent}</span></div>
                        </div>
                        <div className={`p-3 border-t flex justify-center ${matchViewMode === 'upcoming' ? 'border-white/10 bg-white/5' : 'border-gray-100 dark:border-gray-800'}`}>
                             <button onClick={() => openMatchResultModal(m)} className={`w-full py-2.5 rounded-lg text-xs font-bold uppercase flex items-center justify-center gap-2 transition-all ${matchViewMode === 'upcoming' ? 'bg-white/20 text-white' : 'bg-white dark:bg-surface-dark border border-gray-200 dark:border-gray-700 hover:bg-primary hover:text-white'}`}>
                                 <span className="material-icons-outlined text-[14px]">{m.isFinished ? "edit" : "sports_score"}</span> {m.isFinished ? "Editar Placar" : "Informar Placar"}
                             </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    </div>
  );
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark text-gray-900 dark:text-gray-100 font-display p-4 md:p-8 transition-colors duration-300 pb-24 md:pb-8">
        <div className="max-w-7xl mx-auto flex flex-row items-center justify-between mb-4 md:mb-8 sticky top-0 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur z-40 py-4">
             <div className="flex items-center gap-3"><img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10 md:w-12 md:h-12 object-contain" /><h1 className="text-lg md:text-xl font-bold tracking-tight">Pesadão F.C<span className="text-primary">.</span></h1></div>
             <nav className="hidden md:flex bg-gray-200 dark:bg-surface-dark p-1.5 rounded-full">
                 <button onClick={() => setCurrentTab('financial')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${currentTab === 'financial' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Financeiro</button>
                 <button onClick={() => setCurrentTab('matches')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${currentTab === 'matches' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Jogos</button>
                 <button onClick={() => setCurrentTab('stats')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${currentTab === 'stats' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Jogadores</button>
             </nav>
             <button onClick={toggleTheme} className="w-10 h-10 rounded-full bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-700 flex items-center justify-center hover:text-primary transition-colors"><span className="material-icons-outlined">{theme === 'dark' ? 'light_mode' : 'dark_mode'}</span></button>
        </div>

        <main className="max-w-7xl mx-auto">
             {currentTab === 'financial' && renderFinancial()}
             {currentTab === 'matches' && renderMatches()}
             {currentTab === 'stats' && renderStats()}
        </main>

        <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-surface-light/90 dark:bg-surface-dark/90 backdrop-blur-xl border-t border-gray-200 dark:border-gray-800 p-2 z-50 flex justify-around items-center safe-area-bottom pb-4 shadow-lg">
             <button onClick={() => setCurrentTab('financial')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg ${currentTab === 'financial' ? 'text-primary' : 'text-muted-light'}`}><span className="material-icons-outlined mb-1">attach_money</span><span className="text-[10px] font-bold uppercase">Financeiro</span></button>
             <button onClick={() => setCurrentTab('matches')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg ${currentTab === 'matches' ? 'text-primary' : 'text-muted-light'}`}><span className="material-icons-outlined mb-1">sports_soccer</span><span className="text-[10px] font-bold uppercase">Jogos</span></button>
             <button onClick={() => setCurrentTab('stats')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg ${currentTab === 'stats' ? 'text-primary' : 'text-muted-light'}`}><span className="material-icons-outlined mb-1">groups</span><span className="text-[10px] font-bold uppercase">Jogadores</span></button>
        </nav>

        {showInstallPrompt && isMobile && (
          <div className="fixed bottom-[80px] left-4 right-4 z-[70] animation-fade-in">
            <div className="bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-700 rounded-2xl p-4 flex items-center justify-between shadow-2xl backdrop-blur-md">
              <div className="flex items-center gap-3"><img src="https://i.imgur.com/GSj0ZPy.png" className="w-10 h-10" /><div><h4 className="font-bold text-sm">Instalar App</h4><p className="text-[10px] opacity-70">Acesso rápido offline</p></div></div>
              <div className="flex items-center gap-2"><button onClick={() => setShowInstallPrompt(false)} className="text-[10px] font-bold uppercase opacity-50 px-3">Depois</button><button onClick={handleInstallClick} className="bg-primary text-white text-xs font-bold px-4 py-2 rounded-xl shadow-lg">Instalar</button></div>
            </div>
          </div>
        )}

        {isIOS && isMobile && !window.matchMedia('(display-mode: standalone)').matches && (
          <div className="fixed bottom-[80px] left-4 right-4 z-[70] bg-surface-light dark:bg-surface-dark border border-gray-200 rounded-2xl p-4 text-[10px] font-bold flex items-center justify-center gap-2 shadow-2xl opacity-90 text-center uppercase">
            <span>Para instalar: Toque em <span className="material-icons-outlined text-xs inline">ios_share</span> e "Adicionar à Tela de Início"</span>
            <button onClick={() => setIsIOS(false)} className="ml-2 opacity-50"><span className="material-icons-outlined text-xs">close</span></button>
          </div>
        )}

        {/* --- MODALS --- */}
        {isAddModalOpen && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
                <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 w-full max-w-md shadow-2xl overflow-y-auto max-h-[90vh]">
                    <div className="flex justify-between items-center mb-6 border-b pb-4"><h3 className="font-bold text-xl">{currentTab === 'matches' ? 'Nova Partida' : 'Novo Jogador'}</h3><button onClick={() => setIsAddModalOpen(false)}><span className="material-icons-outlined">close</span></button></div>
                    {currentTab === 'matches' ? (
                        <form onSubmit={handleAddMatch} className="space-y-4">
                            <div><label className="text-xs font-bold uppercase text-muted-dark ml-1">Adversário</label><input type="text" value={newMatchOpponent} onChange={e => setNewMatchOpponent(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary" /></div>
                            <div><label className="text-xs font-bold uppercase text-muted-dark ml-1">Local</label><input type="text" value={newMatchLocation} onChange={e => setNewMatchLocation(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary" /></div>
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="text-xs font-bold uppercase text-muted-dark ml-1">Data</label><input type="date" value={newMatchDate} onChange={e => setNewMatchDate(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary" /></div>
                                <div><label className="text-xs font-bold uppercase text-muted-dark ml-1">Horário</label><input type="time" value={newMatchTime} onChange={e => setNewMatchTime(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary" /></div>
                            </div>
                            <button type="submit" disabled={!newMatchOpponent || !newMatchDate} className="w-full mt-4 bg-primary text-white font-bold py-3 rounded-xl hover:opacity-90 shadow-lg disabled:opacity-50">Agendar Jogo</button>
                        </form>
                    ) : (
                        <form onSubmit={handleAddPlayer} className="space-y-4">
                            <div className="flex justify-center mb-6"><div className="relative w-32 h-32"><div className="w-full h-full rounded-full bg-gray-100 dark:bg-gray-800 border-2 border-dashed border-gray-300 dark:border-gray-600 flex items-center justify-center overflow-hidden hover:border-primary">{newPlayerPhoto ? <img src={newPlayerPhoto} className="w-full h-full object-cover" /> : <span className="material-icons-outlined text-muted-dark text-4xl">add_a_photo</span>}</div><label className="absolute inset-0 cursor-pointer rounded-full"><input type="file" accept="image/*" onChange={(e) => handlePhotoUpload(e, setNewPlayerPhoto)} className="hidden" /></label></div></div>
                            <div><label className="text-xs font-bold uppercase text-muted-dark ml-1">Nome Completo</label><input type="text" value={newPlayerName} onChange={e => setNewPlayerName(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary" /></div>
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="text-xs font-bold uppercase text-muted-dark ml-1">Camisa</label><input type="number" value={newPlayerNumber} onChange={e => setNewPlayerNumber(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary" /></div>
                                <div><label className="text-xs font-bold uppercase text-muted-dark ml-1">Posição</label><select value={newPlayerPosition} onChange={e => setNewPlayerPosition(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3 font-bold text-sm focus:ring-primary"><option value="GOL">Goleiro</option><option value="ZAG">Zagueiro</option><option value="LAT">Lateral</option><option value="VOL">Volante</option><option value="MEI">Meia</option><option value="ATA">Atacante</option></select></div>
                            </div>
                            <button type="submit" disabled={!newPlayerName || !newPlayerPhoto} className="w-full mt-4 bg-primary text-white font-bold py-3 rounded-xl hover:opacity-90 shadow-lg disabled:opacity-50">Salvar Jogador</button>
                        </form>
                    )}
                </div>
            </div>
        )}

        {isMatchResultModalOpen && selectedMatch && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/90 backdrop-blur-sm">
                <div className="bg-surface-light dark:bg-surface-dark rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
                    <div className="p-6 border-b flex justify-between items-center bg-gray-50 dark:bg-black/20"><div><h2 className="text-xl font-bold">Súmula da Partida</h2><p className="text-sm opacity-70">{selectedMatch.opponent}</p></div><button onClick={() => setIsMatchResultModalOpen(false)}><span className="material-icons-outlined">close</span></button></div>
                    <div className="p-8 flex justify-center items-center gap-8">
                        <div className="text-center"><img src="https://i.imgur.com/GSj0ZPy.png" className="w-12 h-12 mx-auto mb-2" /><h3 className="font-bold text-xs">PESADÃO</h3><input type="number" min="0" value={manualHomeScore} onChange={(e) => setManualHomeScore(parseInt(e.target.value) || 0)} className="mt-2 w-16 h-16 text-center text-3xl font-bold bg-gray-100 dark:bg-black/30 border-2 rounded-xl focus:border-primary" /></div>
                        <span className="text-2xl font-bold">X</span>
                        <div className="text-center"><div className="w-12 h-12 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center mx-auto mb-2 overflow-hidden">{selectedMatch.locationImg ? <img src={selectedMatch.locationImg} className="w-full h-full object-cover" /> : <span className="material-icons-outlined">sports_soccer</span>}</div><h3 className="font-bold text-xs truncate max-w-[80px]">{selectedMatch.opponent}</h3><input type="number" min="0" value={manualAwayScore} onChange={(e) => setManualAwayScore(parseInt(e.target.value) || 0)} className="mt-2 w-16 h-16 text-center text-3xl font-bold bg-gray-100 dark:bg-black/30 border-2 rounded-xl focus:border-primary" /></div>
                    </div>
                    <div className="flex-1 overflow-y-auto p-6 bg-gray-50 dark:bg-black/10">
                        <div className="flex items-center justify-between mb-4"><h4 className="font-bold text-sm uppercase text-muted-light">Seleção de Atletas</h4><div className="flex gap-2"><button onClick={resetMatchStats} className="text-[10px] font-bold text-red-500 bg-red-100 px-3 py-1 rounded-lg">Limpar</button><button onClick={selectActivePlayers} className="text-[10px] font-bold text-primary bg-primary/10 px-3 py-1 rounded-lg">Titulares</button></div></div>
                        <div className="space-y-2">
                            {players.filter(p => p.status === 'active' || (matchPlayerStats[p.id]?.present)).sort((a,b) => (matchPlayerStats[b.id]?.present ? 1 : 0) - (matchPlayerStats[a.id]?.present ? 1 : 0)).map(p => {
                                const isPresent = matchPlayerStats[p.id]?.present;
                                return (
                                    <div key={p.id} onClick={() => toggleMatchPresence(p.id)} className={`flex items-center justify-between p-3 rounded-xl border cursor-pointer ${isPresent ? 'bg-white dark:bg-surface-dark border-green-500 shadow-md' : 'opacity-60'}`}>
                                        <div className="flex items-center gap-3"><div className={`w-6 h-6 rounded-full border flex items-center justify-center ${isPresent ? 'bg-green-500 border-green-500' : ''}`}>{isPresent && <span className="material-icons-outlined text-white text-sm">check</span>}</div><img src={p.photoUrl} className="w-10 h-10 rounded-full object-cover" /><div><p className="font-bold text-sm">{p.name}</p><p className="text-[10px] opacity-70">#{p.jerseyNumber}</p></div></div>
                                        {isPresent && (
                                            <div className="flex items-center gap-2" onClick={e => e.stopPropagation()}>
                                                <button onClick={() => updateMatchStat(p.id, -1)} className="w-6 h-6 bg-gray-100 dark:bg-gray-800 rounded font-bold">-</button>
                                                <span className="w-4 text-center font-bold text-primary">{matchPlayerStats[p.id]?.goals || 0}</span>
                                                <button onClick={() => updateMatchStat(p.id, 1)} className="w-6 h-6 bg-gray-100 dark:bg-gray-800 rounded font-bold">+</button>
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                    <div className="p-6 border-t bg-surface-light dark:bg-surface-dark"><button onClick={confirmMatchResult} disabled={isSubmitting} className="w-full py-4 bg-primary text-white font-bold rounded-xl shadow-lg hover:opacity-90">{isSubmitting ? 'Salvando...' : 'Confirmar Resultado'}</button></div>
                </div>
            </div>
        )}

        {editingStatsId && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
              <div className="bg-surface-light dark:bg-surface-dark rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
                  <div className="p-4 border-b flex justify-end"><button onClick={() => setEditingStatsId(null)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><span className="material-icons-outlined">close</span></button></div>
                  <div className="flex-1 overflow-y-auto">
                      <div className="flex flex-col items-center pt-4 pb-8 bg-gradient-to-b from-transparent to-gray-50 dark:to-black/20">
                          <img src={players.find(p => p.id === editingStatsId)?.photoUrl} className="w-32 h-32 rounded-full object-cover border-4 border-primary shadow-2xl mb-4" />
                          <h2 className="text-2xl font-bold">{players.find(p => p.id === editingStatsId)?.name}</h2>
                          <p className="text-muted-light font-bold">#{players.find(p => p.id === editingStatsId)?.jerseyNumber} • {players.find(p => p.id === editingStatsId)?.position}</p>
                      </div>
                      <div className="grid grid-cols-2 gap-4 px-6 py-6 border-y">
                          <div className="flex flex-col items-center bg-gray-50 dark:bg-black/20 p-4 rounded-2xl">
                              <span className="text-xs font-bold uppercase mb-2">Gols</span>
                              <div className="flex items-center gap-3"><button onClick={() => setTempStats(prev => ({...prev, goals: Math.max(0, prev.goals - 1)}))} className="w-8 h-8 bg-white dark:bg-gray-700 rounded-full shadow-sm font-bold">-</button><span className="text-3xl font-bold text-primary">{tempStats.goals}</span><button onClick={() => setTempStats(prev => ({...prev, goals: prev.goals + 1}))} className="w-8 h-8 bg-white dark:bg-gray-700 rounded-full shadow-sm font-bold">+</button></div>
                          </div>
                          <div className="flex flex-col items-center bg-gray-50 dark:bg-black/20 p-4 rounded-2xl">
                              <span className="text-xs font-bold uppercase mb-2">Jogos</span>
                              <div className="flex items-center gap-3"><button onClick={() => setTempStats(prev => ({...prev, matchesPlayed: Math.max(0, prev.matchesPlayed - 1)}))} className="w-8 h-8 bg-white dark:bg-gray-700 rounded-full shadow-sm font-bold">-</button><span className="text-3xl font-bold">{tempStats.matchesPlayed}</span><button onClick={() => setTempStats(prev => ({...prev, matchesPlayed: prev.matchesPlayed + 1}))} className="w-8 h-8 bg-white dark:bg-gray-700 rounded-full shadow-sm font-bold">+</button></div>
                          </div>
                      </div>
                  </div>
                  <div className="p-4 border-t bg-gray-50 dark:bg-black/10 flex justify-between items-center"><button onClick={() => setEditingStatsId(null)} className="px-6 py-3 font-bold text-gray-500">Cancelar</button><button onClick={savePlayerStats} className="px-8 py-3 bg-primary text-white font-bold rounded-xl shadow-lg">Salvar</button></div>
              </div>
          </div>
        )}

        {isEditPlayerModalOpen && editingPlayer && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
                <div className="bg-surface-light dark:bg-surface-dark rounded-2xl p-6 w-full max-w-md shadow-2xl"><div className="flex justify-between items-center mb-6 border-b pb-4"><h3 className="font-bold text-xl">Editar Atleta</h3><button onClick={() => setIsEditPlayerModalOpen(false)}><span className="material-icons-outlined">close</span></button></div>
                <form onSubmit={handleUpdatePlayer} className="space-y-4">
                    <div className="flex justify-center mb-6"><div className="relative w-32 h-32"><img src={editPlayerPhoto || editingPlayer.photoUrl} className="w-full h-full rounded-full object-cover border-2" /><label className="absolute inset-0 cursor-pointer rounded-full opacity-0 hover:opacity-100 bg-black/50 flex items-center justify-center text-white"><input type="file" accept="image/*" onChange={(e) => handlePhotoUpload(e, setEditPlayerPhoto)} className="hidden" /><span className="material-icons-outlined">edit</span></label></div></div>
                    <div><label className="text-xs font-bold uppercase opacity-70">Nome</label><input type="text" value={editPlayerName} onChange={e => setEditPlayerName(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3" /></div>
                    <div className="grid grid-cols-2 gap-4">
                        <div><label className="text-xs font-bold uppercase opacity-70">Número</label><input type="number" value={editPlayerNumber} onChange={e => setEditPlayerNumber(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3" /></div>
                        <div><label className="text-xs font-bold uppercase opacity-70">Posição</label><select value={editPlayerPosition} onChange={e => setEditPlayerPosition(e.target.value)} className="w-full mt-1 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-700 rounded-xl p-3"><option value="GOL">Goleiro</option><option value="ZAG">Zagueiro</option><option value="LAT">Lateral</option><option value="VOL">Volante</option><option value="MEI">Meia</option><option value="ATA">Atacante</option></select></div>
                    </div>
                    <button type="submit" disabled={isSubmitting} className="w-full mt-4 bg-primary text-white font-bold py-3 rounded-xl shadow-lg">{isSubmitting ? 'Salvando...' : 'Atualizar'}</button>
                </form></div>
            </div>
        )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, ChangeEvent } from 'react';
import { Player, DbPlayer, Match, DbMatch } from './types';
import { getSupabase, saveSupabaseKey, SUPABASE_URL } from './supabaseClient';

const DEFAULT_FEE = 40;

const App: React.FC = () => {
  // --- PWA INSTALL LOGIC ---
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showInstallPrompt, setShowInstallPrompt] = useState(false);
  const [isIOS, setIsIOS] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const mobileCheck = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) || window.innerWidth < 1024;
    setIsMobile(mobileCheck);

    const ios = /iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream;
    setIsIOS(ios);

    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
      if (mobileCheck) {
        setShowInstallPrompt(true);
      }
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    if (window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone) {
      setShowInstallPrompt(false);
    }

    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setDeferredPrompt(null);
      setShowInstallPrompt(false);
    }
  };

  // --- STATE ---
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [currentTab, setCurrentTab] = useState<'financial' | 'matches' | 'stats'>('matches'); 

  const [players, setPlayers] = useState<Player[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  const [apiKeyModalOpen, setApiKeyModalOpen] = useState(false);
  const [apiKeyInput, setApiKeyInput] = useState('');
  const [isConnected, setIsConnected] = useState(false);

  const [editingNameId, setEditingNameId] = useState<string | null>(null);
  const [tempName, setTempName] = useState<string>('');

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isEditPlayerModalOpen, setIsEditPlayerModalOpen] = useState(false);
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [editPlayerName, setEditPlayerName] = useState('');
  const [editPlayerNumber, setEditPlayerNumber] = useState('');
  const [editPlayerPosition, setEditPlayerPosition] = useState('');
  const [editPlayerPhoto, setEditPlayerPhoto] = useState<string | null>(null);

  const [isScorersModalOpen, setIsScorersModalOpen] = useState(false);
  const [isAppearancesModalOpen, setIsAppearancesModalOpen] = useState(false);

  const [matchViewMode, setMatchViewMode] = useState<'upcoming' | 'history'>('upcoming');
  const [searchQuery, setSearchQuery] = useState(''); 

  const [isMatchResultModalOpen, setIsMatchResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);
  const [manualHomeScore, setManualHomeScore] = useState(0);
  const [manualAwayScore, setManualAwayScore] = useState(0);
  const [matchComments, setMatchComments] = useState('');
  const [matchPlayerStats, setMatchPlayerStats] = useState<Record<string, {goals: number, present: boolean}>>({});

  const [newPlayerName, setNewPlayerName] = useState('');
  const [newPlayerNumber, setNewPlayerNumber] = useState('');
  const [newPlayerPhoto, setNewPlayerPhoto] = useState<string | null>(null);
  const [newPlayerPosition, setNewPlayerPosition] = useState('MEI');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [newMatchOpponent, setNewMatchOpponent] = useState('');
  const [newMatchLocation, setNewMatchLocation] = useState('');
  const [newMatchDate, setNewMatchDate] = useState(new Date().toISOString().split('T')[0]);
  const [newMatchTime, setNewMatchTime] = useState('');
  const [newMatchLocationImg, setNewMatchLocationImg] = useState<string | null>(null);

  const [editingStatsId, setEditingStatsId] = useState<string | null>(null);
  const [tempStats, setTempStats] = useState({ goals: 0, matchesPlayed: 0, overall: 0, position: '' });

  // --- INITIALIZATION ---
  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const supabase = getSupabase();
    if (!supabase) {
      setApiKeyModalOpen(true);
      setLoading(false);
      return;
    }
    setIsConnected(true);
    fetchData();

    const channelPlayers = supabase.channel('realtime-players')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'players' }, () => fetchData())
      .subscribe();

    const channelMatches = supabase.channel('realtime-matches')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, () => fetchData())
      .subscribe();

    return () => {
      supabase.removeChannel(channelPlayers);
      supabase.removeChannel(channelMatches);
    };
  }, []);

  const fetchData = async () => {
    const supabase = getSupabase();
    if (!supabase) return;

    try {
      const { data: dataPlayers } = await supabase.from('players').select('*').order('name', { ascending: true });
      if (dataPlayers) {
        setPlayers(dataPlayers.map((p: any) => ({
          id: p.id.toString(),
          name: p.name,
          photoUrl: p.photo_url || 'https://via.placeholder.com/150',
          isPaid: false, 
          paymentDate: undefined,
          value: p.value,
          jerseyNumber: p.jersey_number,
          status: (p.status === 'injured' ? 'injured' : 'active') as 'active' | 'injured',
          paymentHistory: parsePaymentHistory(p.payment_date),
          position: p.position || 'MEI',
          goals: p.goals || 0,
          matchesPlayed: p.matches_played || 0,
          lastPlayedDate: p.last_played_date,
          overall: p.overall || 75
        })));
      }

      const { data: dataMatches } = await supabase.from('matches').select('*').order('date', { ascending: true });
      if (dataMatches) {
        setMatches(dataMatches.map((m: DbMatch) => ({
          id: m.id.toString(),
          opponent: m.opponent,
          locationImg: m.location_img,
          location: m.location || '',
          date: m.date,
          time: m.time,
          homeScore: m.home_score,
          awayScore: m.away_score,
          result: m.result as any,
          isFinished: m.is_finished,
          lineup: m.lineup || undefined,
          comments: m.comments || ''
        })));
      }
    } catch (error) {
      console.error("Erro ao buscar dados:", error);
    } finally {
      setLoading(false);
    }
  };

  const parsePaymentHistory = (dateStr: string | null): Record<string, string> => {
    if (!dateStr) return {};
    try {
        const parsed = JSON.parse(dateStr);
        return (typeof parsed === 'object' && parsed !== null) ? parsed : {};
    } catch (e) { return {}; }
  };

  const getMonthKey = (date: Date) => {
    const m = (date.getMonth() + 1).toString().padStart(2, '0');
    const y = date.getFullYear();
    return `${m}-${y}`;
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  const changeMonth = (increment: number) => {
    const newDate = new Date(selectedDate);
    newDate.setMonth(newDate.getMonth() + increment);
    setSelectedDate(newDate);
  };

  const getNextSundays = () => {
      const dates = [];
      let d = new Date();
      d.setDate(d.getDate() + (7 - d.getDay()) % 7);
      for(let i=0; i<6; i++) {
          dates.push(new Date(d));
          d.setDate(d.getDate() + 7);
      }
      return dates;
  };

  const financialStats = useMemo(() => {
    const currentMonthKey = getMonthKey(selectedDate);
    const playersView = players.map(p => ({ ...p, isPaid: !!p.paymentHistory[currentMonthKey] }));
    const active = playersView.filter(p => p.status === 'active' || p.isPaid);
    let collected = playersView.reduce((acc, p) => acc + (p.isPaid ? p.value : 0), 0);
    if (selectedDate.getMonth() === 0) collected += 130;
    const potential = active.reduce((acc, p) => acc + p.value, 0);
    const paid = playersView.filter(p => p.isPaid).length;
    return { collected, potential, paid, count: active.length, progress: active.length > 0 ? (paid / active.length) * 100 : 0 };
  }, [players, selectedDate]);

  const matchStats = useMemo(() => {
    const finished = matches.filter(m => m.isFinished);
    const wins = finished.filter(m => m.result === 'win').length;
    const draws = finished.filter(m => m.result === 'draw').length;
    const losses = finished.filter(m => m.result === 'loss').length;
    const goalsFor = finished.reduce((acc, m) => acc + m.homeScore, 0);
    const goalsAgainst = finished.reduce((acc, m) => acc + m.awayScore, 0);
    return { wins, draws, losses, total: finished.length, winRate: finished.length > 0 ? Math.round((wins / finished.length) * 100) : 0, goalsFor, goalsAgainst, goalDiff: goalsFor - goalsAgainst };
  }, [matches]);

  const topScorers = useMemo(() => [...players].sort((a, b) => b.goals - a.goals).slice(0, 5), [players]);
  const topAppearances = useMemo(() => [...players].sort((a, b) => b.matchesPlayed - a.matchesPlayed).slice(0, 3), [players]);

  const handleSaveKey = (e: React.FormEvent) => {
    e.preventDefault();
    if (apiKeyInput.trim()) {
      saveSupabaseKey(apiKeyInput.trim());
      setApiKeyModalOpen(false);
    }
  };

  const togglePayment = async (id: string) => {
    const supabase = getSupabase();
    if (!supabase) return;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const currentMonthKey = getMonthKey(selectedDate);
    const newHistory = { ...player.paymentHistory };
    const isPaidNow = !!newHistory[currentMonthKey];
    if (isPaidNow) delete newHistory[currentMonthKey];
    else newHistory[currentMonthKey] = new Date().toLocaleDateString('pt-BR');
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    await supabase.from('players').update({ payment_date: JSON.stringify(newHistory) }).eq('id', id);
  };

  const handlePhotoUpload = (e: ChangeEvent<HTMLInputElement>, setter: (val: string) => void) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => setter(reader.result as string);
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const updatePlayerPhoto = async (id: string, e: ChangeEvent<HTMLInputElement>) => {
    handlePhotoUpload(e, async (base64) => {
        const supabase = getSupabase();
        if(supabase) await supabase.from('players').update({ photo_url: base64 }).eq('id', id);
        fetchData();
    });
  };

  const deletePlayer = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Remover jogador?")) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').delete().eq('id', id);
      setPlayers(prev => prev.filter(p => p.id !== id));
    }
  };

  const togglePlayerStatus = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const player = players.find(p => p.id === id);
    if(!player) return;
    const newStatus = player.status === 'active' ? 'injured' : 'active';
    const supabase = getSupabase();
    if(supabase) await supabase.from('players').update({ status: newStatus }).eq('id', id);
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
  };

  const openEditPlayerModal = (player: Player, e: React.MouseEvent) => {
      e.stopPropagation();
      setEditingPlayer(player);
      setEditPlayerName(player.name);
      setEditPlayerNumber(player.jerseyNumber.toString());
      setEditPlayerPosition(player.position);
      setEditPlayerPhoto(player.photoUrl);
      setIsEditPlayerModalOpen(true);
  };

  const handleUpdatePlayer = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!editingPlayer || !editPlayerName.trim()) return;
      setIsSubmitting(true);
      const supabase = getSupabase();
      if (supabase) {
          const { error } = await supabase.from('players').update({ name: editPlayerName, jersey_number: parseInt(editPlayerNumber) || 0, position: editPlayerPosition, photo_url: editPlayerPhoto }).eq('id', editingPlayer.id);
          if (!error) {
              setPlayers(prev => prev.map(p => p.id === editingPlayer.id ? { ...p, name: editPlayerName, jerseyNumber: parseInt(editPlayerNumber) || 0, position: editPlayerPosition, photoUrl: editPlayerPhoto || p.photoUrl } : p));
              setIsEditPlayerModalOpen(false);
          }
      }
      setIsSubmitting(false);
  };

  const handleAddPlayer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlayerName.trim() || !newPlayerPhoto || isSubmitting) return;
    setIsSubmitting(true);
    const supabase = getSupabase();
    if (supabase) {
        const fullPayload = { name: newPlayerName, photo_url: newPlayerPhoto, is_paid: false, value: DEFAULT_FEE, jersey_number: parseInt(newPlayerNumber) || 0, status: 'active', payment_date: JSON.stringify({}), position: newPlayerPosition, goals: 0, matches_played: 0, overall: 70 };
        const { error } = await supabase.from('players').insert([fullPayload]);
        if (!error) await fetchData();
    }
    setNewPlayerName(''); setNewPlayerNumber(''); setNewPlayerPhoto(null); setIsAddModalOpen(false); setIsSubmitting(false);
  };

  const openPlayerProfile = (player: Player) => {
      setTempStats({ goals: player.goals, matchesPlayed: player.matchesPlayed, overall: player.overall, position: player.position });
      setEditingStatsId(player.id);
  };

  const savePlayerStats = async () => {
      if(!editingStatsId) return;
      const supabase = getSupabase();
      if(supabase) {
          const { error } = await supabase.from('players').update({ goals: tempStats.goals, matches_played: tempStats.matchesPlayed, overall: tempStats.overall, position: tempStats.position }).eq('id', editingStatsId);
          if (!error) setPlayers(prev => prev.map(p => p.id === editingStatsId ? { ...p, ...tempStats } : p));
      }
      setEditingStatsId(null);
  };

  const handleAddMatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if(isSubmitting) return;
    setIsSubmitting(true);
    const supabase = getSupabase();
    if(supabase) {
        const { error } = await supabase.from('matches').insert([{ opponent: newMatchOpponent, location: newMatchLocation, date: newMatchDate, time: newMatchTime, location_img: newMatchLocationImg, result: 'pending', is_finished: false }]);
        if (!error) await fetchData();
    }
    setNewMatchOpponent(''); setNewMatchLocation(''); setNewMatchDate(new Date().toISOString().split('T')[0]); setNewMatchTime(''); setNewMatchLocationImg(null); setIsAddModalOpen(false); setIsSubmitting(false);
  };

  const deleteMatch = async (id: string, e: React.MouseEvent) => {
      e.preventDefault(); e.stopPropagation();
      if (!window.confirm("Remover esta partida?")) return;
      const supabase = getSupabase();
      if(supabase) {
          const { error } = await supabase.from('matches').delete().eq('id', parseInt(id));
          if (!error) setMatches(prev => prev.filter(m => m.id !== id));
      }
  };

  // --- MATCH STATS FUNCTIONS ---
  const toggleMatchPresence = (playerId: string) => {
      setMatchPlayerStats(prev => {
          const current = prev[playerId] || { goals: 0, present: false };
          return { ...prev, [playerId]: { ...current, present: !current.present, goals: !current.present ? current.goals : 0 } };
      });
  };

  const updateMatchStat = (playerId: string, delta: number) => {
      setMatchPlayerStats(prev => {
          const current = prev[playerId];
          if (!current || !current.present) return prev;
          return { ...prev, [playerId]: { ...current, goals: Math.max(0, current.goals + delta) } };
      });
  };

  const resetMatchStats = () => {
      const reset = { ...matchPlayerStats };
      Object.keys(reset).forEach(k => { reset[k] = { goals: 0, present: false }; });
      setMatchPlayerStats(reset);
  };

  const selectActivePlayers = () => {
       const next = { ...matchPlayerStats };
       Object.keys(next).forEach((k, i) => { if (i < 11) next[k].present = true; });
       setMatchPlayerStats(next);
  };

  const openMatchResultModal = (match: Match) => {
      setSelectedMatch(match);
      setManualHomeScore(match.isFinished ? match.homeScore : 0);
      setManualAwayScore(match.isFinished ? match.awayScore : 0);
      setMatchComments(match.comments || '');
      const statsMap: Record<string, {goals: number, present: boolean}> = {};
      if (match.lineup) {
          const loaded = typeof match.lineup === 'string' ? JSON.parse(match.lineup) : match.lineup;
          if (loaded) Object.assign(statsMap, loaded);
      }
      players.forEach(p => { if (p.status === 'active' && !statsMap[p.id]) statsMap[p.id] = { goals: 0, present: false }; });
      setMatchPlayerStats(statsMap);
      setIsMatchResultModalOpen(true);
  };

  const confirmMatchResult = async () => {
      if (!selectedMatch) return;
      const supabase = getSupabase();
      if (!supabase) return;
      setIsSubmitting(true);
      let result = 'draw';
      if (manualHomeScore > manualAwayScore) result = 'win';
      else if (manualHomeScore < manualAwayScore) result = 'loss';

      const { error: mError } = await supabase.from('matches').update({ home_score: manualHomeScore, away_score: manualAwayScore, result, is_finished: true, lineup: matchPlayerStats, comments: matchComments }).eq('id', parseInt(selectedMatch.id));

      if (!mError) {
          // Atualiza estatísticas dos jogadores baseadas na súmula
          const updates = [];
          for (const pid in matchPlayerStats) {
              const stat = matchPlayerStats[pid];
              const player = players.find(p => p.id === pid);
              if (player && stat.present && !selectedMatch.isFinished) {
                  updates.push(supabase.from('players').update({ goals: (player.goals || 0) + stat.goals, matches_played: (player.matchesPlayed || 0) + 1 }).eq('id', parseInt(pid)));
              }
          }
          if (updates.length) await Promise.all(updates);
          await fetchData();
      }
      setIsMatchResultModalOpen(false); setIsSubmitting(false);
  };

  const renderFinancial = () => (
    <div className="space-y-8 md:space-y-10 animation-fade-in pb-20">
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 md:gap-8">
          <div className="xl:col-span-1 bg-surface-light dark:bg-surface-dark rounded-2xl p-6 md:p-8 border border-gray-200 dark:border-gray-800 shadow-sm relative overflow-hidden flex flex-col justify-between min-h-[200px] md:min-h-[220px]">
             <div className="absolute top-0 right-0 w-64 h-64 bg-primary/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
             <div className="relative z-10">
               <h2 className="text-muted-light dark:text-muted-dark font-medium mb-1 text-sm md:text-base">Total em Caixa ({selectedDate.toLocaleDateString('pt-BR', {month: 'long', year: 'numeric'})})</h2>
               <div className="flex items-baseline gap-2 mb-6">
                 <span className="text-4xl md:text-5xl font-bold tracking-tighter text-gray-900 dark:text-white">R$ {financialStats.collected}</span>
                 <span className="text-sm md:text-lg text-muted-light dark:text-muted-dark font-medium">/ {financialStats.potential}</span>
               </div>
             </div>
             <div className="relative z-10 mt-auto">
               <div className="flex justify-between text-sm font-semibold mb-3">
                 <span className="text-primary">{financialStats.paid} Pagos</span>
                 <span className="text-muted-light dark:text-muted-dark">{financialStats.count - financialStats.paid} Pendentes</span>
               </div>
               <div className="w-full bg-gray-200 dark:bg-gray-800 rounded-full h-3 md:h-4 overflow-hidden">
                 <div className="bg-primary h-3 md:h-4 rounded-full transition-all duration-700 ease-out" style={{ width: `${financialStats.progress}%` }}></div>
               </div>
             </div>
          </div>
          <div className="xl:col-span-2 bg-surface-light dark:bg-surface-dark rounded-2xl p-6 md:p-8 border border-gray-200 dark:border-gray-800 shadow-sm relative overflow-hidden">
              <div className="flex items-center gap-2 mb-6"><span className="material-icons-outlined text-yellow-500">emoji_events</span><h3 className="font-bold text-lg">Pagadores Rápidos</h3></div>
              <div className="flex items-end justify-around h-36 md:h-40 pb-2">
                 {[1, 0, 2].map((idx) => {
                     const p = (players.filter(p => !!p.paymentHistory[getMonthKey(selectedDate)] && p.status === 'active'))[idx];
                     return p ? (
                        <div key={p.id} className={`flex flex-col items-center gap-2 ${idx === 0 ? 'mb-4' : ''}`}>
                             <div className="relative">
                                 {idx === 0 && <span className="absolute -top-5 left-1/2 -translate-x-1/2 material-icons-outlined text-yellow-400 animate-bounce">crown</span>}
                                 <img src={p.photoUrl} className={`${idx === 0 ? 'w-20 h-20 md:w-24 md:h-24 border-yellow-400' : 'w-14 h-14 md:w-16 md:h-16 border-gray-400'} rounded-full border-4 object-cover object-top`} />
                             </div>
                             <div className="text-center mt-2"><p className="font-bold text-xs truncate max-w-[80px]">{p.name}</p></div>
                        </div>
                     ) : null;
                 })}
              </div>
          </div>
        </div>
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <h3 className="text-xl font-bold flex items-center gap-2">Elenco <span className="text-xs bg-gray-200 dark:bg-gray-800 px-2 py-1 rounded">{players.length}</span></h3>
                <div className="flex w-full md:w-auto items-center gap-2">
                    <div className="flex items-center gap-2 bg-surface-light dark:bg-surface-dark px-2 py-1 rounded-full border border-gray-200 dark:border-gray-700">
                        <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><span className="material-icons-outlined">chevron_left</span></button>
                        <span className="font-bold text-sm px-2">{selectedDate.toLocaleDateString('pt-BR', {month: 'long', year: 'numeric'})}</span>
                        <button onClick={() => changeMonth(1)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><span className="material-icons-outlined">chevron_right</span></button>
                    </div>
                    <button onClick={() => setIsAddModalOpen(true)} className="hidden md:flex items-center justify-center gap-2 bg-primary text-white font-bold px-4 py-2 rounded-xl text-sm shadow-lg shadow-primary/20"><span className="material-icons-outlined text-lg">add</span> Novo Jogador</button>
                </div>
            </div>
