                    <button onClick={() => setMatchViewMode('history')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${matchViewMode === 'history' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Histórico</button>
                </div>
                <div className="flex w-full md:w-auto items-center gap-2">
                    <input type="text" placeholder="Buscar..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full md:w-64 bg-white dark:bg-black/20 border border-gray-200 dark:border-gray-700 rounded-full px-4 py-2 text-sm font-bold" />
