                              <button onClick={() => updateMatchStat(p.id, -1)} className="w-6 h-6 flex items-center justify-center bg-gray-200 dark:bg-gray-700 rounded-md text-xs">-</button>
                              <span className="w-4 text-center text-xs font-black">{stat.goals}</span>
                              <button onClick={() => updateMatchStat(p.id, 1)} className="w-6 h-6 flex items-center justify-center bg-primary text-white rounded-md text-xs">+</button>
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>

                <div className="flex flex-col gap-2">
                  <label className="text-[10px] font-black uppercase text-muted-light ml-1">O que aconteceu no jogo? (Comentários)</label>
                  <textarea value={matchComments} onChange={(e) => setMatchComments(e.target.value)} placeholder="Ex: Golaço do fulano, jogo difícil, lesão..." className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl text-sm min-h-[100px] p-4 focus:ring-2 focus:ring-primary/20"></textarea>
                </div>
              </div>

              <div className="p-6 border-t border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-black/20 flex gap-3">
                <button onClick={() => setIsMatchResultModalOpen(false)} className="flex-1 py-3 font-bold text-sm text-muted-light">Cancelar</button>
                <button onClick={confirmMatchResult} disabled={isSubmitting} className="flex-[2] py-3 bg-primary text-white font-bold rounded-xl shadow-lg shadow-primary/30 flex items-center justify-center gap-2">
                  {isSubmitting ? 'Salvando...' : 'Salvar Relatório'}
                </button>
              </div>
            </div>
          </div>
        )}

        {/* MODAL ADICIONAR (SIMPLIFICADO) */}
        {isAddModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-surface-light dark:bg-surface-dark w-full max-w-md rounded-3xl border border-gray-200 dark:border-gray-800 overflow-hidden shadow-2xl p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold">{addMode === 'player' ? 'Novo Jogador' : 'Novo Jogo'}</h3>
                <button onClick={() => setIsAddModalOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-200 dark:hover:bg-gray-800"><span className="material-icons-outlined">close</span></button>
              </div>

              {addMode === 'player' ? (
                <form onSubmit={handleAddPlayer} className="space-y-4">
                  <div>
                    <label className="text-[10px] font-black uppercase text-muted-light mb-1 block">Nome do Jogador</label>
                    <input type="text" required value={newPlayerName} onChange={(e) => setNewPlayerName(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl p-3 text-sm" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black uppercase text-muted-light mb-1 block">Número</label>
                      <input type="number" required value={newPlayerNumber} onChange={(e) => setNewPlayerNumber(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl p-3 text-sm" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-muted-light mb-1 block">Posição</label>
                      <select value={newPlayerPosition} onChange={(e) => setNewPlayerPosition(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl p-3 text-sm">
                        <option value="GOL">Goleiro</option>
                        <option value="LAT">Lateral</option>
                        <option value="ZAG">Zagueiro</option>
                        <option value="VOL">Volante</option>
                        <option value="MEI">Meia</option>
                        <option value="ATA">Atacante</option>
                      </select>
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-muted-light mb-1 block">Foto (Base64/URL)</label>
                    <input type="file" accept="image/*" onChange={(e) => handlePhotoUpload(e, setNewPlayerPhoto)} className="w-full text-xs" />
                  </div>
                  <button type="submit" disabled={isSubmitting} className="w-full bg-primary text-white font-bold py-4 rounded-xl shadow-lg mt-4">{isSubmitting ? 'Salvando...' : 'Adicionar Atleta'}</button>
                </form>
              ) : (
                <form onSubmit={handleAddMatch} className="space-y-4">
                  <div>
                    <label className="text-[10px] font-black uppercase text-muted-light mb-1 block">Adversário</label>
                    <input type="text" required value={newMatchOpponent} onChange={(e) => setNewMatchOpponent(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl p-3 text-sm" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-muted-light mb-1 block">Local</label>
                    <input type="text" required value={newMatchLocation} onChange={(e) => setNewMatchLocation(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl p-3 text-sm" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black uppercase text-muted-light mb-1 block">Data</label>
                      <input type="date" required value={newMatchDate} onChange={(e) => setNewMatchDate(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl p-3 text-sm" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-muted-light mb-1 block">Horário</label>
                      <input type="time" required value={newMatchTime} onChange={(e) => setNewMatchTime(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl p-3 text-sm" />
                    </div>
                  </div>
                  <button type="submit" disabled={isSubmitting} className="w-full bg-primary text-white font-bold py-4 rounded-xl shadow-lg mt-4">{isSubmitting ? 'Salvando...' : 'Marcar Partida'}</button>
                </form>
              )}
            </div>
          </div>
        )}

        {/* MODAL EDITAR JOGADOR */}
        {isEditPlayerModalOpen && editingPlayer && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-surface-light dark:bg-surface-dark w-full max-w-md rounded-3xl border border-gray-200 dark:border-gray-800 p-6">
              <h3 className="text-xl font-bold mb-6">Editar Jogador</h3>
              <form onSubmit={handleUpdatePlayer} className="space-y-4">
                  <input type="text" value={editPlayerName} onChange={(e) => setEditPlayerName(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl p-3 text-sm" placeholder="Nome" />
                  <input type="number" value={editPlayerNumber} onChange={(e) => setEditPlayerNumber(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl p-3 text-sm" placeholder="Número" />
                  <select value={editPlayerPosition} onChange={(e) => setEditPlayerPosition(e.target.value)} className="w-full bg-gray-100 dark:bg-black/20 border-0 rounded-xl p-3 text-sm">
                    <option value="GOL">Goleiro</option>
                    <option value="LAT">Lateral</option>
                    <option value="ZAG">Zagueiro</option>
                    <option value="VOL">Volante</option>
                    <option value="MEI">Meia</option>
                    <option value="ATA">Atacante</option>
                  </select>
                  <button type="submit" className="w-full bg-primary text-white font-bold py-4 rounded-xl shadow-lg">Salvar Alterações</button>
                  <button type="button" onClick={() => setIsEditPlayerModalOpen(false)} className="w-full py-4 text-muted-light font-bold">Cancelar</button>
              </form>
            </div>
          </div>
        )}

        {/* MENSAGENS PWA */}
        {showInstallPrompt && isMobile && (
          <div className="fixed bottom-[85px] left-4 right-4 z-[70] animation-fade-in pointer-events-none">
            <div className="bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-700 rounded-2xl p-4 flex items-center justify-between shadow-2xl backdrop-blur-md pointer-events-auto">
              <div className="flex items-center gap-3">
                <img src={PWA_LOGO_URL} className="w-10 h-10 rounded-xl" />
                <div>
                  <h4 className="font-bold text-sm">Pesadão FC App</h4>
                  <p className="text-[10px] opacity-70">Acesso rápido no seu celular</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button onClick={() => setShowInstallPrompt(false)} className="text-[10px] font-bold uppercase opacity-50 px-3">Fechar</button>
                <button onClick={handleInstallClick} className="bg-primary text-white text-xs font-bold px-4 py-2 rounded-xl shadow-lg shadow-primary/20">Instalar</button>
              </div>
            </div>
          </div>
        )}

        {isIOS && isMobile && !window.matchMedia('(display-mode: standalone)').matches && (
          <div className="fixed bottom-[85px] left-4 right-4 z-[70] bg-surface-light dark:bg-surface-dark border border-gray-200 rounded-2xl p-4 text-[10px] font-bold flex flex-col items-center gap-2 shadow-2xl opacity-90 text-center uppercase">
            <span>Toque em <span className="material-icons-outlined text-xs inline">ios_share</span> e "Adicionar à Tela de Início"</span>
            <button onClick={() => setIsIOS(false)} className="opacity-50 text-[9px]">Entendi</button>
          </div>
        )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, ChangeEvent } from 'react';
import { Player, DbPlayer, Match, DbMatch } from './types';
import { getSupabase, saveSupabaseKey, SUPABASE_URL } from './supabaseClient';

const DEFAULT_FEE = 40;
const TEAM_LOGO_URL = 'https://i.imgur.com/GSj0ZPy.png'; // Ícone transparente (Interno)
const PWA_LOGO_URL = 'https://i.imgur.com/CxbCPR5.png';   // Ícone PWA (Sólido/Download)

const App: React.FC = () => {
  // --- PWA INSTALL LOGIC ---
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showInstallPrompt, setShowInstallPrompt] = useState(false);
  const [isIOS, setIsIOS] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const checkMobile = () => {
      const isMobileSize = window.innerWidth < 1024;
      const isMobileUA = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
      return isMobileSize || isMobileUA;
    };

    const mobileStatus = checkMobile();
    setIsMobile(mobileStatus);

    const ios = /iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream;
    setIsIOS(ios);

    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
      if (mobileStatus && !window.matchMedia('(display-mode: standalone)').matches) {
        setShowInstallPrompt(true);
      }
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    if (window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone) {
      setShowInstallPrompt(false);
    }

    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setDeferredPrompt(null);
      setShowInstallPrompt(false);
    }
  };

  // --- STATE ---
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [currentTab, setCurrentTab] = useState<'financial' | 'matches' | 'stats'>('matches'); 

  const [players, setPlayers] = useState<Player[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  const [apiKeyModalOpen, setApiKeyModalOpen] = useState(false);
  const [isConnected, setIsConnected] = useState(false);

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [addMode, setAddMode] = useState<'player' | 'match'>('player');

  const [isEditPlayerModalOpen, setIsEditPlayerModalOpen] = useState(false);
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [editPlayerName, setEditPlayerName] = useState('');
  const [editPlayerNumber, setEditPlayerNumber] = useState('');
  const [editPlayerPosition, setEditPlayerPosition] = useState('');
  const [editPlayerPhoto, setEditPlayerPhoto] = useState<string | null>(null);

  const [isMatchResultModalOpen, setIsMatchResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);
  const [manualHomeScore, setManualHomeScore] = useState<number | string>(0);
  const [manualAwayScore, setManualAwayScore] = useState<number | string>(0);
  const [matchComments, setMatchComments] = useState('');
  const [matchPlayerStats, setMatchPlayerStats] = useState<Record<string, {goals: number, present: boolean}>>({});

  const [matchViewMode, setMatchViewMode] = useState<'upcoming' | 'history'>('upcoming');
  const [searchQuery, setSearchQuery] = useState('');

  const [newPlayerName, setNewPlayerName] = useState('');
  const [newPlayerNumber, setNewPlayerNumber] = useState('');
  const [newPlayerPhoto, setNewPlayerPhoto] = useState<string | null>(null);
  const [newPlayerPosition, setNewPlayerPosition] = useState('MEI');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [newMatchOpponent, setNewMatchOpponent] = useState('');
  const [newMatchLocation, setNewMatchLocation] = useState('');
  const [newMatchDate, setNewMatchDate] = useState(new Date().toISOString().split('T')[0]);
  const [newMatchTime, setNewMatchTime] = useState('');
  const [newMatchLocationImg, setNewMatchLocationImg] = useState<string | null>(null);

  const [editingStatsId, setEditingStatsId] = useState<string | null>(null);
  const [tempStats, setTempStats] = useState({ goals: 0, matchesPlayed: 0, overall: 0, position: '' });

  // --- INITIALIZATION ---
  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const supabase = getSupabase();
    if (!supabase) {
      setApiKeyModalOpen(true);
      setLoading(false);
      return;
    }
    setIsConnected(true);
    fetchData();

    const channelPlayers = supabase.channel('realtime-players')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'players' }, () => fetchData())
      .subscribe();

    const channelMatches = supabase.channel('realtime-matches')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, () => fetchData())
      .subscribe();

    return () => {
      supabase.removeChannel(channelPlayers);
      supabase.removeChannel(channelMatches);
    };
  }, []);

  const fetchData = async () => {
    const supabase = getSupabase();
    if (!supabase) return;

    try {
      const { data: dataPlayers } = await supabase.from('players').select('*').order('name', { ascending: true });
      if (dataPlayers) {
        setPlayers(dataPlayers.map((p: any) => ({
          id: p.id.toString(),
          name: p.name,
          photoUrl: p.photo_url || 'https://via.placeholder.com/150',
          isPaid: false, 
          paymentDate: undefined,
          value: p.value,
          jerseyNumber: p.jersey_number,
          status: (p.status === 'injured' ? 'injured' : 'active') as 'active' | 'injured',
          paymentHistory: parsePaymentHistory(p.payment_date),
          position: p.position || 'MEI',
          goals: p.goals || 0,
          matchesPlayed: p.matches_played || 0,
          lastPlayedDate: p.last_played_date,
          overall: p.overall || 75
        })));
      }

      const { data: dataMatches } = await supabase.from('matches').select('*').order('date', { ascending: true });
      if (dataMatches) {
        setMatches(dataMatches.map((m: DbMatch) => ({
          id: m.id.toString(),
          opponent: m.opponent,
          locationImg: m.location_img,
          location: m.location || '',
          date: m.date,
          time: m.time,
          homeScore: m.home_score,
          awayScore: m.away_score,
          result: m.result as any,
          isFinished: m.is_finished,
          lineup: m.lineup || undefined,
          comments: m.comments || ''
        })));
      }
    } catch (error) {
      console.error("Erro ao buscar dados:", error);
    } finally {
      setLoading(false);
    }
  };

  const parsePaymentHistory = (dateStr: string | null): Record<string, string> => {
    if (!dateStr) return {};
    try {
        const parsed = JSON.parse(dateStr);
        return (typeof parsed === 'object' && parsed !== null) ? parsed : {};
    } catch (e) { return {}; }
  };

  const getMonthKey = (date: Date) => {
    const m = (date.getMonth() + 1).toString().padStart(2, '0');
    const y = date.getFullYear();
    return `${m}-${y}`;
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  const changeMonth = (increment: number) => {
    const newDate = new Date(selectedDate);
    newDate.setMonth(newDate.getMonth() + increment);
    setSelectedDate(newDate);
  };

  const financialStats = useMemo(() => {
    const currentMonthKey = getMonthKey(selectedDate);
    const playersView = players.map(p => ({ ...p, isPaid: !!p.paymentHistory[currentMonthKey] }));
    const active = playersView.filter(p => p.status === 'active' || p.isPaid);
    let collected = playersView.reduce((acc, p) => acc + (p.isPaid ? p.value : 0), 0);
    if (selectedDate.getMonth() === 0) collected += 130;
    const potential = active.reduce((acc, p) => acc + p.value, 0);
    const paid = playersView.filter(p => p.isPaid).length;
    return { collected, potential, paid, count: active.length, progress: active.length > 0 ? (paid / active.length) * 100 : 0 };
  }, [players, selectedDate]);

  const matchStats = useMemo(() => {
    const finished = matches.filter(m => m.isFinished);
    const wins = finished.filter(m => m.result === 'win').length;
    const draws = finished.filter(m => m.result === 'draw').length;
    const losses = finished.filter(m => m.result === 'loss').length;
    const goalsFor = finished.reduce((acc, m) => acc + m.homeScore, 0);
    const goalsAgainst = finished.reduce((acc, m) => acc + m.awayScore, 0);
    return { wins, draws, losses, total: finished.length, winRate: finished.length > 0 ? Math.round((wins / finished.length) * 100) : 0, goalsFor, goalsAgainst, goalDiff: goalsFor - goalsAgainst };
  }, [matches]);

  const topScorers = useMemo(() => [...players].sort((a, b) => b.goals - a.goals).slice(0, 5), [players]);
  const topAppearances = useMemo(() => [...players].sort((a, b) => b.matchesPlayed - a.matchesPlayed).slice(0, 3), [players]);

  const togglePayment = async (id: string) => {
    const supabase = getSupabase();
    if (!supabase) return;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const currentMonthKey = getMonthKey(selectedDate);
    const newHistory = { ...player.paymentHistory };
    const isPaidNow = !!newHistory[currentMonthKey];
    if (isPaidNow) delete newHistory[currentMonthKey];
    else newHistory[currentMonthKey] = new Date().toLocaleDateString('pt-BR');
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    await supabase.from('players').update({ payment_date: JSON.stringify(newHistory) }).eq('id', id);
  };

  const handlePhotoUpload = (e: ChangeEvent<HTMLInputElement>, setter: (val: string) => void) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => setter(reader.result as string);
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const deletePlayer = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Remover jogador?")) {
      const supabase = getSupabase();
      if(supabase) await supabase.from('players').delete().eq('id', id);
      setPlayers(prev => prev.filter(p => p.id !== id));
    }
  };

  const togglePlayerStatus = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const player = players.find(p => p.id === id);
    if(!player) return;
    const newStatus = player.status === 'active' ? 'injured' : 'active';
    const supabase = getSupabase();
    if(supabase) await supabase.from('players').update({ status: newStatus }).eq('id', id);
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
  };

  const openEditPlayerModal = (player: Player, e: React.MouseEvent) => {
      e.stopPropagation();
      setEditingPlayer(player);
      setEditPlayerName(player.name);
      setEditPlayerNumber(player.jerseyNumber.toString());
      setEditPlayerPosition(player.position);
      setEditPlayerPhoto(player.photoUrl);
      setIsEditPlayerModalOpen(true);
  };

  const handleUpdatePlayer = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!editingPlayer || !editPlayerName.trim()) return;
      setIsSubmitting(true);
      const supabase = getSupabase();
      if (supabase) {
          const { error } = await supabase.from('players').update({ name: editPlayerName, jersey_number: parseInt(editPlayerNumber) || 0, position: editPlayerPosition, photo_url: editPlayerPhoto }).eq('id', editingPlayer.id);
          if (!error) {
              setPlayers(prev => prev.map(p => p.id === editingPlayer.id ? { ...p, name: editPlayerName, jerseyNumber: parseInt(editPlayerNumber) || 0, position: editPlayerPosition, photoUrl: editPlayerPhoto || p.photoUrl } : p));
              setIsEditPlayerModalOpen(false);
          }
      }
      setIsSubmitting(false);
  };

  const handleAddPlayer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlayerName.trim() || !newPlayerPhoto || isSubmitting) return;
    setIsSubmitting(true);
    const supabase = getSupabase();
    if (supabase) {
        const fullPayload = { name: newPlayerName, photo_url: newPlayerPhoto, is_paid: false, value: DEFAULT_FEE, jersey_number: parseInt(newPlayerNumber) || 0, status: 'active', payment_date: JSON.stringify({}), position: newPlayerPosition, goals: 0, matches_played: 0, overall: 70 };
        const { error } = await supabase.from('players').insert([fullPayload]);
        if (!error) await fetchData();
    }
    setNewPlayerName(''); setNewPlayerNumber(''); setNewPlayerPhoto(null); setIsAddModalOpen(false); setIsSubmitting(false);
  };

  const openPlayerProfile = (player: Player) => {
      setTempStats({ goals: player.goals, matchesPlayed: player.matchesPlayed, overall: player.overall, position: player.position });
      setEditingStatsId(player.id);
  };

  const handleAddMatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if(isSubmitting) return;
    setIsSubmitting(true);
    const supabase = getSupabase();
    if(supabase) {
        const { error } = await supabase.from('matches').insert([{ opponent: newMatchOpponent, location: newMatchLocation, date: newMatchDate, time: newMatchTime, location_img: newMatchLocationImg, result: 'pending', is_finished: false }]);
        if (!error) await fetchData();
    }
    setNewMatchOpponent(''); setNewMatchLocation(''); setNewMatchDate(new Date().toISOString().split('T')[0]); setNewMatchTime(''); setNewMatchLocationImg(null); setIsAddModalOpen(false); setIsSubmitting(false);
  };

  const deleteMatch = async (id: string, e: React.MouseEvent) => {
      e.preventDefault(); e.stopPropagation();
      if (!window.confirm("Remover esta partida?")) return;
      const supabase = getSupabase();
      if(supabase) {
          const { error } = await supabase.from('matches').delete().eq('id', parseInt(id));
          if (!error) setMatches(prev => prev.filter(m => m.id !== id));
      }
  };

  const toggleMatchPresence = (playerId: string) => {
      setMatchPlayerStats(prev => {
          const current = prev[playerId] || { goals: 0, present: false };
          return { ...prev, [playerId]: { ...current, present: !current.present, goals: !current.present ? current.goals : 0 } };
      });
  };

  const updateMatchStat = (playerId: string, delta: number) => {
      setMatchPlayerStats(prev => {
          const current = prev[playerId];
          if (!current || !current.present) return prev;
          return { ...prev, [playerId]: { ...current, goals: Math.max(0, current.goals + delta) } };
      });
  };

  const openMatchResultModal = (match: Match) => {
      setSelectedMatch(match);
      // Se não estiver finalizado, iniciamos como vazio (ou 0 mas exibido vazio)
      setManualHomeScore(match.isFinished ? match.homeScore : '');
      setManualAwayScore(match.isFinished ? match.awayScore : '');
      setMatchComments(match.comments || '');
      const statsMap: Record<string, {goals: number, present: boolean}> = {};
      if (match.lineup) {
          try {
            const loaded = typeof match.lineup === 'string' ? JSON.parse(match.lineup) : match.lineup;
            if (loaded) Object.assign(statsMap, loaded);
          } catch(e) {}
      }
      players.forEach(p => { if (p.status === 'active' && !statsMap[p.id]) statsMap[p.id] = { goals: 0, present: false }; });
      setMatchPlayerStats(statsMap);
      setIsMatchResultModalOpen(true);
  };

  const confirmMatchResult = async () => {
      if (!selectedMatch) return;
      const supabase = getSupabase();
      if (!supabase) return;
      setIsSubmitting(true);

      const homeVal = parseInt(manualHomeScore.toString()) || 0;
      const awayVal = parseInt(manualAwayScore.toString()) || 0;

      let result = 'draw';
      if (homeVal > awayVal) result = 'win';
      else if (homeVal < awayVal) result = 'loss';

      const { error: mError } = await supabase.from('matches').update({ 
          home_score: homeVal, 
          away_score: awayVal, 
          result, 
          is_finished: true, 
          lineup: matchPlayerStats, 
          comments: matchComments 
      }).eq('id', parseInt(selectedMatch.id));

      if (mError) {
          alert("Erro ao salvar partida: " + mError.message);
          setIsSubmitting(false);
          return;
      }

      if (!selectedMatch.isFinished) {
          const updates = [];
          for (const pid in matchPlayerStats) {
              const stat = matchPlayerStats[pid];
              const player = players.find(p => p.id === pid);
              if (player && stat.present) {
                  updates.push(supabase.from('players').update({ 
                      goals: (player.goals || 0) + stat.goals, 
                      matches_played: (player.matchesPlayed || 0) + 1 
                  }).eq('id', parseInt(pid)));
              }
          }
          if (updates.length) await Promise.all(updates);
      }

      await fetchData();
      setIsMatchResultModalOpen(false); 
      setIsSubmitting(false);
  };

