                </div>

                <div className="flex items-center justify-between gap-4">
                  <div className="flex flex-col items-center gap-3 w-1/3">
                    <img src={TEAM_LOGO_URL} className="w-16 h-16 drop-shadow-xl" />
                    <span className="text-[10px] font-black uppercase tracking-widest opacity-60">PESADÃO FC</span>
                    <input 
                      type="number" 
                      placeholder="?"
                      value={manualHomeScore} 
                      onChange={(e) => setManualHomeScore(e.target.value)} 
                      className="w-full text-center text-4xl font-black bg-white dark:bg-black/30 border-2 border-transparent focus:border-primary rounded-2xl p-4 shadow-inner outline-none transition-all placeholder:text-gray-300 dark:placeholder:text-gray-700" 
                    />
                  </div>
                  <div className="flex flex-col items-center justify-center w-1/6">
                    <span className="text-3xl font-black opacity-20 italic">VS</span>
                  </div>
                  <div className="flex flex-col items-center gap-3 w-1/3">
                    <div className="w-16 h-16 rounded-full bg-white dark:bg-black/30 flex items-center justify-center overflow-hidden border-2 border-white/10 shadow-xl">
                      {selectedMatch.locationImg ? <img src={selectedMatch.locationImg} className="w-full h-full object-cover" /> : <span className="material-icons-outlined text-3xl opacity-30">sports_soccer</span>}
                    </div>
                    <span className="text-[10px] font-black uppercase tracking-widest opacity-60 truncate w-full text-center">{selectedMatch.opponent}</span>
                    <input 
                      type="number" 
                      placeholder="?"
                      value={manualAwayScore} 
                      onChange={(e) => setManualAwayScore(e.target.value)} 
                      className="w-full text-center text-4xl font-black bg-white dark:bg-black/30 border-2 border-transparent focus:border-primary rounded-2xl p-4 shadow-inner outline-none transition-all placeholder:text-gray-300 dark:placeholder:text-gray-700" 
                    />
                  </div>
                </div>
              </div>

              <div className="px-8 py-6 space-y-8 max-h-[45vh] overflow-y-auto scrollbar-hide bg-gray-50/50 dark:bg-black/10">
                <div className="flex flex-col gap-4">
                  <div className="flex justify-between items-end">
                    <label className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Súmula de Atletas</label>
                    <span className="text-[9px] font-bold opacity-40 uppercase">Selecione quem jogou</span>
                  </div>
                  <div className="grid grid-cols-1 gap-3">
                    {players.filter(p => p.status === 'active').map(p => {
                      const stat = matchPlayerStats[p.id] || { goals: 0, present: false };
                      return (
                        <div 
                          key={p.id} 
                          onClick={() => toggleMatchPresence(p.id)}
                          className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all cursor-pointer ${stat.present ? 'bg-white dark:bg-gray-800 border-primary shadow-lg scale-[1.02]' : 'bg-transparent border-gray-100 dark:border-gray-800 opacity-60 hover:opacity-100'}`}
                        >
                          <div className="flex items-center gap-4">
                            <div className="relative">
                              <img src={p.photoUrl} className="w-14 h-14 rounded-full object-cover object-top border-2 border-white dark:border-gray-700 shadow-md" />
                              {stat.present && <div className="absolute -top-1 -right-1 bg-primary text-white w-5 h-5 rounded-full flex items-center justify-center border-2 border-white dark:border-gray-800"><span className="material-icons-outlined text-[10px]">check</span></div>}
                            </div>
                            <div className="flex flex-col">
                              <span className="text-xs font-black uppercase italic tracking-tighter">{p.name}</span>
                              <span className="text-[9px] font-bold opacity-40 uppercase">#{p.jerseyNumber} • {p.position}</span>
                            </div>
                          </div>
                          {stat.present && (
                            <div className="flex items-center gap-3 bg-gray-100 dark:bg-black/30 p-1.5 rounded-xl border border-white/10" onClick={(e) => e.stopPropagation()}>
