                                <span className="text-lg font-black leading-none">{stat.goals}</span>
                                <span className="text-[7px] font-black uppercase opacity-40">GOLS</span>
                              </div>
                              <button onClick={() => updateMatchStat(p.id, 1)} className="w-8 h-8 flex items-center justify-center bg-primary text-white rounded-lg text-lg font-black shadow-lg hover:brightness-110 transition-all">+</button>
                            </div>
                          )}
