                    </div>
                    <button onClick={() => {setAddMode('match'); setIsAddModalOpen(true);}} className="hidden md:flex bg-primary text-white px-4 py-2 rounded-xl font-bold text-sm shadow-lg shadow-primary/20 whitespace-nowrap">Novo Jogo</button>
                </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
