                    <div key={m.id} className={`relative rounded-2xl overflow-hidden flex flex-col transition-all duration-300 ${matchViewMode === 'upcoming' ? 'bg-gradient-to-br from-primary to-orange-500 text-white' : 'bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-800 shadow-sm'}`}>
