                  <div className="absolute -top-1 -right-1 bg-blue-500 text-white w-5 h-5 rounded-full flex items-center justify-center border-2 border-surface-light dark:border-surface-dark shadow-sm">
                    <span className="material-icons-outlined text-[10px]">history</span>
                  </div>
                </>
              ) : (
                <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-black/20 flex items-center justify-center"><span className="material-icons-outlined opacity-20">person</span></div>
              )}
            </div>
            <div className="flex-1">
              <span className="text-[9px] font-black uppercase tracking-widest text-muted-light block">Participações</span>
              <h4 className="text-xs font-black uppercase italic tracking-tighter truncate max-w-[100px] mt-1">{mostMatches ? mostMatches.name : '---'}</h4>
              <p className="text-xl font-black text-blue-500 leading-none mt-1">{mostMatches ? mostMatches.matchesPlayed : 0} <span className="text-[8px] font-bold opacity-40 uppercase">Jogos</span></p>
            </div>
            <button onClick={() => { setRankingType('matches'); setIsRankingModalOpen(true); }} className="mt-3 text-[8px] font-black uppercase tracking-widest bg-gray-100 dark:bg-black/30 px-3 py-1.5 rounded-full hover:bg-blue-500 hover:text-white transition-all">Ver Ranking</button>
          </div>
        </div>

        <div className="space-y-6">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <h3 className="text-xl font-bold flex items-center gap-2">Desempenho por Atleta</h3>
            <div className="relative w-full md:w-64">
              <input 
                type="text" 
                placeholder="Filtrar elenco..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-800 rounded-full px-4 py-2 text-sm font-bold pl-10 focus:ring-2 focus:ring-primary/20 outline-none transition-all" 
              />
              <span className="material-icons-outlined absolute left-3 top-1/2 -translate-y-1/2 text-muted-light text-sm">search</span>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredPlayers.map(p => (
              <div 
                key={p.id} 
                onClick={() => { setSelectedPlayerForDetail(p); setIsPlayerDetailModalOpen(true); }}
