                 <button onClick={() => setCurrentTab('stats')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${currentTab === 'stats' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Jogadores</button>
             </nav>
             <button onClick={toggleTheme} className="w-10 h-10 rounded-full bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-700 flex items-center justify-center hover:text-primary transition-colors"><span className="material-icons-outlined">{theme === 'dark' ? 'light_mode' : 'dark_mode'}</span></button>
        </div>

        <main className="max-w-7xl mx-auto">
             {currentTab === 'financial' && renderFinancial()}
             {currentTab === 'matches' && renderMatches()}
             {currentTab === 'stats' && renderStats()}
        </main>

        <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-surface-light/90 dark:bg-surface-dark/90 backdrop-blur-xl border-t border-gray-200 dark:border-gray-800 p-2 z-50 flex justify-around items-center safe-area-bottom pb-4 shadow-lg">
             <button onClick={() => setCurrentTab('financial')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg ${currentTab === 'financial' ? 'text-primary' : 'text-muted-light'}`}><span className="material-icons-outlined mb-1 text-2xl">attach_money</span><span className="text-[10px] font-bold uppercase">Financeiro</span></button>
             <button onClick={() => setCurrentTab('matches')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg ${currentTab === 'matches' ? 'text-primary' : 'text-muted-light'}`}><span className="material-icons-outlined mb-1 text-2xl">sports_soccer</span><span className="text-[10px] font-bold uppercase">Jogos</span></button>
             <button onClick={() => setCurrentTab('stats')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg ${currentTab === 'stats' ? 'text-primary' : 'text-muted-light'}`}><span className="material-icons-outlined mb-1 text-2xl">groups</span><span className="text-[10px] font-bold uppercase">Jogadores</span></button>
        </nav>

        {/* MODAL RANKING COMPLETO */}
        {isRankingModalOpen && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/70 backdrop-blur-md animate-fade-in">
            <div className="bg-surface-light dark:bg-surface-dark w-full max-w-sm rounded-3xl border border-gray-200 dark:border-gray-800 overflow-hidden shadow-2xl">
              <div className="p-6 border-b border-gray-100 dark:border-gray-800 flex justify-between items-center">
                <h3 className="font-black uppercase tracking-widest text-xs italic">Ranking: {rankingType === 'goals' ? 'Artilheiros' : 'Participações'}</h3>
                <button onClick={() => setIsRankingModalOpen(false)} className="material-icons-outlined opacity-40">close</button>
              </div>
              <div className="p-6 space-y-4">
                {(rankingType === 'goals' ? topScorers : topAppearances).slice(0, 3).map((p, i) => (
                  <div key={p.id} className="flex items-center justify-between p-3 rounded-2xl bg-gray-50 dark:bg-black/20">
                    <div className="flex items-center gap-3">
                      <span className={`text-xl font-black italic ${i === 0 ? 'text-yellow-500' : i === 1 ? 'text-gray-400' : 'text-orange-500'}`}>{i+1}º</span>
                      <img src={p.photoUrl} className="w-10 h-10 rounded-full object-cover object-top" />
                      <span className="text-xs font-bold">{p.name}</span>
                    </div>
                    <span className="text-sm font-black text-primary">{rankingType === 'goals' ? p.goals : p.matchesPlayed}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* MODAL DETALHE DO JOGADOR / HISTÓRICO */}
        {isPlayerDetailModalOpen && selectedPlayerForDetail && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-xl animate-fade-in">
            <div className="bg-surface-light dark:bg-surface-dark w-full max-w-md rounded-[3rem] border border-gray-200 dark:border-gray-800 overflow-hidden shadow-2xl">
              <div className="relative p-8 flex flex-col items-center">
                <button onClick={() => setIsPlayerDetailModalOpen(false)} className="absolute top-8 right-8 w-10 h-10 rounded-full bg-black/5 dark:bg-white/5 flex items-center justify-center hover:bg-black/10 transition-colors"><span className="material-icons-outlined">close</span></button>
                <div className="w-40 h-40 md:w-48 md:h-48 relative mb-6">
