                  </div>
                  <div className="absolute -bottom-2 -right-2 bg-primary text-white font-black text-2xl px-4 py-2 rounded-2xl shadow-lg leading-none">#{selectedPlayerForDetail.jerseyNumber}</div>
                </div>
                <div className="text-center mb-8">
                  <h3 className="text-3xl font-black uppercase italic tracking-tighter leading-none mb-1">{selectedPlayerForDetail.name}</h3>
                  <span className="text-[10px] font-black uppercase tracking-[0.4em] text-primary">{selectedPlayerForDetail.position}</span>
                </div>
                <div className="grid grid-cols-2 gap-4 w-full mb-8">
                  <div className="bg-gray-100 dark:bg-black/20 p-5 rounded-[2rem] text-center border border-gray-100 dark:border-gray-800">
