                    <span className="text-3xl font-black leading-none block">{selectedPlayerForDetail.matchesPlayed}</span>
                    <p className="text-[8px] font-black uppercase opacity-40 tracking-widest mt-2">Partidas</p>
                  </div>
                </div>
              </div>
              <div className="p-8 border-t border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-black/20">
