        {/* MODAL DE RESULTADO DA PARTIDA - REESTRUTURADO */}
        {isMatchResultModalOpen && selectedMatch && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in overflow-y-auto">
            <div className="bg-surface-light dark:bg-surface-dark w-full max-w-2xl my-auto rounded-[2.5rem] border border-gray-200 dark:border-gray-800 overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">

              {/* Header Placar */}
