                                >
                                    <div className="flex items-center gap-3">
                                        <div className="relative">
                                            <img src={player.photoUrl} className="w-10 h-10 rounded-full object-cover border-2 border-white dark:border-gray-800" />
                                            <button 
                                                onClick={() => toggleMatchPresence(player.id)}
                                                className={`absolute -bottom-1 -right-1 w-5 h-5 rounded-full flex items-center justify-center border-2 border-surface-light dark:border-surface-dark transition-all ${stat.present ? 'bg-green-500 text-white' : 'bg-gray-300 dark:bg-gray-700 text-transparent'}`}
                                            >
