                  <h3 className="text-lg font-black italic uppercase tracking-tight">Relatório de Jogo</h3>
                  <button onClick={() => setIsMatchResultModalOpen(false)} className="material-icons-outlined opacity-40 hover:opacity-100">close</button>
                </div>

                <div className="flex items-center justify-between max-w-sm mx-auto">
                  <div className="flex flex-col items-center gap-2 w-1/3">
                    <img src={TEAM_LOGO_URL} className="w-12 h-12 object-contain" />
                    <input 
                      type="number" 
                      value={manualHomeScore} 
                      onChange={(e) => setManualHomeScore(e.target.value)} 
                      className="w-full text-center text-3xl font-black bg-white dark:bg-black/30 rounded-xl p-2 border border-transparent focus:border-primary outline-none" 
                    />
                  </div>
                  <span className="text-xl font-black opacity-20 italic">VS</span>
                  <div className="flex flex-col items-center gap-2 w-1/3">
                    <div className="w-12 h-12 rounded-full bg-gray-200 dark:bg-black/40 flex items-center justify-center border border-gray-400 dark:border-gray-700 overflow-hidden">
                      {selectedMatch.locationImg ? <img src={selectedMatch.locationImg} className="w-full h-full object-cover" /> : <span className="material-icons-outlined opacity-20 text-xl">sports_soccer</span>}
                    </div>
                    <input 
                      type="number" 
                      value={manualAwayScore} 
                      onChange={(e) => setManualAwayScore(e.target.value)} 
                      className="w-full text-center text-3xl font-black bg-white dark:bg-black/30 rounded-xl p-2 border border-transparent focus:border-primary outline-none" 
                    />
                  </div>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto p-5 md:p-6 space-y-4 scrollbar-hide">
                <div>
                    <h4 className="text-[11px] font-bold uppercase text-primary mb-3 flex items-center gap-2">
                        Presença e Gols
                    </h4>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                        {players.filter(p => p.status === 'active').map(player => {
                            const stat = matchPlayerStats[player.id] || { goals: 0, present: false };
                            return (
                                <div 
                                    key={player.id} 
                                    onClick={() => toggleMatchPresence(player.id)}
                                    className={`flex items-center justify-between p-2.5 rounded-xl border transition-all cursor-pointer ${
                                        stat.present 
                                        ? 'bg-primary/10 border-primary/50' 
                                        : 'bg-gray-50 dark:bg-black/20 border-transparent opacity-60 grayscale'
                                    }`}
                                >
                                    <div className="flex items-center gap-3">
                                        <div className="relative">
                                            <img src={player.photoUrl} className="w-9 h-9 rounded-full object-cover border border-white dark:border-gray-800" />
                                            {stat.present && (
                                                <div className="absolute -top-1 -right-1 bg-green-500 text-white w-4 h-4 rounded-full flex items-center justify-center border border-surface-light dark:border-surface-dark">
                                                    <span className="material-icons-outlined text-[8px] font-bold">check</span>
                                                </div>
                                            )}
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[11px] font-bold truncate max-w-[90px]">{player.name}</span>
                                            <span className="text-[8px] font-bold opacity-40 uppercase">{player.position}</span>
                                        </div>
                                    </div>

                                    {stat.present && (
                                        <div className="flex items-center gap-1 bg-white dark:bg-black/30 rounded-lg p-0.5 border border-black/5">
                                            <button onClick={(e) => updateMatchStat(player.id, -1, e)} className="w-6 h-6 flex items-center justify-center hover:text-primary transition-colors"><span className="material-icons-outlined text-sm">remove</span></button>
                                            <div className="flex flex-col items-center min-w-[20px]">
                                                <span className="text-[10px] font-black">{stat.goals}</span>
