                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div>
                    <h4 className="text-[11px] font-bold uppercase text-primary mb-2">Comentários</h4>
                    <textarea 
                        value={matchComments} 
                        onChange={(e) => setMatchComments(e.target.value)}
                        placeholder="Destaques do jogo..."
                        className="w-full h-20 bg-gray-50 dark:bg-black/30 border-0 rounded-xl p-3 text-xs font-medium focus:ring-2 focus:ring-primary/20 outline-none resize-none placeholder:opacity-30"
                    />
