                  <img src={mostMatches.photoUrl} className="w-16 h-16 rounded-full object-cover object-top border-2 border-blue-500 shadow-md" />
                  <div className="absolute -top-1 -right-1 bg-blue-500 text-white w-5 h-5 rounded-full flex items-center justify-center border-2 border-surface-light dark:border-surface-dark shadow-sm">
                    <span className="material-icons-outlined text-[10px]">history</span>
                  </div>
                </>
              ) : (
                <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-black/20 flex items-center justify-center"><span className="material-icons-outlined opacity-20">person</span></div>
              )}
            </div>
            <div className="flex-1">
              <span className="text-[9px] font-black uppercase tracking-widest text-muted-light block">Participações</span>
              <h4 className="text-xs font-black uppercase italic tracking-tighter truncate max-w-[100px] mt-1">{mostMatches ? mostMatches.name : '---'}</h4>
              <p className="text-xl font-black text-blue-500 leading-none mt-1">{mostMatches ? mostMatches.matchesPlayed : 0} <span className="text-[8px] font-bold opacity-40 uppercase">Jogos</span></p>
            </div>
            <button onClick={() => { setRankingType('matches'); setIsRankingModalOpen(true); }} className="mt-3 text-[8px] font-black uppercase tracking-widest bg-gray-100 dark:bg-black/30 px-3 py-1.5 rounded-full hover:bg-blue-500 hover:text-white transition-all">Ver Ranking</button>
          </div>
        </div>

        <div className="space-y-6">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <h3 className="text-xl font-bold flex items-center gap-2">Desempenho por Atleta</h3>
            <div className="relative w-full md:w-64">
              <input 
                type="text" 
                placeholder="Filtrar elenco..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-800 rounded-full px-4 py-2 text-sm font-bold pl-10 focus:ring-2 focus:ring-primary/20 outline-none transition-all" 
              />
              <span className="material-icons-outlined absolute left-3 top-1/2 -translate-y-1/2 text-muted-light text-sm">search</span>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredPlayers.map(p => (
              <div 
                key={p.id} 
                onClick={() => { setSelectedPlayerForDetail(p); setIsPlayerDetailModalOpen(true); }}
                className={`relative group h-[280px] md:h-[340px] bg-gradient-to-b from-white to-gray-200 dark:from-[#1a1d22] dark:to-[#0f1115] rounded-[2.5rem] border ${p.status === 'injured' ? 'border-orange-500/50' : 'border-gray-200 dark:border-gray-800'} transition-all duration-500 hover:-translate-y-2 hover:shadow-2xl overflow-hidden flex flex-col justify-end cursor-pointer`}
              >
                <div className="absolute top-0 left-0 w-full px-6 py-6 flex justify-between items-start z-20 pointer-events-none">
                  <img src={TEAM_LOGO_URL} className="w-10 h-10 object-contain opacity-80" />
                  <span className="font-display font-black text-5xl text-gray-300 dark:text-gray-800 group-hover:text-primary/20 transition-colors">{p.jerseyNumber}</span>
                </div>
                <div className="absolute bottom-14 left-0 right-0 h-4/5 z-10 flex items-end justify-center">
                  <img src={p.photoUrl} className={`h-full w-auto max-w-[120%] object-cover object-top transition-all duration-500 ${p.status === 'injured' ? 'grayscale opacity-60' : ''}`} style={{ WebkitMaskImage: 'linear-gradient(to bottom, black 70%, transparent 100%)' }} />
                  <div className="absolute inset-0 bg-gradient-to-t from-gray-200 dark:from-[#0f1115] via-transparent to-transparent pointer-events-none"></div>
                </div>
                <div className="relative z-20 w-full text-center mb-28 md:mb-24 px-2">
                  <span className="block text-3xl md:text-5xl font-black uppercase text-white leading-none tracking-tighter truncate drop-shadow-lg">{p.name.split(' ')[0]}</span>
                </div>
                <div className="absolute bottom-0 w-full px-6 z-20 bg-gradient-to-t from-black/90 to-transparent pt-10 pb-6">
                  <div className="flex items-center justify-center gap-8 border-t border-white/20 pt-4 text-center">
                    <div className="flex flex-col"><span className="text-[8px] uppercase font-black text-gray-400 mb-1 tracking-widest">Gols</span><span className="font-black text-white text-lg leading-none">{p.goals}</span></div>
                    <div className="flex flex-col"><span className="text-[8px] uppercase font-black text-primary mb-1 tracking-widest">Posição</span><span className="font-black text-white text-lg leading-none">{p.position}</span></div>
