};

export default App;

import React, { useState, useEffect, useMemo, ChangeEvent } from 'react';
import { Player, DbPlayer, Match, DbMatch } from './types';
import { getSupabase, saveSupabaseKey, SUPABASE_URL } from './supabaseClient';

const DEFAULT_FEE = 40;
const TEAM_LOGO_URL = 'https://i.imgur.com/GSj0ZPy.png'; // Ícone transparente (Interno)
const PWA_LOGO_URL = 'https://i.imgur.com/CxbCPR5.png';   // Ícone PWA (Sólido/Download)

const App: React.FC = () => {
  // --- PWA INSTALL LOGIC ---
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showInstallPrompt, setShowInstallPrompt] = useState(false);
  const [isIOS, setIsIOS] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const checkMobile = () => {
      const isMobileSize = window.innerWidth < 1024;
      const isMobileUA = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
      return isMobileSize || isMobileUA;
    };

    const mobileStatus = checkMobile();
    setIsMobile(mobileStatus);

    const ios = /iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream;
    setIsIOS(ios);

    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
      if (mobileStatus && !window.matchMedia('(display-mode: standalone)').matches) {
        setShowInstallPrompt(true);
      }
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    if (window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone) {
      setShowInstallPrompt(false);
    }

    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, [isMobile]);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setDeferredPrompt(null);
      setShowInstallPrompt(false);
    }
  };

  // --- STATE ---
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [currentTab, setCurrentTab] = useState<'financial' | 'matches' | 'stats'>('matches'); 

  const [players, setPlayers] = useState<Player[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  const [apiKeyModalOpen, setApiKeyModalOpen] = useState(false);
  const [isConnected, setIsConnected] = useState(false);

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [addMode, setAddMode] = useState<'player' | 'match'>('player');

  const [isEditPlayerModalOpen, setIsEditPlayerModalOpen] = useState(false);
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [editPlayerName, setEditPlayerName] = useState('');
  const [editPlayerNumber, setEditPlayerNumber] = useState('');
  const [editPlayerPosition, setEditPlayerPosition] = useState('');
  const [editPlayerPhoto, setEditPlayerPhoto] = useState<string | null>(null);

  const [isMatchResultModalOpen, setIsMatchResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);
  const [manualHomeScore, setManualHomeScore] = useState<number | string>(0);
  const [manualAwayScore, setManualAwayScore] = useState<number | string>(0);
  const [matchComments, setMatchComments] = useState('');
  const [matchPlayerStats, setMatchPlayerStats] = useState<Record<string, {goals: number, present: boolean}>>({});

  const [matchViewMode, setMatchViewMode] = useState<'upcoming' | 'history'>('upcoming');
  const [searchQuery, setSearchQuery] = useState('');

  const [newPlayerName, setNewPlayerName] = useState('');
  const [newPlayerNumber, setNewPlayerNumber] = useState('');
  const [newPlayerPhoto, setNewPlayerPhoto] = useState<string | null>(null);
  const [newPlayerPosition, setNewPlayerPosition] = useState('MEI');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [newMatchOpponent, setNewMatchOpponent] = useState('');
  const [newMatchLocation, setNewMatchLocation] = useState('');
  const [newMatchDate, setNewMatchDate] = useState(new Date().toISOString().split('T')[0]);
  const [newMatchTime, setNewMatchTime] = useState('');
  const [newMatchLocationImg, setNewMatchLocationImg] = useState<string | null>(null);

  const [isPlayerDetailModalOpen, setIsPlayerDetailModalOpen] = useState(false);
  const [selectedPlayerForDetail, setSelectedPlayerForDetail] = useState<Player | null>(null);
  const [isRankingModalOpen, setIsRankingModalOpen] = useState(false);
  const [rankingType, setRankingType] = useState<'goals' | 'matches'>('goals');

  // List of players whose stats should be zeroed in popups (kept as per request)
  const playersToZero = ["Arroz", "Caique", "Dodô", "Filão", "Jé", "Léo", "Pelé", "Tarcísio", "Vi"];

  // --- INITIALIZATION ---
  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const supabase = getSupabase();
    if (!supabase) {
      setApiKeyModalOpen(true);
      setLoading(false);
      return;
    }
    setIsConnected(true);
    fetchData();

    const channelPlayers = supabase.channel('realtime-players')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'players' }, () => fetchData())
      .subscribe();

    const channelMatches = supabase.channel('realtime-matches')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, () => fetchData())
      .subscribe();

    return () => {
      supabase.removeChannel(channelPlayers);
      supabase.removeChannel(channelMatches);
    };
  }, []);

  const fetchData = async () => {
    const supabase = getSupabase();
    if (!supabase) return;

    try {
      const { data: dataPlayers } = await supabase.from('players').select('*').order('name', { ascending: true });
      if (dataPlayers) {
        setPlayers(dataPlayers.map((p: any) => ({
          id: p.id.toString(),
          name: p.name,
          photoUrl: p.photo_url || 'https://via.placeholder.com/150',
          isPaid: false, 
          paymentDate: undefined,
          value: p.value,
          jerseyNumber: p.jersey_number,
          status: (p.status === 'injured' ? 'injured' : 'active') as 'active' | 'injured',
          paymentHistory: parsePaymentHistory(p.payment_date),
          position: p.position || 'MEI',
          goals: p.goals || 0,
          matchesPlayed: p.matches_played || 0,
          lastPlayedDate: p.last_played_date,
          overall: p.overall || 75
        })));
      }

      const { data: dataMatches } = await supabase.from('matches').select('*').order('date', { ascending: true });
      if (dataMatches) {
        setMatches(dataMatches.map((m: DbMatch) => ({
          id: m.id.toString(),
          opponent: m.opponent,
          locationImg: m.location_img,
          location: m.location || '',
          date: m.date,
          time: m.time,
          homeScore: m.home_score,
          awayScore: m.away_score,
          result: m.result as any,
          isFinished: m.is_finished,
          lineup: m.lineup || undefined,
          comments: m.comments || ''
        })));
      }
    } catch (error) {
      console.error("Erro ao buscar dados:", error);
    } finally {
      setLoading(false);
    }
  };

  const parsePaymentHistory = (dateStr: string | null): Record<string, string> => {
    if (!dateStr) return {};
    try {
        const parsed = JSON.parse(dateStr);
        return (typeof parsed === 'object' && parsed !== null) ? parsed : {};
    } catch (e) { return {}; }
  };

  const getMonthKey = (date: Date) => {
    const m = (date.getMonth() + 1).toString().padStart(2, '0');
    const y = date.getFullYear();
    return `${m}-${y}`;
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  const changeMonth = (increment: number) => {
    const newDate = new Date(selectedDate);
    newDate.setMonth(newDate.getMonth() + increment);
    setSelectedDate(newDate);
  };

  // Completed financialStats logic
  const financialStats = useMemo(() => {
    const currentMonthKey = getMonthKey(selectedDate);
    const playersView = players.map(p => ({ ...p, isPaid: !!p.paymentHistory[currentMonthKey] }));
    const active = playersView.filter(p => p.status === 'active' || p.isPaid);
    let collected = playersView.reduce((acc, p) => acc + (p.isPaid ? p.value : 0), 0);
    if (selectedDate.getMonth() === 0) collected += 130;
    const potential = active.reduce((acc, p) => acc + p.value, 0);
    const paid = playersView.filter(p => p.isPaid).length;
    return { 
      collected, 
      potential, 
      paid, 
      count: active.length, 
      progress: active.length > 0 ? (paid / active.length) * 100 : 0 
    };
  }, [players, selectedDate]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-900 text-white p-4 text-center">
        <div>
          <img src={TEAM_LOGO_URL} alt="Logo" className="w-24 h-24 mx-auto mb-6 animate-pulse" />
          <p className="text-xl font-bold italic tracking-wider">CARREGANDO DADOS...</p>
        </div>
      </div>
    );
  }

  // Final component structure with default export
  return (
    <div className={`min-h-screen ${theme === 'dark' ? 'bg-gray-950 text-white' : 'bg-gray-50 text-gray-900'}`}>
      <header className="p-4 flex justify-between items-center bg-white dark:bg-gray-900 shadow-md sticky top-0 z-40">
        <div className="flex items-center gap-2">
          <img src={TEAM_LOGO_URL} alt="Team Logo" className="w-10 h-10 object-contain" />
          <h1 className="text-xl font-black italic tracking-tighter">PESADÃO FC</h1>
        </div>
        <div className="flex gap-2">
          <button onClick={toggleTheme} className="p-2 rounded-xl bg-gray-100 dark:bg-gray-800">
            {theme === 'dark' ? '☀️' : '🌙'}
          </button>
        </div>
      </header>

      <main className="p-4 pb-24 max-w-lg mx-auto">
        {currentTab === 'matches' && (
          <section className="space-y-4">
            <h2 className="text-2xl font-bold italic">PARTIDAS</h2>
            <div className="flex gap-2 mb-4">
              <button 
                onClick={() => setMatchViewMode('upcoming')}
                className={`flex-1 py-2 rounded-lg font-bold text-sm ${matchViewMode === 'upcoming' ? 'bg-blue-600 text-white' : 'bg-gray-200 dark:bg-gray-800'}`}
              >
                Próximas
              </button>
              <button 
                onClick={() => setMatchViewMode('history')}
                className={`flex-1 py-2 rounded-lg font-bold text-sm ${matchViewMode === 'history' ? 'bg-blue-600 text-white' : 'bg-gray-200 dark:bg-gray-800'}`}
              >
                Histórico
              </button>
            </div>

            <div className="space-y-3">
              {matches.filter(m => matchViewMode === 'history' ? m.isFinished : !m.isFinished).map(match => (
                <div key={match.id} className="p-4 rounded-2xl bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 shadow-sm">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="text-xs font-bold text-gray-500 uppercase tracking-widest">{match.date} • {match.time}</p>
                      <h3 className="text-lg font-bold mt-1">vs {match.opponent}</h3>
                    </div>
                    {match.isFinished && (
                      <div className="text-right">
                        <p className="text-2xl font-black">{match.homeScore} - {match.awayScore}</p>
                        <p className={`text-xs font-bold uppercase ${match.result === 'win' ? 'text-green-500' : match.result === 'loss' ? 'text-red-500' : 'text-gray-400'}`}>
                          {match.result === 'win' ? 'Vitória' : match.result === 'loss' ? 'Derrota' : 'Empate'}
                        </p>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {currentTab === 'financial' && (
          <section className="space-y-6">
            <div className="flex items-center justify-between">
              <h2 className="text-2xl font-bold italic">FINANCEIRO</h2>
              <div className="flex items-center gap-3">
                <button onClick={() => changeMonth(-1)} className="p-2">◀</button>
                <span className="font-bold text-sm">{getMonthKey(selectedDate)}</span>
                <button onClick={() => changeMonth(1)} className="p-2">▶</button>
              </div>
            </div>

            <div className="p-6 rounded-3xl bg-blue-600 text-white shadow-xl shadow-blue-500/20">
              <p className="text-sm font-bold opacity-80 uppercase tracking-widest">Saldo Mensal</p>
              <h3 className="text-4xl font-black mt-1">R$ {financialStats.collected}</h3>
              <div className="mt-6">
                <div className="flex justify-between text-xs font-bold mb-2">
                  <span>Progresso da Arrecadação</span>
                  <span>{Math.round(financialStats.progress)}%</span>
                </div>
                <div className="w-full h-3 bg-white/20 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-white transition-all duration-700 ease-out"
                    style={{ width: `${financialStats.progress}%` }}
                  />
                </div>
              </div>
              <p className="mt-4 text-xs opacity-80 text-right">Meta Total: R$ {financialStats.potential}</p>
            </div>
          </section>
        )}

        {currentTab === 'stats' && (
          <section className="space-y-6">
            <h2 className="text-2xl font-bold italic">ESTATÍSTICAS</h2>
            <div className="grid grid-cols-2 gap-4">
              <div className="p-4 rounded-2xl bg-white dark:bg-gray-900 border dark:border-gray-800 shadow-sm">
                <p className="text-xs font-bold text-gray-500 uppercase">Artilheiro</p>
                <p className="text-xl font-bold mt-1">
                  {players.reduce((prev, current) => (prev.goals > current.goals) ? prev : current, players[0])?.name || '-'}
                </p>
              </div>
              <div className="p-4 rounded-2xl bg-white dark:bg-gray-900 border dark:border-gray-800 shadow-sm">
                <p className="text-xs font-bold text-gray-500 uppercase">Presenças</p>
                <p className="text-xl font-bold mt-1">
                  {players.reduce((prev, current) => (prev.matchesPlayed > current.matchesPlayed) ? prev : current, players[0])?.matchesPlayed || 0}
                </p>
              </div>
            </div>
          </section>
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 dark:bg-gray-900/90 backdrop-blur-lg border-t dark:border-gray-800 flex justify-around p-3 z-50">
        <button 
          onClick={() => setCurrentTab('matches')} 
          className={`flex flex-col items-center gap-1 transition-colors ${currentTab === 'matches' ? 'text-blue-500' : 'text-gray-400'}`}
        >
          <div className={`w-12 h-1 mb-1 rounded-full ${currentTab === 'matches' ? 'bg-blue-500' : 'bg-transparent'}`} />
          <span className="text-[10px] font-black uppercase tracking-tighter">Jogos</span>
        </button>
        <button 
          onClick={() => setCurrentTab('financial')} 
          className={`flex flex-col items-center gap-1 transition-colors ${currentTab === 'financial' ? 'text-blue-500' : 'text-gray-400'}`}
        >
          <div className={`w-12 h-1 mb-1 rounded-full ${currentTab === 'financial' ? 'bg-blue-500' : 'bg-transparent'}`} />
          <span className="text-[10px] font-black uppercase tracking-tighter">Caixa</span>
        </button>
        <button 
          onClick={() => setCurrentTab('stats')} 
          className={`flex flex-col items-center gap-1 transition-colors ${currentTab === 'stats' ? 'text-blue-500' : 'text-gray-400'}`}
        >
          <div className={`w-12 h-1 mb-1 rounded-full ${currentTab === 'stats' ? 'bg-blue-500' : 'bg-transparent'}`} />
          <span className="text-[10px] font-black uppercase tracking-tighter">Stats</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

