                  <div className="flex flex-col items-center gap-2 w-1/3">
                    <div className="w-12 h-12 rounded-full bg-gray-200 dark:bg-black/40 flex items-center justify-center border border-gray-400 dark:border-gray-700 overflow-hidden">
