          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in overflow-y-auto">
            <div className="bg-surface-light dark:bg-surface-dark w-full max-w-2xl my-auto rounded-[2rem] border border-gray-200 dark:border-gray-800 overflow-hidden shadow-2xl flex flex-col max-h-[95vh]">

              <div className="p-5 md:p-6 border-b border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-black/20 flex-shrink-0">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-black italic uppercase tracking-tight">Relatório de Jogo</h3>
                  <button onClick={() => setIsMatchResultModalOpen(false)} className="material-icons-outlined opacity-40 hover:opacity-100">close</button>
