                  <div className="bg-white dark:bg-black/20 p-3 rounded-2xl text-center border border-black/5">
                    <span className="text-xl font-black text-primary leading-none block">
                      {PLAYERS_TO_ZERO.includes(selectedPlayerForDetail.name) ? 0 : selectedPlayerForDetail.goals}
                    </span>
                    <p className="text-[8px] font-bold uppercase opacity-40 mt-1">Gols Totais</p>
