          </div>
        </div>

        <div className="space-y-6">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <h3 className="text-xl font-bold flex items-center gap-2">Desempenho por Atleta</h3>
            <div className="flex w-full md:w-auto items-center gap-2">
                <div className="relative flex-1 md:w-64">
                    <input 
                        type="text" 
                        placeholder="Filtrar elenco..." 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-800 rounded-full px-4 py-2 text-sm font-bold pl-10 focus:ring-2 focus:ring-primary/20 outline-none transition-all" 
                    />
                    <span className="material-icons-outlined absolute left-3 top-1/2 -translate-y-1/2 text-muted-light text-sm">search</span>
                </div>
                <button onClick={resetAllStats} className="bg-red-500/10 text-red-500 p-2 rounded-xl hover:bg-red-500 hover:text-white transition-all"><span className="material-icons-outlined">restart_alt</span></button>
