             <button onClick={() => setCurrentTab('matches')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg ${currentTab === 'matches' ? 'text-primary' : 'text-muted-light'}`}><span className="material-icons-outlined mb-1 text-2xl">sports_soccer</span><span className="text-[10px] font-bold uppercase">Jogos</span></button>
             <button onClick={() => setCurrentTab('stats')} className={`flex flex-col items-center justify-center w-full p-2 rounded-lg ${currentTab === 'stats' ? 'text-primary' : 'text-muted-light'}`}><span className="material-icons-outlined mb-1 text-2xl">groups</span><span className="text-[10px] font-bold uppercase">Jogadores</span></button>
        </nav>

        {/* MODAL RANKING COMPLETO */}
        {isRankingModalOpen && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/70 backdrop-blur-md animate-fade-in">
