                  {matches.filter(m => {
                    if (!m.isFinished || !m.lineup) return false;
                    const lineup = typeof m.lineup === 'string' ? JSON.parse(m.lineup) : m.lineup;
                    return lineup[selectedPlayerForDetail.id]?.present;
