                      <p className="text-[10px] font-bold uppercase opacity-30 italic">Nenhuma partida registrada na súmula.</p>
                    </div>
                  )}
                </div>
              </div>

              <div className="p-6 md:p-8 border-t border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-black/20">
