                  <img src={mostMatches.photoUrl} className="w-16 h-16 rounded-full object-cover object-top border-2 border-blue-500 shadow-md" />
                  <div className="absolute -top-1 -right-1 bg-blue-500 text-white w-5 h-5 rounded-full flex items-center justify-center border-2 border-surface-light dark:border-surface-dark shadow-sm">
                    <span className="material-icons-outlined text-[10px]">history</span>
                  </div>
