    setIsSubmitting(true);
    const supabase = getSupabase();
    if (supabase) {
        const fullPayload = { 
          name: newPlayerName, 
          photo_url: newPlayerPhoto || 'https://via.placeholder.com/150', 
          is_paid: false, 
          value: DEFAULT_FEE, 
          jersey_number: parseInt(newPlayerNumber) || 0, 
          status: 'active', 
          payment_date: JSON.stringify({}), 
          position: newPlayerPosition, 
          goals: 0, 
          matches_played: 0, 
          overall: 70 
        };
        const { error } = await supabase.from('players').insert([fullPayload]).select();

        if (error) {
          console.error("Erro ao adicionar jogador:", error);
          alert("Não foi possível salvar o jogador. Verifique sua conexão ou chaves do banco.");
        } else {
          await fetchData();
          setIsAddModalOpen(false);
          setNewPlayerName(''); 
          setNewPlayerNumber(''); 
