  const handleAddPlayer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlayerName.trim() || isSubmitting) return;
    setIsSubmitting(true);
    const supabase = getSupabase();
    if (supabase) {
        try {
          const fullPayload = { 
            name: newPlayerName, 
            photo_url: newPlayerPhoto || 'https://via.placeholder.com/150', 
            is_paid: false, 
            value: DEFAULT_FEE, 
            jersey_number: parseInt(newPlayerNumber) || 0, 
            status: 'active', 
            payment_date: JSON.stringify({}), 
            position: newPlayerPosition, 
            goals: 0, 
            matches_played: 0, 
            overall: 70 
          };

          // Removido .select() para evitar erros de RLS se as permissões de leitura forem restritas
          const { error } = await supabase.from('players').insert([fullPayload]);

          if (error) {
            console.error("Erro Supabase:", error);
            alert(`Erro ao salvar: ${error.message}`);
          } else {
            // Sucesso
            await fetchData();
            setNewPlayerName(''); 
            setNewPlayerNumber(''); 
            setNewPlayerPhoto(null);
