                        <div className="absolute top-3 right-3 z-30"><button onClick={(e) => deleteMatch(m.id, e)} className={`p-2 rounded-full hover:bg-black/10 ${matchViewMode === 'upcoming' ? 'text-white' : 'text-muted-light'}`}><span className="material-icons-outlined text-lg">delete_outline</span></button></div>
