                      <div className="flex flex-col text-right"><span className="text-[8px] uppercase font-black text-blue-400 mb-1 tracking-widest">Jogos</span><span className="font-black text-white text-lg leading-none">{p.matchesPlayed}</span></div>
                    </div>
                  </div>
                </div>
              );
            })}
