                  <button type="submit" className="w-full bg-primary text-white font-bold py-4 rounded-xl shadow-lg">Salvar Alterações</button>
                  <button type="button" onClick={() => setIsEditPlayerModalOpen(false)} className="w-full py-4 text-muted-light font-bold uppercase text-[10px] tracking-widest">Cancelar</button>
