                      <span className="text-xs font-bold">{p.name}</span>
                    </div>
                    <span className="text-sm font-black text-primary">
                      {rankingType === 'goals' ? p.goals : p.matchesPlayed}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

