    d.setDate(d.getDate() + (d.getDay() === 0 ? 0 : 7 - d.getDay()));
    d.setHours(0, 0, 0, 0);
    for (let i = 0; i < 12; i++) {
      dates.push(new Date(d));
      d.setDate(d.getDate() + 7);
    }
    return dates;
  }, []);

